// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity ^0.8.17;

import {Test} from "forge-std/Test.sol";
import {TokenUtils} from "src/utils/vendor/0xSplits/TokenUtils.sol";
import {SafeTransferLib} from "solady/utils/SafeTransferLib.sol";

/// @dev Minimal ERC20 mock with configurable decimals and a strict transfer
/// implementation (reverts on insufficient balance) so we can exercise
/// SafeTransferLib's failure paths through TokenUtils.
contract MockERC20 {
    string public name = "Mock Token";
    string public symbol = "MOCK";
    uint8 private immutable _decimalsValue;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    constructor(uint8 decimals_) {
        _decimalsValue = decimals_;
    }

    function decimals() external view returns (uint8) {
        return _decimalsValue;
    }

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        require(balanceOf[msg.sender] >= amount, "insufficient balance");
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(balanceOf[from] >= amount, "insufficient balance");
        require(allowance[from][msg.sender] >= amount, "insufficient allowance");
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

/// @dev Contract with no receive/fallback, used to force ETH transfer failures.
contract ETHRejecter {}

/// @dev Thin external wrapper so the library's internal functions are
/// callable/expect-revertable from the test contract like normal calls.
contract TokenUtilsHarness {
    function safeTransfer(address token, address to, uint256 amount) external {
        TokenUtils._safeTransfer(token, to, amount);
    }

    function decimalsOf(address token) external view returns (uint8) {
        return TokenUtils._decimals(token);
    }

    function balanceOf(address token, address addr) external view returns (uint256) {
        return TokenUtils._balanceOf(token, addr);
    }

    function isETH(address token) external pure returns (bool) {
        return TokenUtils._isETH(token);
    }

    receive() external payable {}
}

contract TokenUtilsTest is Test {
    TokenUtilsHarness internal harness;
    MockERC20 internal token;

    address internal alice = makeAddr("alice");
    address internal bob = makeAddr("bob");

    function setUp() public {
        harness = new TokenUtilsHarness();
        token = new MockERC20(6);
    }

    // ----------------------------------------------------------------
    // _isETH
    // ----------------------------------------------------------------

    function test_isETH_trueForZeroAddress() public {
        assertTrue(harness.isETH(address(0)));
        assertTrue(harness.isETH(TokenUtils.ETH_ADDRESS));
    }

    function test_isETH_falseForToken() public {
        assertFalse(harness.isETH(address(token)));
    }

    function testFuzz_isETH(address token_) public {
        vm.assume(token_ != address(0));
        assertFalse(harness.isETH(token_));
    }

    // ----------------------------------------------------------------
    // _decimals
    // ----------------------------------------------------------------

    function test_decimals_ETHReturns18() public {
        assertEq(harness.decimalsOf(TokenUtils.ETH_ADDRESS), 18);
    }

    function test_decimals_ERC20ReturnsTokenDecimals() public {
        assertEq(harness.decimalsOf(address(token)), 6);
    }

    function testFuzz_decimals_ERC20(uint8 decimals_) public {
        MockERC20 t = new MockERC20(decimals_);
        assertEq(harness.decimalsOf(address(t)), decimals_);
    }

    // ----------------------------------------------------------------
    // _balanceOf
    // ----------------------------------------------------------------

    function test_balanceOf_ETH() public {
        vm.deal(alice, 3 ether);
        assertEq(harness.balanceOf(TokenUtils.ETH_ADDRESS, alice), 3 ether);
    }

    function testFuzz_balanceOf_ETH(uint96 amount) public {
        vm.deal(alice, amount);
        assertEq(harness.balanceOf(TokenUtils.ETH_ADDRESS, alice), amount);
    }

    function test_balanceOf_ERC20() public {
        token.mint(alice, 500);
        assertEq(harness.balanceOf(address(token), alice), 500);
    }

    function testFuzz_balanceOf_ERC20(uint256 amount) public {
        token.mint(alice, amount);
        assertEq(harness.balanceOf(address(token), alice), amount);
    }

    // ----------------------------------------------------------------
    // _safeTransfer — ETH
    // ----------------------------------------------------------------

    function test_safeTransfer_ETH() public {
        vm.deal(address(harness), 5 ether);
        uint256 bobBalanceBefore = bob.balance;

        harness.safeTransfer(TokenUtils.ETH_ADDRESS, bob, 2 ether);

        assertEq(bob.balance, bobBalanceBefore + 2 ether);
        assertEq(address(harness).balance, 3 ether);
