    }
}

/// @notice Token whose approve() returns extra-long but valid bool-decodable data (first word decodes fine).
contract MockERC20ExtraReturnData {
    mapping(address => mapping(address => uint256)) public allowance;

    function approve(address spender, uint256 amount) external returns (bool, uint256) {
        allowance[msg.sender][spender] = amount;
        return (true, 42);
    }
}

/// @notice Non-contract address (no code) to exercise the low-level call failure path.
contract ERC20SafeApproveLibTest is Test {
    address internal constant SPENDER = address(0xBEEF);
    uint256 internal constant AMOUNT = 1_000e18;

    address internal eoa = address(0x1234);

    /* ------------------------------------------------------------------ */
    /*                              SUCCESS                              */
    /* ------------------------------------------------------------------ */

    function test_SafeApprove_StandardToken_Succeeds() public {
        MockERC20Standard token = new MockERC20Standard();

        ERC20SafeApproveLib.safeApprove(address(token), SPENDER, AMOUNT);

        assertEq(token.allowance(address(this), SPENDER), AMOUNT);
    }

    function test_SafeApprove_NoReturnValueToken_Succeeds() public {
        MockERC20NoReturn token = new MockERC20NoReturn();

        ERC20SafeApproveLib.safeApprove(address(token), SPENDER, AMOUNT);

        assertEq(token.allowance(address(this), SPENDER), AMOUNT);
    }

