        ERC20SafeApproveLib.safeApprove(address(token), SPENDER, AMOUNT);

        assertEq(token.allowance(address(this), SPENDER), AMOUNT);
    }

    function test_SafeApprove_ZeroAmount_Succeeds() public {
        MockERC20Standard token = new MockERC20Standard();

        ERC20SafeApproveLib.safeApprove(address(token), SPENDER, 0);

        assertEq(token.allowance(address(this), SPENDER), 0);
    }

    function test_SafeApprove_CanBeCalledTwice_ReApprove() public {
        MockERC20Standard token = new MockERC20Standard();

        ERC20SafeApproveLib.safeApprove(address(token), SPENDER, AMOUNT);
        assertEq(token.allowance(address(this), SPENDER), AMOUNT);

        ERC20SafeApproveLib.safeApprove(address(token), SPENDER, AMOUNT * 2);
        assertEq(token.allowance(address(this), SPENDER), AMOUNT * 2);

        ERC20SafeApproveLib.safeApprove(address(token), SPENDER, 0);
        assertEq(token.allowance(address(this), SPENDER), 0);
    }

    function testFuzz_SafeApprove_StandardToken_Succeeds(address spender, uint256 amount) public {
        vm.assume(spender != address(0));
        MockERC20Standard token = new MockERC20Standard();

        ERC20SafeApproveLib.safeApprove(address(token), spender, amount);

        assertEq(token.allowance(address(this), spender), amount);
    }

    /* ------------------------------------------------------------------ */
    /*                              FAILURE                              */
    /* ------------------------------------------------------------------ */

    function test_SafeApprove_RevertsWhen_TokenReturnsFalse() public {
        MockERC20ReturnFalse token = new MockERC20ReturnFalse();

        vm.expectRevert(IMultistrategyVault.ApprovalFailed.selector);
        ERC20SafeApproveLib.safeApprove(address(token), SPENDER, AMOUNT);
    }

    function test_SafeApprove_RevertsWhen_TokenReverts() public {
        MockERC20Revert token = new MockERC20Revert();

        vm.expectRevert(IMultistrategyVault.ApprovalFailed.selector);
        ERC20SafeApproveLib.safeApprove(address(token), SPENDER, AMOUNT);
    }

    function test_SafeApprove_RevertsWhen_TokenRevertsWithNoReason() public {
        MockERC20RevertNoReason token = new MockERC20RevertNoReason();

        vm.expectRevert(IMultistrategyVault.ApprovalFailed.selector);
        ERC20SafeApproveLib.safeApprove(address(token), SPENDER, AMOUNT);
    }

    function test_SafeApprove_RevertsWhen_TargetHasNoCode() public {
        // token.call(...) on an address with no code succeeds with empty
        // returndata in the EVM, so the low-level call itself does not fail;
        // however this is still a legitimate "no contract" scenario to pin
        // down: since data.length == 0, the lib currently treats it as success.
        // We assert the actual (documented) behavior here rather than assume.
        address noCode = address(0xDEAD);

        // Should NOT revert: success == true, data.length == 0 => passes.
        ERC20SafeApproveLib.safeApprove(noCode, SPENDER, AMOUNT);
