        noReturnToken = new NoReturnERC20Mock();
        falseReturnToken = new FalseReturnERC20Mock();
        revertingToken = new RevertingERC20Mock();
        silentRevertToken = new SilentRevertERC20Mock();
        invalidReturnDataToken = new InvalidReturnDataERC20Mock();
        extraDataTrueToken = new ExtraDataTrueERC20Mock();
        zeroReturnToken = new ZeroReturnERC20Mock();
    }

    /* -------------------------------------------------------------------- */
    /*                              Success cases                           */
    /* -------------------------------------------------------------------- */

    function test_safeApprove_standardToken_setsAllowance() public {
        ERC20SafeApproveLib.safeApprove(address(standardToken), SPENDER, 100 ether);
        assertEq(standardToken.allowance(address(this), SPENDER), 100 ether);
    }

    function test_safeApprove_noReturnToken_succeeds() public {
        // USDT-like token: no return data at all, but call succeeds and allowance is set.
        ERC20SafeApproveLib.safeApprove(address(noReturnToken), SPENDER, 50 ether);
        assertEq(noReturnToken.allowance(address(this), SPENDER), 50 ether);
    }

    function test_safeApprove_extraDataTrueToken_succeeds() public {
        // Return data longer than 32 bytes but decodable as `true` in the first word.
        ERC20SafeApproveLib.safeApprove(address(extraDataTrueToken), SPENDER, 7 ether);
        assertEq(extraDataTrueToken.allowance(address(this), SPENDER), 7 ether);
    }

    function test_safeApprove_zeroAmount_succeeds() public {
        ERC20SafeApproveLib.safeApprove(address(standardToken), SPENDER, 0);
        assertEq(standardToken.allowance(address(this), SPENDER), 0);
    }

    function testFuzz_safeApprove_standardToken_setsAllowance(address spender, uint256 amount) public {
        ERC20SafeApproveLib.safeApprove(address(standardToken), spender, amount);
        assertEq(standardToken.allowance(address(this), spender), amount);
    }

    /// @dev Low-level `.call` to an address with no code succeeds trivially (success = true, empty
    /// return data), so safeApprove does not revert even though nothing meaningful happened.
    function test_safeApprove_nonContractAddress_doesNotRevert() public {
        address eoaLikeAddress = address(0x1234567890123456789012345678901234567890);
        assertEq(eoaLikeAddress.code.length, 0);
        ERC20SafeApproveLib.safeApprove(eoaLikeAddress, SPENDER, 1 ether);
    }

    /* -------------------------------------------------------------------- */
    /*                              Failure cases                           */
    /* -------------------------------------------------------------------- */

    function test_safeApprove_falseReturnToken_reverts() public {
        vm.expectRevert(IMultistrategyVault.ApprovalFailed.selector);
        ERC20SafeApproveLib.safeApprove(address(falseReturnToken), SPENDER, 1 ether);
    }

    function test_safeApprove_zeroReturnToken_reverts() public {
        // Returns a 32-byte zero word, which decodes to `false`.
        vm.expectRevert(IMultistrategyVault.ApprovalFailed.selector);
        ERC20SafeApproveLib.safeApprove(address(zeroReturnToken), SPENDER, 1 ether);
    }

    function test_safeApprove_revertingToken_bubblesApprovalFailed() public {
        vm.expectRevert(IMultistrategyVault.ApprovalFailed.selector);
        ERC20SafeApproveLib.safeApprove(address(revertingToken), SPENDER, 1 ether);
    }

    function test_safeApprove_silentRevertingToken_bubblesApprovalFailed() public {
        vm.expectRevert(IMultistrategyVault.ApprovalFailed.selector);
        ERC20SafeApproveLib.safeApprove(address(silentRevertToken), SPENDER, 1 ether);
    }

    function test_safeApprove_invalidReturnData_reverts() public {
        // Return data is present but too short to abi.decode as bool -> revert (not necessarily
