// SPDX-License-Identifier: AGPL-3.0
pragma solidity >=0.8.18;

import {Test} from "forge-std/Test.sol";
import {Vm} from "forge-std/Vm.sol";
import {Privileged} from "src/core/Privileged.sol";

/// @dev Minimal concrete harness exposing the internal functions of the abstract
///      Privileged mixin so it can be exercised directly in tests. No additional
///      access control is layered on top since Privileged itself is access-control
///      agnostic (that's left to inheriting contracts).
contract PrivilegedHarness is Privileged {
    function setPrivileged(address _account, bool _status) external {
        _setPrivileged(_account, _status);
    }

    function setPrivilegedBatch(address[] calldata _accounts, bool _status) external {
        _setPrivilegedBatch(_accounts, _status);
    }

    function storageSlot() external pure returns (bytes32) {
        return PRIVILEGED_STORAGE;
    }
}

contract PrivilegedTest is Test {
    event PrivilegedUpdated(address indexed account, bool status);

    PrivilegedHarness internal harness;

    address internal alice = makeAddr("alice");
    address internal bob = makeAddr("bob");
    address internal carol = makeAddr("carol");

    function setUp() public {
        harness = new PrivilegedHarness();
    }

    /*//////////////////////////////////////////////////////////////
                              INITIAL STATE
    //////////////////////////////////////////////////////////////*/

    function test_InitialState_NotPrivileged() public view {
        assertFalse(harness.isPrivileged(alice));
        assertFalse(harness.isPrivileged(bob));
        assertFalse(harness.isPrivileged(address(0)));
    }

    /*//////////////////////////////////////////////////////////////
                              setPrivileged
    //////////////////////////////////////////////////////////////*/

    function test_SetPrivileged_TrueSetsFlagAndEmits() public {
        vm.expectEmit(true, false, false, true, address(harness));
        emit PrivilegedUpdated(alice, true);

        harness.setPrivileged(alice, true);

        assertTrue(harness.isPrivileged(alice));
    }

    function test_SetPrivileged_FalseAfterTrueSetsFlagAndEmits() public {
        harness.setPrivileged(alice, true);
        assertTrue(harness.isPrivileged(alice));

        vm.expectEmit(true, false, false, true, address(harness));
        emit PrivilegedUpdated(alice, false);

        harness.setPrivileged(alice, false);

        assertFalse(harness.isPrivileged(alice));
    }

    function test_SetPrivileged_NoopWhenAlreadyFalse_NoEvent() public {
        assertFalse(harness.isPrivileged(alice));

        vm.recordLogs();
        harness.setPrivileged(alice, false);
        Vm.Log[] memory logs = vm.getRecordedLogs();

        assertEq(logs.length, 0);
        assertFalse(harness.isPrivileged(alice));
    }

    function test_SetPrivileged_NoopWhenAlreadyTrue_NoEvent() public {
        harness.setPrivileged(alice, true);
        assertTrue(harness.isPrivileged(alice));

        vm.recordLogs();
        harness.setPrivileged(alice, true);
        Vm.Log[] memory logs = vm.getRecordedLogs();

        assertEq(logs.length, 0);
        assertTrue(harness.isPrivileged(alice));
    }

    function test_SetPrivileged_DoesNotAffectOtherAccounts() public {
        harness.setPrivileged(alice, true);

        assertTrue(harness.isPrivileged(alice));
        assertFalse(harness.isPrivileged(bob));
        assertFalse(harness.isPrivileged(carol));
    }

    function test_SetPrivileged_ZeroAddress() public {
        vm.expectEmit(true, false, false, true, address(harness));
        emit PrivilegedUpdated(address(0), true);

        harness.setPrivileged(address(0), true);

        assertTrue(harness.isPrivileged(address(0)));
    }

    function testFuzz_SetPrivileged_TogglesCorrectly(address account, bool status) public {
        harness.setPrivileged(account, status);
        assertEq(harness.isPrivileged(account), status);

        harness.setPrivileged(account, !status);
        assertEq(harness.isPrivileged(account), !status);
    }

    function testFuzz_SetPrivileged_RepeatedSameStatusIsIdempotent(address account, bool status, uint8 repeats)
        public
    {
        vm.assume(repeats > 0);
        harness.setPrivileged(account, status);
        assertEq(harness.isPrivileged(account), status);

        for (uint256 i = 0; i < uint256(repeats) % 10; i++) {
            vm.recordLogs();
            harness.setPrivileged(account, status);
            assertEq(vm.getRecordedLogs().length, 0);
            assertEq(harness.isPrivileged(account), status);
        }
    }

    /*//////////////////////////////////////////////////////////////
                           setPrivilegedBatch
    //////////////////////////////////////////////////////////////*/

    function test_SetPrivilegedBatch_EmptyArray_NoEventsNoRevert() public {
        address[] memory accounts = new address[](0);

        vm.recordLogs();
        harness.setPrivilegedBatch(accounts, true);
        assertEq(vm.getRecordedLogs().length, 0);
    }

    function test_SetPrivilegedBatch_SetsAllToTrue() public {
        address[] memory accounts = new address[](3);
        accounts[0] = alice;
        accounts[1] = bob;
        accounts[2] = carol;

        vm.expectEmit(true, false, false, true, address(harness));
        emit PrivilegedUpdated(alice, true);
        vm.expectEmit(true, false, false, true, address(harness));
        emit PrivilegedUpdated(bob, true);
        vm.expectEmit(true, false, false, true, address(harness));
        emit PrivilegedUpdated(carol, true);

        harness.setPrivilegedBatch(accounts, true);

        assertTrue(harness.isPrivileged(alice));
        assertTrue(harness.isPrivileged(bob));
        assertTrue(harness.isPrivileged(carol));
    }

    function test_SetPrivilegedBatch_SetsAllToFalse() public {
        address[] memory accounts = new address[](2);
        accounts[0] = alice;
        accounts[1] = bob;

        harness.setPrivilegedBatch(accounts, true);
        assertTrue(harness.isPrivileged(alice));
        assertTrue(harness.isPrivileged(bob));

        vm.expectEmit(true, false, false, true, address(harness));
        emit PrivilegedUpdated(alice, false);
        vm.expectEmit(true, false, false, true, address(harness));
        emit PrivilegedUpdated(bob, false);

        harness.setPrivilegedBatch(accounts, false);

        assertFalse(harness.isPrivileged(alice));
        assertFalse(harness.isPrivileged(bob));
    }

    function test_SetPrivilegedBatch_SkipsNoopEntries() public {
        // alice already privileged, bob is not.
        harness.setPrivileged(alice, true);

        address[] memory accounts = new address[](2);
        accounts[0] = alice; // no-op: already true
        accounts[1] = bob; // real change: false -> true

        vm.recordLogs();
        harness.setPrivilegedBatch(accounts, true);
        Vm.Log[] memory logs = vm.getRecordedLogs();

        assertEq(logs.length, 1);
        assertEq(logs[0].topics[0], PrivilegedUpdated.selector);
        assertEq(address(uint160(uint256(logs[0].topics[1]))), bob);

        assertTrue(harness.isPrivileged(alice));
        assertTrue(harness.isPrivileged(bob));
    }

    function test_SetPrivilegedBatch_AllNoop_NoEvents() public {
        address[] memory accounts = new address[](2);
        accounts[0] = alice;
        accounts[1] = bob;

        harness.setPrivilegedBatch(accounts, true);

        vm.recordLogs();
        harness.setPrivilegedBatch(accounts, true);
        assertEq(vm.getRecordedLogs().length, 0);
    }

    function test_SetPrivilegedBatch_DuplicateAddresses_EmitsOncePerActualChange() public {
        address[] memory accounts = new address[](3);
        accounts[0] = alice;
        accounts[1] = alice;
        accounts[2] = alice;

        vm.recordLogs();
        harness.setPrivilegedBatch(accounts, true);
        Vm.Log[] memory logs = vm.getRecordedLogs();

        // Only the first entry causes an actual state change; the rest are no-ops.
        assertEq(logs.length, 1);
        assertTrue(harness.isPrivileged(alice));
    }

    function test_SetPrivilegedBatch_DoesNotAffectUnlistedAccounts() public {
        address[] memory accounts = new address[](1);
        accounts[0] = alice;

        harness.setPrivilegedBatch(accounts, true);

        assertTrue(harness.isPrivileged(alice));
        assertFalse(harness.isPrivileged(bob));
    }

    function testFuzz_SetPrivilegedBatch_MatchesIndividualCalls(address a, address b, address c, bool status)
        public
    {
        address[] memory accounts = new address[](3);
        accounts[0] = a;
        accounts[1] = b;
        accounts[2] = c;

        harness.setPrivilegedBatch(accounts, status);

        assertEq(harness.isPrivileged(a), status);
        assertEq(harness.isPrivileged(b), status);
        assertEq(harness.isPrivileged(c), status);
    }

    /*//////////////////////////////////////////////////////////////
                       ERC-7201 STORAGE LAYOUT
    //////////////////////////////////////////////////////////////*/

    function test_StorageSlot_MatchesErc7201Derivation() public view {
        bytes32 expected =
            keccak256(abi.encode(uint256(keccak256("octant.privileged.strategy.storage")) - 1)) & ~bytes32(uint256(0xff));
        assertEq(harness.storageSlot(), expected);
    }

    function test_StorageSlot_LowByteIsZeroed() public view {
        bytes32 slot = harness.storageSlot();
        assertEq(uint256(slot) & 0xff, 0);
    }

    function testFuzz_MappingStorageLocation_MatchesIsPrivileged(address account, bool status) public {
        harness.setPrivileged(account, status);

        bytes32 baseSlot = harness.storageSlot();
        bytes32 mappingSlot = keccak256(abi.encode(account, baseSlot));
        bytes32 raw = vm.load(address(harness), mappingSlot);

        assertEq(uint256(raw), status ? 1 : 0);
        assertEq(harness.isPrivileged(account), status);
    }
}

