// SPDX-License-Identifier: AGPL-3.0
pragma solidity >=0.8.25;

import { Test } from "forge-std/Test.sol";
import { PrivilegedYieldDonatingTokenizedStrategy } from
    "src/strategies/yieldDonating/PrivilegedYieldDonatingTokenizedStrategy.sol";

/// @dev Minimal self-contained ERC20 mock used only as the strategy's underlying asset.
///      No repo access was available while writing this suite, so no shared mock/token
///      helper from the project could be reused here.
contract MockERC20 {
    string public name = "Mock Asset";
    string public symbol = "mAST";
    uint8 public constant decimals = 18;
    uint256 public totalSupply;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    function mint(address to, uint256 amount) external {
        totalSupply += amount;
        balanceOf[to] += amount;
        emit Transfer(address(0), to, amount);
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        _transfer(msg.sender, to, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 allowed = allowance[from][msg.sender];
        if (allowed != type(uint256).max) {
            require(allowed >= amount, "allowance");
            allowance[from][msg.sender] = allowed - amount;
        }
        _transfer(from, to, amount);
        return true;
    }

    function _transfer(address from, address to, uint256 amount) internal {
        require(balanceOf[from] >= amount, "balance");
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        emit Transfer(from, to, amount);
    }
}

/// @notice Test suite for PrivilegedYieldDonatingTokenizedStrategy.
///
/// @dev IMPORTANT — deployment assumptions:
/// The full source of `YieldDonatingTokenizedStrategy` / `Privileged` / the underlying
/// tokenized-strategy base was not available while writing this suite (only the contract
/// in the prompt was provided). Because `PrivilegedYieldDonatingTokenizedStrategy` declares
/// no constructor of its own, the base chain must not require constructor arguments, which
/// matches the well-known Yearn-V3-style "tokenized strategy" pattern where the concrete
/// strategy is deployed bare and then configured once via `initialize(...)`. This suite
/// assumes that shape:
///
///     initialize(address asset, string memory name, address management, address keeper, address dragonRouter)
///
/// and that `onlyManagement`-gated functions revert (reason string not assumed — checked
/// generically), while the caller-gate added by this contract reverts with the exact
/// string "!privileged" shown in the reviewed source. If the real `initialize` signature
/// differs, only `_deployStrategy()` below needs to change; all other assertions target
/// behavior documented directly in the reviewed contract.
contract PrivilegedYieldDonatingTokenizedStrategyTest is Test {
    PrivilegedYieldDonatingTokenizedStrategy internal strategy;
    MockERC20 internal asset;

    address internal management = address(this);
    address internal keeper = address(0xCAFE);
    address internal dragonRouter = address(0xD1A6D0);

    address internal alice = address(0xA11CE); // will be made privileged in most tests
    address internal bob = address(0xB0B); // stays non-privileged in most tests
    address internal carol = address(0xCA401);

    function setUp() public {
        asset = new MockERC20();
        strategy = _deployStrategy();
    }

    function _deployStrategy() internal returns (PrivilegedYieldDonatingTokenizedStrategy s) {
        s = new PrivilegedYieldDonatingTokenizedStrategy();
        s.initialize(address(asset), "Privileged Yield Donating Strategy", management, keeper, dragonRouter);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // isPrivileged / setPrivileged
    // ─────────────────────────────────────────────────────────────────────────

    function test_isPrivileged_defaultsFalse() public {
        assertFalse(strategy.isPrivileged(alice));
        assertFalse(strategy.isPrivileged(bob));
        assertFalse(strategy.isPrivileged(address(this)));
    }

    function test_setPrivileged_grantsAndRevokes() public {
        assertFalse(strategy.isPrivileged(alice));

        strategy.setPrivileged(alice, true);
        assertTrue(strategy.isPrivileged(alice));

        strategy.setPrivileged(alice, false);
        assertFalse(strategy.isPrivileged(alice));
    }

    function test_setPrivileged_revertsForNonManagement() public {
        vm.prank(bob);
        vm.expectRevert();
        strategy.setPrivileged(alice, true);
    }

    function testFuzz_setPrivileged_toggles(address account, bool status) public {
        vm.assume(account != address(0));
        strategy.setPrivileged(account, status);
        assertEq(strategy.isPrivileged(account), status);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // setPrivilegedBatch
    // ─────────────────────────────────────────────────────────────────────────

    function test_setPrivilegedBatch_grantsAndRevokesAll() public {
        address[] memory accounts = new address[](3);
        accounts[0] = alice;
        accounts[1] = bob;
        accounts[2] = carol;

        strategy.setPrivilegedBatch(accounts, true);
        assertTrue(strategy.isPrivileged(alice));
        assertTrue(strategy.isPrivileged(bob));
        assertTrue(strategy.isPrivileged(carol));

        strategy.setPrivilegedBatch(accounts, false);
        assertFalse(strategy.isPrivileged(alice));
        assertFalse(strategy.isPrivileged(bob));
        assertFalse(strategy.isPrivileged(carol));
    }

    function test_setPrivilegedBatch_revertsForNonManagement() public {
        address[] memory accounts = new address[](1);
        accounts[0] = alice;

        vm.prank(bob);
        vm.expectRevert();
        strategy.setPrivilegedBatch(accounts, true);
    }

    function test_setPrivilegedBatch_emptyArray_noop() public {
        address[] memory accounts = new address[](0);
        // Should not revert on an empty batch.
        strategy.setPrivilegedBatch(accounts, true);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // deposit — caller-gated, receiver may be unprivileged
    // ─────────────────────────────────────────────────────────────────────────

    function test_deposit_revertsForNonPrivilegedCaller() public {
        asset.mint(bob, 10e18);

        vm.startPrank(bob);
        asset.approve(address(strategy), 10e18);
        vm.expectRevert(bytes("!privileged"));
        strategy.deposit(10e18, bob);
        vm.stopPrank();
    }

    function test_deposit_succeedsForPrivilegedCaller_toUnprivilegedReceiver() public {
        strategy.setPrivileged(alice, true);
        assertFalse(strategy.isPrivileged(bob));

        asset.mint(alice, 100e18);
        vm.startPrank(alice);
        asset.approve(address(strategy), 100e18);
        uint256 shares = strategy.deposit(100e18, bob);
        vm.stopPrank();

        assertEq(shares, 100e18);
        assertEq(strategy.balanceOf(bob), 100e18);
        assertEq(strategy.balanceOf(alice), 0);
        assertEq(asset.balanceOf(address(strategy)), 100e18);
    }

    function test_deposit_revertsAgainAfterPrivilegeRevoked() public {
        strategy.setPrivileged(alice, true);
        strategy.setPrivileged(alice, false);

        asset.mint(alice, 10e18);
        vm.startPrank(alice);
        asset.approve(address(strategy), 10e18);
        vm.expectRevert(bytes("!privileged"));
        strategy.deposit(10e18, alice);
        vm.stopPrank();
    }

    // ─────────────────────────────────────────────────────────────────────────
    // mint — caller-gated, receiver may be unprivileged
    // ─────────────────────────────────────────────────────────────────────────

    function test_mint_revertsForNonPrivilegedCaller() public {
        asset.mint(bob, 40e18);

