// SPDX-License-Identifier: AGPL-3.0
pragma solidity >=0.8.25;

import { Test } from "forge-std/Test.sol";
import { PrivilegedYieldDonatingTokenizedStrategy } from
    "src/strategies/yieldDonating/PrivilegedYieldDonatingTokenizedStrategy.sol";

/// -----------------------------------------------------------------------
/// Test-only helpers
/// -----------------------------------------------------------------------
///
/// NOTE ON ASSUMPTIONS: only `PrivilegedYieldDonatingTokenizedStrategy.sol`
/// was provided for this task. Its parent chain (`YieldDonatingTokenizedStrategy`
/// -> base tokenized-strategy, and `Privileged`) is not shown, so this suite
/// makes the following (standard, low-risk) assumptions about the inherited
/// surface, consistent with the Yearn-V3-style "TokenizedStrategy" pattern
/// this contract is clearly built on and with the NatSpec in the file under
/// test:
///   - No constructor args are required (the base uses a clone-friendly
///     `initialize(address asset, string name, address management,
///     address feeOrDonationRecipient, address keeper)` entrypoint).
///   - Strategy-specific investment hooks `_deployFunds`, `_freeFunds`, and
///     `_harvestAndReport` are `internal virtual` and must be implemented by
///     a concrete strategy (an idle no-op implementation is provided here).
///   - `Privileged.isPrivileged(address)` is a `public view` getter.
///   - `management()` is a `public view` getter for the management role,
///     and management-gated setters revert (reason string unspecified) when
///     called by a non-management account.
///   - `asset()` is a public getter returning the underlying ERC-20, and a
///     vault's first-ever deposit mints shares 1:1 with assets deposited.
/// If any of these differ from the real base contracts, only the setUp/
/// harness section below should need adjusting — the test bodies exercise
/// only the behavior added by `PrivilegedYieldDonatingTokenizedStrategy`
/// itself.

interface IERC20Like {
    function balanceOf(address account) external view returns (uint256);
}

/// @dev Minimal mintable ERC-20 used as the strategy's underlying asset.
contract MockERC20 {
    string public name = "Mock Token";
    string public symbol = "MOCK";
    uint8 public decimals = 18;
    uint256 public totalSupply;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    function mint(address to, uint256 amount) external {
        totalSupply += amount;
        balanceOf[to] += amount;
        emit Transfer(address(0), to, amount);
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        _transfer(msg.sender, to, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 allowed = allowance[from][msg.sender];
        if (allowed != type(uint256).max) {
            require(allowed >= amount, "MockERC20: insufficient allowance");
            allowance[from][msg.sender] = allowed - amount;
        }
        _transfer(from, to, amount);
        return true;
    }

    function _transfer(address from, address to, uint256 amount) internal {
        require(balanceOf[from] >= amount, "MockERC20: insufficient balance");
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        emit Transfer(from, to, amount);
    }
}

/// @dev Concrete, deployable strategy under test. Investment hooks are
///      no-ops: deposited assets simply sit idle in the contract, which is
///      sufficient to exercise the privileged-gating logic being tested.
contract PrivilegedYieldDonatingTokenizedStrategyHarness is PrivilegedYieldDonatingTokenizedStrategy {
    function _deployFunds(uint256 /* _amount */ ) internal override { }

    function _freeFunds(uint256 /* _amount */ ) internal override { }

    function _harvestAndReport() internal override returns (uint256) {
        return IERC20Like(asset()).balanceOf(address(this));
    }
}

contract PrivilegedYieldDonatingTokenizedStrategyTest is Test {
    PrivilegedYieldDonatingTokenizedStrategyHarness internal strategy;
    MockERC20 internal asset;

    address internal management;
    address internal keeper;
    address internal donationRecipient;

    address internal alice; // will be made privileged
    address internal bob; // stays non-privileged
    address internal carol; // stays non-privileged

    uint256 internal constant DEPOSIT_AMOUNT = 100 ether;

    function setUp() public {
        asset = new MockERC20();

        management = makeAddr("management");
        keeper = makeAddr("keeper");
        donationRecipient = makeAddr("donationRecipient");

        alice = makeAddr("alice");
        bob = makeAddr("bob");
        carol = makeAddr("carol");

        strategy = new PrivilegedYieldDonatingTokenizedStrategyHarness();
        strategy.initialize(
            address(asset), "Privileged Yield Donating Strategy", management, donationRecipient, keeper
        );

        vm.prank(management);
        strategy.setPrivileged(alice, true);
    }

    /// -------------------------------------------------------------------
    /// helpers
    /// -------------------------------------------------------------------

    function _fund(address who, uint256 amount) internal {
        asset.mint(who, amount);
        vm.prank(who);
        asset.approve(address(strategy), amount);
    }

    /// -------------------------------------------------------------------
    /// isPrivileged / setPrivileged
    /// -------------------------------------------------------------------

    function test_IsPrivileged_DefaultsFalse() public {
        assertFalse(strategy.isPrivileged(bob));
        assertFalse(strategy.isPrivileged(carol));
    }

    function test_SetPrivileged_ByManagement_GrantsStatus() public {
        assertFalse(strategy.isPrivileged(bob));

        vm.prank(management);
        strategy.setPrivileged(bob, true);

        assertTrue(strategy.isPrivileged(bob));
    }

    function test_SetPrivileged_ByManagement_RevokesStatus() public {
        assertTrue(strategy.isPrivileged(alice));

        vm.prank(management);
        strategy.setPrivileged(alice, false);

        assertFalse(strategy.isPrivileged(alice));
    }

    function test_SetPrivileged_RevertsForNonManagement() public {
        vm.prank(bob);
        vm.expectRevert();
        strategy.setPrivileged(bob, true);
    }

    function testFuzz_SetPrivileged_TogglesCorrectly(address account, bool status) public {
        vm.assume(account != address(0));

        vm.prank(management);
        strategy.setPrivileged(account, status);

        assertEq(strategy.isPrivileged(account), status);
    }

    /// -------------------------------------------------------------------
    /// setPrivilegedBatch
    /// -------------------------------------------------------------------

    function test_SetPrivilegedBatch_RevertsForNonManagement() public {
        address[] memory accounts = new address[](2);
        accounts[0] = bob;
        accounts[1] = carol;

        vm.prank(bob);
        vm.expectRevert();
        strategy.setPrivilegedBatch(accounts, true);
    }

    function test_SetPrivilegedBatch_GrantsAllAccounts() public {
        address[] memory accounts = new address[](3);
        accounts[0] = bob;
        accounts[1] = carol;
        accounts[2] = makeAddr("dave");

        vm.prank(management);
        strategy.setPrivilegedBatch(accounts, true);

        for (uint256 i = 0; i < accounts.length; i++) {
            assertTrue(strategy.isPrivileged(accounts[i]));
        }
    }

    function test_SetPrivilegedBatch_RevokesAllAccounts() public {
        address[] memory accounts = new address[](2);
        accounts[0] = bob;
        accounts[1] = carol;

        vm.startPrank(management);
        strategy.setPrivilegedBatch(accounts, true);
        strategy.setPrivilegedBatch(accounts, false);
        vm.stopPrank();

        assertFalse(strategy.isPrivileged(bob));
        assertFalse(strategy.isPrivileged(carol));
    }

    function testFuzz_SetPrivilegedBatch_HandlesArbitraryLength(uint8 rawLength, bool status) public {
        uint256 length = bound(uint256(rawLength), 0, 20);
        address[] memory accounts = new address[](length);
        for (uint256 i = 0; i < length; i++) {
            accounts[i] = address(uint160(uint256(keccak256(abi.encode(i, "batch")))));
        }

        vm.prank(management);
        strategy.setPrivilegedBatch(accounts, status);

        for (uint256 i = 0; i < length; i++) {
            assertEq(strategy.isPrivileged(accounts[i]), status);
        }
    }

    /// -------------------------------------------------------------------
    /// deposit
    /// -------------------------------------------------------------------

    function test_Deposit_RevertsForNonPrivilegedCaller() public {
        _fund(bob, DEPOSIT_AMOUNT);

        vm.prank(bob);
        vm.expectRevert(bytes("!privileged"));
        strategy.deposit(DEPOSIT_AMOUNT, bob);
    }

    function test_Deposit_SucceedsForPrivilegedCallerToSelf() public {
        _fund(alice, DEPOSIT_AMOUNT);

        vm.prank(alice);
        uint256 shares = strategy.deposit(DEPOSIT_AMOUNT, alice);

        assertGt(shares, 0);
        assertEq(strategy.balanceOf(alice), shares);
        assertEq(asset.balanceOf(address(strategy)), DEPOSIT_AMOUNT);
    }

    function test_Deposit_SucceedsForPrivilegedCallerToNonPrivilegedReceiver() public {
        _fund(alice, DEPOSIT_AMOUNT);
        assertFalse(strategy.isPrivileged(bob));

        vm.prank(alice);
        uint256 shares = strategy.deposit(DEPOSIT_AMOUNT, bob);

        assertGt(shares, 0);
        assertEq(strategy.balanceOf(bob), shares);
        assertEq(strategy.balanceOf(alice), 0);
    }

    function test_Deposit_RevertsAfterPrivilegeIsRevoked() public {
        _fund(alice, DEPOSIT_AMOUNT * 2);

        vm.prank(alice);
        strategy.deposit(DEPOSIT_AMOUNT, alice);

        vm.prank(management);
        strategy.setPrivileged(alice, false);

        vm.prank(alice);
        vm.expectRevert(bytes("!privileged"));
        strategy.deposit(DEPOSIT_AMOUNT, alice);
    }

    /// -------------------------------------------------------------------
    /// mint
    /// -------------------------------------------------------------------

    function test_Mint_RevertsForNonPrivilegedCaller() public {
        _fund(bob, DEPOSIT_AMOUNT);

        vm.prank(bob);
        vm.expectRevert(bytes("!privileged"));
        strategy.mint(DEPOSIT_AMOUNT, bob);
    }

    function test_Mint_SucceedsForPrivilegedCallerToSelf() public {
        _fund(alice, DEPOSIT_AMOUNT);

        vm.prank(alice);
        uint256 assetsUsed = strategy.mint(DEPOSIT_AMOUNT, alice);

        assertGt(assetsUsed, 0);
        assertGt(strategy.balanceOf(alice), 0);
    }

    function test_Mint_SucceedsForPrivilegedCallerToNonPrivilegedReceiver() public {
        _fund(alice, DEPOSIT_AMOUNT);
        assertFalse(strategy.isPrivileged(carol));

        vm.prank(alice);
        strategy.mint(DEPOSIT_AMOUNT, carol);

        assertGt(strategy.balanceOf(carol), 0);
        assertEq(strategy.balanceOf(alice), 0);
    }

    /// -------------------------------------------------------------------
    /// maxDeposit / maxMint
    /// -------------------------------------------------------------------

    function test_MaxDeposit_ZeroForNonPrivilegedReceiver() public {
        assertEq(strategy.maxDeposit(bob), 0);
        assertEq(strategy.maxDeposit(carol), 0);
    }

    function test_MaxDeposit_NonZeroForPrivilegedReceiver() public {
        assertGt(strategy.maxDeposit(alice), 0);
    }

    function test_MaxDeposit_BecomesZeroAfterRevocation() public {
        assertGt(strategy.maxDeposit(alice), 0);

        vm.prank(management);
        strategy.setPrivileged(alice, false);

        assertEq(strategy.maxDeposit(alice), 0);
    }

    function test_MaxMint_ZeroForNonPrivilegedReceiver() public {
        assertEq(strategy.maxMint(bob), 0);
        assertEq(strategy.maxMint(carol), 0);
    }

    function test_MaxMint_NonZeroForPrivilegedReceiver() public {
        assertGt(strategy.maxMint(alice), 0);
    }

    function testFuzz_MaxDepositAndMaxMint_MatchPrivilegeStatus(address receiver, bool status) public {
        vm.assume(receiver != address(0));

        vm.prank(management);
        strategy.setPrivileged(receiver, status);

        if (status) {
            assertGt(strategy.maxDeposit(receiver), 0);
            assertGt(strategy.maxMint(receiver), 0);
        } else {
            assertEq(strategy.maxDeposit(receiver), 0);
            assertEq(strategy.maxMint(receiver), 0);
        }
    }
}

