    function test_Mint_RevertsForNonPrivilegedCaller() public {
        vm.prank(bob);
        vm.expectRevert(bytes("!privileged"));
        strategy.mint(DEPOSIT_AMOUNT, bob);
    }

    function test_Mint_SucceedsForPrivilegedCaller() public {
        _setPrivileged(alice, true);

        vm.prank(alice);
        uint256 assetsPulled = strategy.mint(DEPOSIT_AMOUNT, alice);

        assertGt(assetsPulled, 0, "should pull underlying assets");
        assertEq(strategy.balanceOf(alice), DEPOSIT_AMOUNT);
    }

    function test_Mint_AllowsPrivilegedCallerToMintForNonPrivilegedReceiver() public {
        _setPrivileged(alice, true);
        assertFalse(strategy.isPrivileged(bob));

        vm.prank(alice);
        strategy.mint(DEPOSIT_AMOUNT, bob);

        assertEq(strategy.balanceOf(bob), DEPOSIT_AMOUNT);
        assertEq(strategy.balanceOf(alice), 0);
    }

    // ------------------------------------------------------------------
    // Once shares exist, they move freely regardless of privileged status
    // (this is the documented trust boundary: only issuance is gated).
    // ------------------------------------------------------------------

    function test_Shares_CanBeTransferredToNonPrivilegedAccount() public {
        _setPrivileged(alice, true);

        vm.prank(alice);
        uint256 shares = strategy.deposit(DEPOSIT_AMOUNT, alice);

        assertFalse(strategy.isPrivileged(carol), "carol must remain non-privileged");

        vm.prank(alice);
        strategy.transfer(carol, shares);

        assertEq(strategy.balanceOf(carol), shares);
        assertEq(strategy.balanceOf(alice), 0);
    }

    function test_NonPrivilegedHolder_CanRedeemSharesReceivedByTransfer() public {
        _setPrivileged(alice, true);

        vm.prank(alice);
        uint256 shares = strategy.deposit(DEPOSIT_AMOUNT, alice);

        vm.prank(alice);
        strategy.transfer(carol, shares);

        assertFalse(strategy.isPrivileged(carol));

        vm.prank(carol);
