    }

    // ------------------------------------------------------------------
    // Sanity: management gating on the new setters is real access control,
    // not merely a no-op modifier.
    // ------------------------------------------------------------------

    function test_SetPrivileged_ManagementItselfIsUnaffectedByPrivilegedStatus() public {
        // Management is not implicitly privileged just by being management.
        assertFalse(strategy.isPrivileged(management));

        vm.prank(management);
        vm.expectRevert(bytes("!privileged"));
        strategy.deposit(DEPOSIT_AMOUNT, management);
    }
}

