    function test_RevertsOnDelegatecallOperation_EmptyRevertData() public {
        bytes memory txs = _encodeTx(1, address(target), 0, "");

        (bool success, bytes memory ret) = address(multiSend_).call(
            abi.encodeWithSelector(MultiSendCallOnly.multiSend.selector, txs)
        );

        assertFalse(success);
        assertEq(ret.length, 0);
    }

    function test_RevertsOnDelegatecall_EvenWhenLaterOperationsAreValid() public {
        bytes memory tx1 = _encodeTx(1, address(target), 0, "");
        bytes memory tx2 =
            _encodeTx(0, address(target), 0, abi.encodeWithSelector(Target.increment.selector));

        vm.expectRevert();
        multiSend_.multiSend(abi.encodePacked(tx1, tx2));

        assertEq(target.counter(), 0);
    }

    /* -------------------------------------------------------------------- */
    /*                          Failure propagation                         */
    /* -------------------------------------------------------------------- */

    function test_BubblesUpStringRevertReason() public {
        bytes memory txs = _encodeTx(
            0, address(target), 0, abi.encodeWithSelector(Target.revertWithString.selector)
        );

        vm.expectRevert("Target: explicit revert");
        multiSend_.multiSend(txs);
    }

    function test_BubblesUpCustomErrorRevertReason() public {
        bytes memory txs = _encodeTx(
