        multiSend_.multiSend(outerTxs);
    }

    function test_DefaultsToAddressThis_NestedRealCall() public {
        bytes memory innerTx =
            _encodeTx(0, address(target), 0, abi.encodeWithSelector(Target.increment.selector));
        bytes memory innerCalldata =
            abi.encodeWithSelector(MultiSendCallOnly.multiSend.selector, innerTx);
        bytes memory outerTxs = _encodeTx(0, address(0), 0, innerCalldata);

        multiSend_.multiSend(outerTxs);

        assertEq(target.counter(), 1);
    }
}
