        return abi.encodePacked(operation, to, value, uint256(data.length), data);
    }

    /* -------------------------------------------------------------------- */
    /*                             Basic behavior                           */
    /* -------------------------------------------------------------------- */

    function test_EmptyTransactions_NoOp() public {
        // Should not revert, and should have no observable effect.
        multiSend_.multiSend("");
        assertEq(target.counter(), 0);
    }

    function test_SingleCall_Success() public {
        bytes memory txs =
            _encodeTx(0, address(target), 0, abi.encodeWithSelector(Target.increment.selector));

        multiSend_.multiSend(txs);

        assertEq(target.counter(), 1);
    }

    function test_MultipleCalls_Success() public {
        bytes memory tx1 =
            _encodeTx(0, address(target), 0, abi.encodeWithSelector(Target.increment.selector));
        bytes memory tx2 =
            _encodeTx(0, address(target), 0, abi.encodeWithSelector(Target.increment.selector));
        bytes memory tx3 = _encodeTx(
            0, address(target2), 0, abi.encodeWithSelector(Target.setValue.selector, uint256(99))
        );

        multiSend_.multiSend(abi.encodePacked(tx1, tx2, tx3));

        assertEq(target.counter(), 2);
        assertEq(target2.counter(), 99);
    }

    function test_HandlesVariableLengthDataOffsets() public {
        bytes memory shortData = ""; // 0 bytes
        bytes memory wordData = new bytes(32); // exactly one word
        bytes memory oddData = new bytes(37); // spans multiple words with remainder
        for (uint256 i = 0; i < oddData.length; i++) {
            oddData[i] = bytes1(uint8(i + 1));
        }

        bytes memory tx1 =
            _encodeTx(0, address(target), 0, abi.encodeWithSelector(Target.record.selector, shortData));
        bytes memory tx2 =
            _encodeTx(0, address(target2), 0, abi.encodeWithSelector(Target.record.selector, wordData));
        bytes memory tx3 =
            _encodeTx(0, address(target3), 0, abi.encodeWithSelector(Target.record.selector, oddData));

        multiSend_.multiSend(abi.encodePacked(tx1, tx2, tx3));

        assertEq(target.lastData(), shortData);
        assertEq(target2.lastData(), wordData);
        assertEq(target3.lastData(), oddData);
    }

    /* -------------------------------------------------------------------- */
    /*                                Value                                 */
    /* -------------------------------------------------------------------- */

    function test_ValueTransfer_ToEOA() public {
        address payable recipient = payable(makeAddr("recipient"));
        bytes memory txs = _encodeTx(0, recipient, 1 ether, "");

        multiSend_.multiSend{value: 1 ether}(txs);

        assertEq(recipient.balance, 1 ether);
    }

    function test_ValueTransfer_MultipleRecipients() public {
        bytes memory tx1 = _encodeTx(0, address(target), 0.4 ether, "");
        bytes memory tx2 = _encodeTx(0, address(target2), 0.6 ether, "");

        multiSend_.multiSend{value: 1 ether}(abi.encodePacked(tx1, tx2));

        assertEq(target.received(address(multiSend_)), 0.4 ether);
        assertEq(target2.received(address(multiSend_)), 0.6 ether);
    }

    function testFuzz_ValueTransfer_SingleRecipient(uint96 value) public {
        vm.deal(address(this), uint256(value));
        address payable recipient = payable(makeAddr("fuzzRecipient"));
        bytes memory txs = _encodeTx(0, recipient, value, "");

        multiSend_.multiSend{value: value}(txs);

        assertEq(recipient.balance, value);
    }

    function test_RevertsIfInsufficientBalanceForValue() public {
        // Requests more value than is forwarded with the call / held by the contract.
        bytes memory txs = _encodeTx(0, address(target), 1 ether, "");

        vm.expectRevert();
        multiSend_.multiSend{value: 0}(txs);
    }

    /* -------------------------------------------------------------------- */
    /*                            Delegatecall guard                        */
    /* -------------------------------------------------------------------- */

    function test_RevertsOnDelegatecallOperation() public {
        bytes memory txs = _encodeTx(1, address(target), 0, "");

        vm.expectRevert();
        multiSend_.multiSend(txs);
    }

    function test_RevertsOnDelegatecallOperation_EmptyRevertData() public {
        bytes memory txs = _encodeTx(1, address(target), 0, "");

        (bool success, bytes memory ret) = address(multiSend_).call(
            abi.encodeWithSelector(MultiSendCallOnly.multiSend.selector, txs)
        );

        assertFalse(success);
        assertEq(ret.length, 0);
    }

    function test_RevertsOnDelegatecall_EvenWhenLaterOperationsAreValid() public {
        bytes memory tx1 = _encodeTx(1, address(target), 0, "");
        bytes memory tx2 =
            _encodeTx(0, address(target), 0, abi.encodeWithSelector(Target.increment.selector));

        vm.expectRevert();
        multiSend_.multiSend(abi.encodePacked(tx1, tx2));

        assertEq(target.counter(), 0);
    }

    /* -------------------------------------------------------------------- */
    /*                          Failure propagation                         */
    /* -------------------------------------------------------------------- */

    function test_BubblesUpStringRevertReason() public {
        bytes memory txs = _encodeTx(
            0, address(target), 0, abi.encodeWithSelector(Target.revertWithString.selector)
        );

        vm.expectRevert("Target: explicit revert");
        multiSend_.multiSend(txs);
    }

    function test_BubblesUpCustomErrorRevertReason() public {
        bytes memory txs = _encodeTx(
            0, address(target), 0, abi.encodeWithSelector(Target.revertWithCustomError.selector)
        );

        vm.expectRevert(abi.encodeWithSelector(Target.CustomError.selector, uint256(42)));
        multiSend_.multiSend(txs);
    }

    function test_BubblesUpEmptyRevertReason() public {
        bytes memory txs = _encodeTx(
            0, address(target), 0, abi.encodeWithSelector(Target.revertWithNoReason.selector)
        );

        (bool success, bytes memory ret) = address(multiSend_).call(
            abi.encodeWithSelector(MultiSendCallOnly.multiSend.selector, txs)
        );

        assertFalse(success);
        assertEq(ret.length, 0);
    }

    function test_AllChangesRevert_WhenOneCallFails() public {
        bytes memory tx1 =
            _encodeTx(0, address(target), 0, abi.encodeWithSelector(Target.increment.selector));
        bytes memory tx2 = _encodeTx(
            0, address(target2), 0, abi.encodeWithSelector(Target.revertWithString.selector)
        );

        vm.expectRevert("Target: explicit revert");
        multiSend_.multiSend(abi.encodePacked(tx1, tx2));

        // The first call's state change must be rolled back along with the whole tx.
        assertEq(target.counter(), 0);
    }

    /* -------------------------------------------------------------------- */
    /*                          `to == address(0)`                          */
    /* -------------------------------------------------------------------- */

    function test_DefaultsToAddressThis_WhenToIsZero() public {
        // Inner call: multiSend(""), which is a harmless no-op.
        bytes memory innerCalldata =
            abi.encodeWithSelector(MultiSendCallOnly.multiSend.selector, bytes(""));
        bytes memory outerTxs = _encodeTx(0, address(0), 0, innerCalldata);

        // Should not revert: address(0) resolves to address(this) (the MultiSendCallOnly contract),
        // which does have a matching `multiSend` function to dispatch to.
        multiSend_.multiSend(outerTxs);
    }

    function test_DefaultsToAddressThis_NestedRealCall() public {
        bytes memory innerTx =
            _encodeTx(0, address(target), 0, abi.encodeWithSelector(Target.increment.selector));
        bytes memory innerCalldata =
            abi.encodeWithSelector(MultiSendCallOnly.multiSend.selector, innerTx);
        bytes memory outerTxs = _encodeTx(0, address(0), 0, innerCalldata);

        multiSend_.multiSend(outerTxs);

        assertEq(target.counter(), 1);
    }
}

