// SPDX-License-Identifier: LGPL-3.0-only
pragma solidity >=0.8.0 <0.9.0;

import {Test} from "forge-std/Test.sol";
import {MultiSendCallOnly} from "src/utils/libs/Safe/MultiSendCallOnly.sol";

/// @dev Simple target contract used to observe the effects of the batched calls.
contract Target {
    uint256 public value;
    uint256 public callCount;
    mapping(uint256 => uint256) public store;

    event ValueSet(uint256 newValue);

    receive() external payable {}

    function setValue(uint256 _value) external {
        value = _value;
        callCount += 1;
        emit ValueSet(_value);
    }

    function setValuePayable(uint256 _value) external payable {
        value = _value;
        callCount += 1;
    }

    function setStore(uint256 key, uint256 val) external {
        store[key] = val;
        callCount += 1;
    }

    function alwaysReverts() external pure {
        revert("Target: I always revert");
    }

    function alwaysRevertsNoReason() external pure {
        revert();
    }

    function deposit() external payable {}
}

contract MultiSendCallOnlyTest is Test {
    MultiSendCallOnly internal multiSend;
    Target internal target;
    Target internal target2;

    function setUp() public {
        multiSend = new MultiSendCallOnly();
        target = new Target();
        target2 = new Target();
        vm.deal(address(this), 100 ether);
    }

    /* -------------------------------------------------------------------- */
    /*                              Helpers                                 */
    /* -------------------------------------------------------------------- */

    function _encodeTx(uint8 operation, address to, uint256 value, bytes memory data)
        internal
        pure
        returns (bytes memory)
    {
        return abi.encodePacked(operation, to, value, data.length, data);
    }

    /* -------------------------------------------------------------------- */
    /*                             Basic behavior                          */
    /* -------------------------------------------------------------------- */

    function test_EmptyTransactions_NoOp() public {
        // Should simply return without reverting.
        multiSend.multiSend("");
    }

    function test_SingleCall_Success() public {
        bytes memory data = abi.encodeWithSelector(Target.setValue.selector, 42);
        bytes memory txs = _encodeTx(0, address(target), 0, data);

        multiSend.multiSend(txs);

        assertEq(target.value(), 42);
        assertEq(target.callCount(), 1);
    }

    function test_MultipleCalls_Success_SameTarget() public {
        bytes memory data1 = abi.encodeWithSelector(Target.setValue.selector, 1);
        bytes memory data2 = abi.encodeWithSelector(Target.setStore.selector, uint256(7), uint256(99));

        bytes memory txs = abi.encodePacked(
            _encodeTx(0, address(target), 0, data1), _encodeTx(0, address(target), 0, data2)
        );

        multiSend.multiSend(txs);

        assertEq(target.value(), 1);
        assertEq(target.store(7), 99);
        assertEq(target.callCount(), 2);
    }

    function test_MultipleCalls_Success_DifferentTargets() public {
        bytes memory data1 = abi.encodeWithSelector(Target.setValue.selector, 111);
        bytes memory data2 = abi.encodeWithSelector(Target.setValue.selector, 222);

        bytes memory txs = abi.encodePacked(
            _encodeTx(0, address(target), 0, data1), _encodeTx(0, address(target2), 0, data2)
        );

        multiSend.multiSend(txs);

        assertEq(target.value(), 111);
        assertEq(target2.value(), 222);
    }

    function test_ManySequentialCalls() public {
        uint256 n = 10;
        bytes memory txs;
        for (uint256 i = 0; i < n; i++) {
            bytes memory data = abi.encodeWithSelector(Target.setStore.selector, i, i * 10);
            txs = abi.encodePacked(txs, _encodeTx(0, address(target), 0, data));
        }

        multiSend.multiSend(txs);

        assertEq(target.callCount(), n);
        for (uint256 i = 0; i < n; i++) {
            assertEq(target.store(i), i * 10);
        }
    }

    /* -------------------------------------------------------------------- */
    /*                         Value / payable forwarding                   */
    /* -------------------------------------------------------------------- */

    function test_ValueForwarded_ToSingleCall() public {
        bytes memory data = abi.encodeWithSelector(Target.deposit.selector);
        bytes memory txs = _encodeTx(0, address(target), 1 ether, data);

        uint256 balBefore = address(target).balance;
        multiSend.multiSend{value: 1 ether}(txs);

        assertEq(address(target).balance, balBefore + 1 ether);
    }

    function test_ValueForwarded_AcrossMultipleCalls() public {
        bytes memory data1 = abi.encodeWithSelector(Target.deposit.selector);
        bytes memory data2 = abi.encodeWithSelector(Target.setValuePayable.selector, 5);

        bytes memory txs = abi.encodePacked(
            _encodeTx(0, address(target), 1 ether, data1), _encodeTx(0, address(target2), 2 ether, data2)
        );

        multiSend.multiSend{value: 3 ether}(txs);

        assertEq(address(target).balance, 1 ether);
        assertEq(address(target2).balance, 2 ether);
        assertEq(target2.value(), 5);
    }

    function test_NoValue_PlainCallSucceeds() public {
        bytes memory data = abi.encodeWithSelector(Target.setValue.selector, 3);
        bytes memory txs = _encodeTx(0, address(target), 0, data);

        multiSend.multiSend(txs);
        assertEq(target.value(), 3);
    }

    /* -------------------------------------------------------------------- */
    /*                       Reverts / failure propagation                  */
    /* -------------------------------------------------------------------- */

    function test_Reverts_WhenInnerCallReverts_WithReason() public {
        bytes memory data = abi.encodeWithSelector(Target.alwaysReverts.selector);
        bytes memory txs = _encodeTx(0, address(target), 0, data);

        vm.expectRevert("Target: I always revert");
        multiSend.multiSend(txs);
    }

    function test_Reverts_WhenInnerCallReverts_NoReason() public {
        bytes memory data = abi.encodeWithSelector(Target.alwaysRevertsNoReason.selector);
        bytes memory txs = _encodeTx(0, address(target), 0, data);

        vm.expectRevert();
        multiSend.multiSend(txs);
    }

    function test_Reverts_WhenSecondCallInBatchReverts_FirstCallStateReverted() public {
        bytes memory data1 = abi.encodeWithSelector(Target.setValue.selector, 999);
        bytes memory data2 = abi.encodeWithSelector(Target.alwaysReverts.selector);

        bytes memory txs = abi.encodePacked(
            _encodeTx(0, address(target), 0, data1), _encodeTx(0, address(target), 0, data2)
        );

        vm.expectRevert("Target: I always revert");
        multiSend.multiSend(txs);

        // Entire batch must be atomic: the first call's effects must not persist.
        assertEq(target.value(), 0);
        assertEq(target.callCount(), 0);
    }

    function test_Reverts_WhenCallingNonExistentContract() public {
        address nobody = makeAddr("nobody");
        // EOA/non-contract target with data: low-level call still "succeeds" (returns true)
        // per EVM semantics when there's no code at the address, so this should NOT revert.
        bytes memory data = abi.encodeWithSelector(Target.setValue.selector, 1);
        bytes memory txs = _encodeTx(0, nobody, 0, data);

        multiSend.multiSend(txs);
    }

    function test_Reverts_OnDelegatecallOperation() public {
        bytes memory data = abi.encodeWithSelector(Target.setValue.selector, 1);
        bytes memory txs = _encodeTx(1, address(target), 0, data);

        vm.expectRevert();
        multiSend.multiSend(txs);
    }

    function test_Reverts_OnDelegatecallOperation_MidBatch() public {
        bytes memory data1 = abi.encodeWithSelector(Target.setValue.selector, 1);
        bytes memory data2 = abi.encodeWithSelector(Target.setValue.selector, 2);

        bytes memory txs = abi.encodePacked(
            _encodeTx(0, address(target), 0, data1), _encodeTx(1, address(target), 0, data2)
        );

        vm.expectRevert();
        multiSend.multiSend(txs);

        // Atomicity: first call must also be rolled back.
        assertEq(target.value(), 0);
    }

    /* -------------------------------------------------------------------- */
    /*                        `to == address(0)` default                   */
    /* -------------------------------------------------------------------- */

    function test_ZeroAddress_DefaultsToSelf() public {
        // Calling with `to = address(0)` should default to `address(multiSend)` itself.
        // We exploit this by having it re-enter `multiSend` with an empty payload,
        // which is a valid no-op call and thus succeeds.
        bytes memory innerData = abi.encodeWithSelector(MultiSendCallOnly.multiSend.selector, bytes(""));
        bytes memory txs = _encodeTx(0, address(0), 0, innerData);

        multiSend.multiSend(txs);
    }

    function test_ZeroAddress_DefaultsToSelf_RevertsIfSelfCallReverts() public {
        // Re-enter multiSend with a delegatecall-operation payload, which must revert.
        bytes memory nestedTxs = _encodeTx(1, address(target), 0, "");
        bytes memory innerData = abi.encodeWithSelector(MultiSendCallOnly.multiSend.selector, nestedTxs);
        bytes memory txs = _encodeTx(0, address(0), 0, innerData);

        vm.expectRevert();
        multiSend.multiSend(txs);
    }

    /* -------------------------------------------------------------------- */
    /*                                 Fuzzing                              */
    /* -------------------------------------------------------------------- */

    function testFuzz_SingleCall_SetsArbitraryValue(uint256 v) public {
        bytes memory data = abi.encodeWithSelector(Target.setValue.selector, v);
        bytes memory txs = _encodeTx(0, address(target), 0, data);

        multiSend.multiSend(txs);
        assertEq(target.value(), v);
    }

    function testFuzz_ValueForwarding(uint96 amount) public {
        vm.assume(amount > 0);
        vm.deal(address(this), uint256(amount));

        bytes memory data = abi.encodeWithSelector(Target.deposit.selector);
        bytes memory txs = _encodeTx(0, address(target), amount, data);

        multiSend.multiSend{value: amount}(txs);
