// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity >=0.8.25;

import { Test } from "forge-std/Test.sol";
import { RocketPoolStrategyFactory } from "src/factories/yieldSkimming/RocketPoolStrategyFactory.sol";

/**
 * @dev Minimal, permissive stand-in for the TokenizedStrategy implementation
 * that RocketPoolStrategy's constructor delegatecalls into during
 * initialization. It accepts any calldata and returns a generous block of
 * non-zero return data so that callers expecting a boolean / numeric /
 * multi-word response after `delegatecall` do not fail to decode it.
 */
contract MockTokenizedStrategy {
    fallback() external payable {
        assembly {
            mstore(0x00, 1)
            mstore(0x20, 1)
            mstore(0x40, 1)
            mstore(0x60, 1)
            return(0x00, 0x80)
        }
    }

    receive() external payable { }
}

/**
 * @dev Minimal rETH stand-in. Its runtime code (not its storage) is etched
 * onto the real, hardcoded mainnet `R_ETH` address via `vm.etch` so that the
 * strategy constructor's interactions with the "asset" token (ERC20 metadata
 * reads and/or RocketPool-specific exchange-rate reads) resolve against real
 * bytecode instead of an empty address, without requiring a mainnet fork.
 *
 * Only `constant`/`pure`/`view`-without-storage members are safe to rely on
 * here, since `vm.etch` copies code only — any plain storage variables would
 * read back as zero at the etched address.
 */
contract MockRETH {
    string public constant name = "Rocket Pool ETH";
    string public constant symbol = "rETH";
    uint8 public constant decimals = 18;
    uint256 public constant totalSupply = 1_000_000 ether;

    function balanceOf(address) external pure returns (uint256) {
        return 0;
    }

    function allowance(address, address) external pure returns (uint256) {
        return 0;
    }

    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }

    function approve(address, uint256) external pure returns (bool) {
        return true;
    }

    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    // Common RocketPool rETH surface.
    function getExchangeRate() external pure returns (uint256) {
        return 1 ether;
    }

    function getEthValue(uint256 _rethAmount) external pure returns (uint256) {
        return _rethAmount;
    }

    function getRethValue(uint256 _ethAmount) external pure returns (uint256) {
        return _ethAmount;
    }

    function getTotalPooledEther() external pure returns (uint256) {
        return totalSupply;
    }

    // Best-effort catch-all for any additional read the strategy performs
    // that isn't explicitly modeled above.
    fallback() external payable {
        assembly {
            mstore(0x00, 1000000000000000000)
            mstore(0x20, 1000000000000000000)
            mstore(0x40, 1000000000000000000)
            mstore(0x60, 1000000000000000000)
            return(0x00, 0x80)
        }
    }
}

contract RocketPoolStrategyFactoryTest is Test {
    RocketPoolStrategyFactory internal factory;
    MockTokenizedStrategy internal mockTokenizedStrategy;

    address internal management = makeAddr("management");
    address internal keeper = makeAddr("keeper");
    address internal emergencyAdmin = makeAddr("emergencyAdmin");
    address internal donationAddress = makeAddr("donationAddress");

    string internal constant NAME = "RocketPool Yield Skimming Strategy";
    string internal constant SYMBOL = "ysRETH";

