        vm.expectRevert(abi.encodeWithSelector(RocketPoolStrategyFactory.InvalidVault.selector, wrongVault, rEth));
        factory.computeStrategyAddress(
            wrongVault,
            wrongAsset,
            NAME,
            SYMBOL,
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
