    }

    function test_ComputeStrategyAddress_AcceptsValidVaultAndAsset() public view {
        address predicted = _compute(NAME, SYMBOL, management, keeper, emergencyAdmin, donationAddress, true, address(mockTokenizedStrategy));
        assertTrue(predicted != address(0));
    }

    function test_ComputeStrategyAddress_IsDeterministic() public view {
        address predicted1 = _compute(NAME, SYMBOL, management, keeper, emergencyAdmin, donationAddress, true, address(mockTokenizedStrategy));
        address predicted2 = _compute(NAME, SYMBOL, management, keeper, emergencyAdmin, donationAddress, true, address(mockTokenizedStrategy));
