            _compute("Different Name", SYMBOL, management, keeper, emergencyAdmin, donationAddress, true, address(mockTokenizedStrategy));
        assertTrue(predicted1 != predicted2);
    }

    function test_ComputeStrategyAddress_SensitiveToSymbol() public view {
        address predicted1 = _compute(NAME, SYMBOL, management, keeper, emergencyAdmin, donationAddress, true, address(mockTokenizedStrategy));
        address predicted2 = _compute(NAME, "DIFF", management, keeper, emergencyAdmin, donationAddress, true, address(mockTokenizedStrategy));
        assertTrue(predicted1 != predicted2);
    }

    function test_ComputeStrategyAddress_SensitiveToManagement() public view {
        address predicted1 = _compute(NAME, SYMBOL, management, keeper, emergencyAdmin, donationAddress, true, address(mockTokenizedStrategy));
        address predicted2 = _compute(
            NAME, SYMBOL, makeAddr("otherManagement"), keeper, emergencyAdmin, donationAddress, true, address(mockTokenizedStrategy)
        );
        assertTrue(predicted1 != predicted2);
    }

    function test_ComputeStrategyAddress_SensitiveToKeeper() public view {
        address predicted1 = _compute(NAME, SYMBOL, management, keeper, emergencyAdmin, donationAddress, true, address(mockTokenizedStrategy));
        address predicted2 = _compute(
            NAME, SYMBOL, management, makeAddr("otherKeeper"), emergencyAdmin, donationAddress, true, address(mockTokenizedStrategy)
