        address predicted2 = _compute(NAME, SYMBOL, management, keeper, emergencyAdmin, donationAddress, false, address(mockTokenizedStrategy));
        assertTrue(predicted1 != predicted2);
    }

    function test_ComputeStrategyAddress_SensitiveToTokenizedStrategyAddress() public view {
        address predicted1 = _compute(NAME, SYMBOL, management, keeper, emergencyAdmin, donationAddress, true, address(mockTokenizedStrategy));
        address predicted2 =
            _compute(NAME, SYMBOL, management, keeper, emergencyAdmin, donationAddress, true, makeAddr("otherImplementation"));
        assertTrue(predicted1 != predicted2);
    }

    function test_ComputeStrategyAddress_SensitiveToDeployer() public view {
        address rEth = factory.R_ETH();

        address predicted1 = factory.computeStrategyAddress(
            rEth,
            rEth,
            NAME,
            SYMBOL,
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
            address(mockTokenizedStrategy),
            address(factory)
        );
        address predicted2 = factory.computeStrategyAddress(
            rEth,
            rEth,
            NAME,
            SYMBOL,
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
