        assertTrue(predicted1 != predicted2);
    }

    /* -------------------------------------------------------------------- */
    /*                              createStrategy                          */
    /* -------------------------------------------------------------------- */

    function test_CreateStrategy_DeploysToPredictedAddress() public {
        address predicted = _compute(NAME, SYMBOL, management, keeper, emergencyAdmin, donationAddress, true, address(mockTokenizedStrategy));

