    }

    function test_RevertWhen_InsufficientFunds_erc20Beneficiary() public {
        swapper.setFlashParams(address(tokenOut), 1 ether);
        ISwapRouter.ExactInputParams[] memory eips = new ISwapRouter.ExactInputParams[](0);
        UniV3Swap.InitFlashParams memory params = _flashParams(eips, 0);

        vm.expectRevert(UniV3Swap.InsufficientFunds.selector);
        uniV3Swap.initFlash(ISwapperImpl(address(swapper)), params);
    }

    function test_RevertWhen_InsufficientFunds_evenWithPartialSwapOutput() public {
        uint256 amountIn = 10 ether;
        uint256 swapOut = 1 ether;

        tokenIn.mint(address(uniV3Swap), amountIn);
        router.setSwapResult(address(weth9), swapOut);
        _fundRouterWithWeth(swapOut);

        swapper.setFlashParams(ETH_ADDRESS, 2 ether);

        ISwapRouter.ExactInputParams[] memory eips = new ISwapRouter.ExactInputParams[](1);
        eips[0] = _exactInputParams(address(tokenIn), address(weth9), amountIn);
        UniV3Swap.InitFlashParams memory params = _flashParams(eips, 0);

        vm.expectRevert(UniV3Swap.InsufficientFunds.selector);
