    }

    /* -------------------------------------------------------------------- */
    /*                    no access control (characterization)              */
    /* -------------------------------------------------------------------- */

    function test_swapperFlashCallback_callableByAnyCaller() public {
        FakeCaller fake = new FakeCaller();
        uint256 amountToBeneficiary = 1 ether;

        (bool ok,) = address(uniV3Swap).call{ value: amountToBeneficiary }("");
        assertTrue(ok);

