// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity ^0.8.17;

import { Test } from "forge-std/Test.sol";

import { UniV3Swap } from "src/utils/vendor/0xSplits/UniV3Swap.sol";
import { ISwapRouter } from "src/utils/vendor/uniswap/ISwapRouter.sol";
import { QuoteParams } from "src/utils/vendor/0xSplits/LibQuotes.sol";
import { ISwapperFlashCallback } from "src/utils/vendor/0xSplits/ISwapperFlashCallback.sol";
import { ISwapperImpl } from "src/utils/vendor/0xSplits/SwapperImpl.sol";
import { ISwapperFactory } from "src/utils/vendor/0xSplits/ISwapperFactory.sol";

import { ERC20 } from "solady/tokens/ERC20.sol";
import { WETH } from "solady/tokens/WETH.sol";
import { SafeTransferLib } from "solady/utils/SafeTransferLib.sol";

address constant ETH_ADDRESS = address(0);

/// @dev Minimal mintable ERC20 used to stand in for arbitrary swap input/output tokens.
contract MockERC20 is ERC20 {
    string private _name;
    string private _symbol;

    constructor(string memory name_, string memory symbol_) {
        _name = name_;
        _symbol = symbol_;
    }

    function name() public view override returns (string memory) {
        return _name;
    }

    function symbol() public view override returns (string memory) {
        return _symbol;
    }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

/// @dev Minimal stand-in for the real uniswap v3 SwapRouter. Pulls `amountIn` of the token
/// encoded at the start of `path` from the caller, then pays out a pre-configured amount of a
/// pre-configured output token to `params.recipient`. If the output token doesn't support
/// `mint` (e.g. real WETH), it falls back to transferring from its own pre-funded balance.
contract MockSwapRouter {
    using SafeTransferLib for address;

    address public outputToken;
    uint256 public nextAmountOut;

    function setSwapResult(address outputToken_, uint256 amountOut_) external {
        outputToken = outputToken_;
        nextAmountOut = amountOut_;
    }

    function exactInput(ISwapRouter.ExactInputParams calldata params) external payable returns (uint256 amountOut) {
        address inputToken = _firstToken(params.path);
        ERC20(inputToken).transferFrom(msg.sender, address(this), params.amountIn);

        amountOut = nextAmountOut;
        (bool success,) = outputToken.call(abi.encodeWithSignature("mint(address,uint256)", params.recipient, amountOut));
        if (!success) {
            outputToken.safeTransfer(params.recipient, amountOut);
        }
    }

    function _firstToken(bytes memory path) internal pure returns (address token) {
        assembly {
            token := mload(add(path, 0x14))
        }
    }
}

/// @dev Minimal stand-in for the real 0xSplits Swapper. `flash` forwards straight into the
/// caller's `swapperFlashCallback` using test-configured beneficiary params (bypassing the real
/// oracle math entirely), then, mimicking the real Swapper, pulls its payment for ERC20
/// beneficiaries via the approval `UniV3Swap` is expected to have granted.
contract MockSwapper {
    address public tokenToBeneficiary;
    uint256 public amountToBeneficiary;
    uint256 public receivedETH;
    uint256 public lastQuoteParamsLength;

    function setFlashParams(address tokenToBeneficiary_, uint256 amountToBeneficiary_) external {
        tokenToBeneficiary = tokenToBeneficiary_;
        amountToBeneficiary = amountToBeneficiary_;
    }

    function flash(QuoteParams[] calldata quoteParams_, bytes calldata callbackData_) external {
        lastQuoteParamsLength = quoteParams_.length;

        ISwapperFlashCallback(msg.sender).swapperFlashCallback(tokenToBeneficiary, amountToBeneficiary, callbackData_);

        if (tokenToBeneficiary != ETH_ADDRESS && amountToBeneficiary != 0) {
            ERC20(tokenToBeneficiary).transferFrom(msg.sender, address(this), amountToBeneficiary);
        }
    }

    function payback() external payable {
        require(msg.value == amountToBeneficiary, "MockSwapper: bad payback amount");
        receivedETH += msg.value;
    }

    receive() external payable { }
}

/// @dev Bare-bones contract used to demonstrate `swapperFlashCallback` can be invoked by an
/// arbitrary caller (the contract under test does not restrict `msg.sender`), so it must be able
/// to receive the `payback()` call itself.
contract FakeCaller {
    receive() external payable { }

    function payback() external payable { }
}

contract UniV3SwapTest is Test {
    UniV3Swap internal uniV3Swap;
    MockSwapRouter internal router;
    MockSwapper internal swapper;
    WETH internal weth9;
    MockERC20 internal tokenIn;
    MockERC20 internal tokenOut;

    address internal excessRecipient = address(0xCAFE);
    ISwapperFactory internal swapperFactory = ISwapperFactory(address(0xBEEF));

    function setUp() public {
        weth9 = new WETH();
        router = new MockSwapRouter();
        uniV3Swap = new UniV3Swap(swapperFactory, ISwapRouter(address(router)), weth9);
        swapper = new MockSwapper();
        tokenIn = new MockERC20("TokenIn", "IN");
        tokenOut = new MockERC20("TokenOut", "OUT");

        vm.deal(address(this), 1000 ether);
    }

    /* -------------------------------------------------------------------- */
    /*                                helpers                                */
    /* -------------------------------------------------------------------- */

    function _fundRouterWithWeth(uint256 amount) internal {
        weth9.deposit{ value: amount }();
        weth9.transfer(address(router), amount);
    }

    function _exactInputParams(address tokenIn_, address tokenOut_, uint256 amountIn_)
        internal
        view
        returns (ISwapRouter.ExactInputParams memory)
    {
        return ISwapRouter.ExactInputParams({
            path: abi.encodePacked(tokenIn_, uint24(3000), tokenOut_),
            recipient: address(uniV3Swap),
            deadline: block.timestamp,
            amountIn: amountIn_,
            amountOutMinimum: 0
        });
    }

    function _flashParams(ISwapRouter.ExactInputParams[] memory exactInputParams, uint256 numQuoteParams)
        internal
        pure
        returns (UniV3Swap.InitFlashParams memory)
    {
        return UniV3Swap.InitFlashParams({
            quoteParams: new QuoteParams[](numQuoteParams),
            flashCallbackData: UniV3Swap.FlashCallbackData({
                exactInputParams: exactInputParams,
                excessRecipient: excessRecipient
            })
        });
    }

    /* -------------------------------------------------------------------- */
    /*                               constructor                            */
    /* -------------------------------------------------------------------- */

    function test_constructor_setsImmutables() public {
        assertEq(address(uniV3Swap.swapperFactory()), address(swapperFactory));
        assertEq(address(uniV3Swap.swapRouter()), address(router));
        assertEq(address(uniV3Swap.weth9()), address(weth9));
    }

    function test_receive_acceptsETH() public {
        (bool ok,) = address(uniV3Swap).call{ value: 2 ether }("");
        assertTrue(ok);
        assertEq(address(uniV3Swap).balance, 2 ether);
    }

    /* -------------------------------------------------------------------- */
    /*                          initFlash forwarding                        */
    /* -------------------------------------------------------------------- */

    function test_initFlash_forwardsQuoteParams() public {
        swapper.setFlashParams(ETH_ADDRESS, 0);
        ISwapRouter.ExactInputParams[] memory eips = new ISwapRouter.ExactInputParams[](0);
        UniV3Swap.InitFlashParams memory params = _flashParams(eips, 3);

        uniV3Swap.initFlash(ISwapperImpl(address(swapper)), params);

        assertEq(swapper.lastQuoteParamsLength(), 3);
    }

    /* -------------------------------------------------------------------- */
    /*                      ETH beneficiary happy paths                     */
    /* -------------------------------------------------------------------- */

    function test_swapperFlashCallback_ethBeneficiary_wrapsAndPaysBackWithExcess() public {
        uint256 amountIn = 100 ether;
        uint256 swapOut = 5 ether;
        uint256 amountToBeneficiary = 3 ether;
        uint256 sentETH = 1 ether;

        tokenIn.mint(address(uniV3Swap), amountIn);
        router.setSwapResult(address(weth9), swapOut);
        _fundRouterWithWeth(swapOut);

        swapper.setFlashParams(ETH_ADDRESS, amountToBeneficiary);

        ISwapRouter.ExactInputParams[] memory eips = new ISwapRouter.ExactInputParams[](1);
        eips[0] = _exactInputParams(address(tokenIn), address(weth9), amountIn);
        UniV3Swap.InitFlashParams memory params = _flashParams(eips, 0);

        uniV3Swap.initFlash{ value: sentETH }(ISwapperImpl(address(swapper)), params);

        // totalOut = sentETH (wrapped) + swapOut = 6 ether; 3 goes to beneficiary, 3 excess
        assertEq(swapper.receivedETH(), amountToBeneficiary);
        assertEq(excessRecipient.balance, sentETH + swapOut - amountToBeneficiary);
        assertEq(address(uniV3Swap).balance, 0);
        assertEq(weth9.balanceOf(address(uniV3Swap)), 0);
        assertEq(tokenIn.balanceOf(address(uniV3Swap)), 0);
        assertEq(tokenIn.balanceOf(address(router)), amountIn);
    }

    function test_swapperFlashCallback_noSwaps_usesExistingBalance() public {
        uint256 existingETH = 4 ether;
        uint256 amountToBeneficiary = 2 ether;

        (bool ok,) = address(uniV3Swap).call{ value: existingETH }("");
        assertTrue(ok);

        swapper.setFlashParams(ETH_ADDRESS, amountToBeneficiary);

        ISwapRouter.ExactInputParams[] memory eips = new ISwapRouter.ExactInputParams[](0);
        UniV3Swap.InitFlashParams memory params = _flashParams(eips, 0);

        uniV3Swap.initFlash(ISwapperImpl(address(swapper)), params);

        assertEq(swapper.receivedETH(), amountToBeneficiary);
        assertEq(excessRecipient.balance, existingETH - amountToBeneficiary);
        assertEq(address(uniV3Swap).balance, 0);
    }

    function test_swapperFlashCallback_zeroExcess_ethBeneficiary() public {
        uint256 amountToBeneficiary = 2 ether;

        swapper.setFlashParams(ETH_ADDRESS, amountToBeneficiary);
        ISwapRouter.ExactInputParams[] memory eips = new ISwapRouter.ExactInputParams[](0);
        UniV3Swap.InitFlashParams memory params = _flashParams(eips, 0);

        uniV3Swap.initFlash{ value: amountToBeneficiary }(ISwapperImpl(address(swapper)), params);

        assertEq(swapper.receivedETH(), amountToBeneficiary);
        assertEq(excessRecipient.balance, 0);
        assertEq(address(uniV3Swap).balance, 0);
    }

    function test_swapperFlashCallback_multipleSwaps_sumsTotalOut() public {
        uint256 amountInEach = 50 ether;
        uint256 swapOutEach = 2 ether;
        uint256 amountToBeneficiary = 3 ether;

        tokenIn.mint(address(uniV3Swap), amountInEach * 2);
        router.setSwapResult(address(weth9), swapOutEach);
        _fundRouterWithWeth(swapOutEach * 2);

        swapper.setFlashParams(ETH_ADDRESS, amountToBeneficiary);

        ISwapRouter.ExactInputParams[] memory eips = new ISwapRouter.ExactInputParams[](2);
        eips[0] = _exactInputParams(address(tokenIn), address(weth9), amountInEach);
        eips[1] = _exactInputParams(address(tokenIn), address(weth9), amountInEach);
        UniV3Swap.InitFlashParams memory params = _flashParams(eips, 0);

        uniV3Swap.initFlash(ISwapperImpl(address(swapper)), params);

        // totalOut = 0 (no pre-existing ETH) + 2 + 2 = 4 ether; 3 to beneficiary, 1 excess
        assertEq(swapper.receivedETH(), amountToBeneficiary);
        assertEq(excessRecipient.balance, swapOutEach * 2 - amountToBeneficiary);
        assertEq(tokenIn.balanceOf(address(router)), amountInEach * 2);
    }

    /* -------------------------------------------------------------------- */
    /*                     ERC20 beneficiary happy paths                    */
    /* -------------------------------------------------------------------- */

    function test_swapperFlashCallback_erc20Beneficiary_approvesPaybackAndForwardsExcess() public {
        uint256 amountIn = 40 ether;
        uint256 swapOut = 10 ether;
        uint256 amountToBeneficiary = 6 ether;

        tokenIn.mint(address(uniV3Swap), amountIn);
        router.setSwapResult(address(tokenOut), swapOut);

        swapper.setFlashParams(address(tokenOut), amountToBeneficiary);

        ISwapRouter.ExactInputParams[] memory eips = new ISwapRouter.ExactInputParams[](1);
        eips[0] = _exactInputParams(address(tokenIn), address(tokenOut), amountIn);
        UniV3Swap.InitFlashParams memory params = _flashParams(eips, 0);

        uniV3Swap.initFlash(ISwapperImpl(address(swapper)), params);

        assertEq(tokenOut.balanceOf(address(swapper)), amountToBeneficiary);
        assertEq(tokenOut.balanceOf(excessRecipient), swapOut - amountToBeneficiary);
        assertEq(tokenOut.balanceOf(address(uniV3Swap)), 0);
        assertEq(tokenIn.balanceOf(address(uniV3Swap)), 0);
        assertEq(tokenIn.balanceOf(address(router)), amountIn);
    }

    function test_swapperFlashCallback_zeroExcess_erc20Beneficiary() public {
        uint256 swapOut = 5 ether;

        router.setSwapResult(address(tokenOut), swapOut);
        swapper.setFlashParams(address(tokenOut), swapOut);

        ISwapRouter.ExactInputParams[] memory eips = new ISwapRouter.ExactInputParams[](1);
        eips[0] = _exactInputParams(address(tokenIn), address(tokenOut), 1 ether);
        tokenIn.mint(address(uniV3Swap), 1 ether);
        UniV3Swap.InitFlashParams memory params = _flashParams(eips, 0);

        uniV3Swap.initFlash(ISwapperImpl(address(swapper)), params);

        assertEq(tokenOut.balanceOf(address(swapper)), swapOut);
        assertEq(tokenOut.balanceOf(excessRecipient), 0);
    }

    /* -------------------------------------------------------------------- */
    /*                            revert paths                              */
    /* -------------------------------------------------------------------- */

    function test_RevertWhen_InsufficientFunds_ethBeneficiary() public {
        swapper.setFlashParams(ETH_ADDRESS, 1 ether);
        ISwapRouter.ExactInputParams[] memory eips = new ISwapRouter.ExactInputParams[](0);
        UniV3Swap.InitFlashParams memory params = _flashParams(eips, 0);

        vm.expectRevert(UniV3Swap.InsufficientFunds.selector);
        uniV3Swap.initFlash(ISwapperImpl(address(swapper)), params);
    }

    function test_RevertWhen_InsufficientFunds_erc20Beneficiary() public {
        swapper.setFlashParams(address(tokenOut), 1 ether);
        ISwapRouter.ExactInputParams[] memory eips = new ISwapRouter.ExactInputParams[](0);
        UniV3Swap.InitFlashParams memory params = _flashParams(eips, 0);

        vm.expectRevert(UniV3Swap.InsufficientFunds.selector);
        uniV3Swap.initFlash(ISwapperImpl(address(swapper)), params);
    }

    function test_RevertWhen_InsufficientFunds_evenWithPartialSwapOutput() public {
        uint256 amountIn = 10 ether;
        uint256 swapOut = 1 ether;

        tokenIn.mint(address(uniV3Swap), amountIn);
        router.setSwapResult(address(weth9), swapOut);
        _fundRouterWithWeth(swapOut);

        swapper.setFlashParams(ETH_ADDRESS, 2 ether);

        ISwapRouter.ExactInputParams[] memory eips = new ISwapRouter.ExactInputParams[](1);
        eips[0] = _exactInputParams(address(tokenIn), address(weth9), amountIn);
        UniV3Swap.InitFlashParams memory params = _flashParams(eips, 0);

        vm.expectRevert(UniV3Swap.InsufficientFunds.selector);
        uniV3Swap.initFlash(ISwapperImpl(address(swapper)), params);
    }

    /* -------------------------------------------------------------------- */
    /*                    no access control (characterization)              */
    /* -------------------------------------------------------------------- */

    function test_swapperFlashCallback_callableByAnyCaller() public {
        FakeCaller fake = new FakeCaller();
        uint256 amountToBeneficiary = 1 ether;

        (bool ok,) = address(uniV3Swap).call{ value: amountToBeneficiary }("");
        assertTrue(ok);

        UniV3Swap.FlashCallbackData memory callbackData = UniV3Swap.FlashCallbackData({
            exactInputParams: new ISwapRouter.ExactInputParams[](0),
            excessRecipient: excessRecipient
        });

        vm.prank(address(fake));
        uniV3Swap.swapperFlashCallback(ETH_ADDRESS, amountToBeneficiary, abi.encode(callbackData));

        assertEq(address(fake).balance, amountToBeneficiary);
        assertEq(address(uniV3Swap).balance, 0);
    }
}

