        ISwapRouter.ExactInputParams[] memory legs = _singleLeg(address(tokenA), address(tokenB), amountIn);
        UniV3Swap.InitFlashParams memory params = _initFlashParams(legs, excessRecipient);

        uniV3Swap.initFlash(ISwapperImpl(address(mockSwapper)), params);

        // swap fully consumed tokenA and the router's one-time approval
        assertEq(tokenA.balanceOf(address(uniV3Swap)), 0);
        assertEq(tokenA.allowance(address(uniV3Swap), address(mockRouter)), 0);

        // required amount approved to the "swapper" (msg.sender of the callback)
        assertEq(tokenB.allowance(address(uniV3Swap), address(mockSwapper)), amountToBeneficiary);
