pragma solidity ^0.8.17;

import { Test } from "forge-std/Test.sol";
import { stdError } from "forge-std/StdError.sol";

import { UniV3Swap } from "src/utils/vendor/0xSplits/UniV3Swap.sol";
import { ISwapperFlashCallback } from "src/utils/vendor/0xSplits/ISwapperFlashCallback.sol";
import { ISwapperImpl } from "src/utils/vendor/0xSplits/SwapperImpl.sol";
import { ISwapperFactory } from "src/utils/vendor/0xSplits/ISwapperFactory.sol";
import { QuoteParams } from "src/utils/vendor/0xSplits/LibQuotes.sol";
import { ISwapRouter } from "src/utils/vendor/uniswap/ISwapRouter.sol";

import { ERC20 } from "solady/tokens/ERC20.sol";
import { WETH } from "solady/tokens/WETH.sol";

/// -----------------------------------------------------------------------
/// Mocks
/// -----------------------------------------------------------------------

/// @dev Minimal mintable ERC20 built on solady's abstract ERC20, used both as the
/// "input" token being liquidated and as the token routed to the beneficiary.
contract MockERC20 is ERC20 {
    string private _name;
    string private _symbol;

    constructor(string memory name_, string memory symbol_) {
        _name = name_;
        _symbol = symbol_;
    }

    function name() public view override returns (string memory) {
        return _name;
    }

    function symbol() public view override returns (string memory) {
        return _symbol;
    }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

/// @dev Stand-in for the uniswap v3 SwapRouter. Pulls `amountIn` of the path's first
/// token from the caller (mimicking the approval UniV3Swap grants before calling) and
/// mints a configurable `nextAmountOut` of the path's last token to `params.recipient`.
contract MockSwapRouter {
    uint256 public nextAmountOut;
    bool public revertOnSwap;
    uint256 public callCount;

    function setNextAmountOut(uint256 amt) external {
        nextAmountOut = amt;
    }

    function setRevertOnSwap(bool v) external {
        revertOnSwap = v;
    }

    function exactInput(ISwapRouter.ExactInputParams calldata params)
        external
        payable
        returns (uint256 amountOut)
    {
        require(!revertOnSwap, "MockSwapRouter: forced revert");
        callCount++;

        address tokenIn = _toAddress(params.path, 0);
        address tokenOut = _toAddress(params.path, params.path.length - 20);

        // mimic pulling the approved input amount from the caller (UniV3Swap)
        MockERC20(tokenIn).transferFrom(msg.sender, address(this), params.amountIn);

        amountOut = nextAmountOut;
        if (amountOut > 0) {
            MockERC20(tokenOut).mint(params.recipient, amountOut);
        }
    }

    function _toAddress(bytes memory data, uint256 start) internal pure returns (address addr) {
        assembly {
            addr := shr(96, mload(add(add(data, 0x20), start)))
        }
    }
}

/// @dev Stand-in for `SwapperImpl`. `flash` optionally funds the caller with an ERC20
/// (simulating the tokens the real Swapper would hand over) and then invokes
/// `swapperFlashCallback` on the caller, exactly as `Swapper#flash` does.
contract MockSwapper {
    address public tokenToBeneficiary;
    uint256 public amountToBeneficiary;
    address public fundToken;
    uint256 public fundAmount;
    bool public callCallback = true;

    bool public receivedPayback;
    uint256 public paybackAmount;

    function setParams(
        address tokenToBeneficiary_,
        uint256 amountToBeneficiary_,
        address fundToken_,
        uint256 fundAmount_,
        bool callCallback_
    ) external {
        tokenToBeneficiary = tokenToBeneficiary_;
        amountToBeneficiary = amountToBeneficiary_;
        fundToken = fundToken_;
        fundAmount = fundAmount_;
        callCallback = callCallback_;
    }

    function flash(QuoteParams[] calldata, bytes calldata data_) external payable {
        if (fundToken != address(0) && fundAmount > 0) {
            MockERC20(fundToken).mint(msg.sender, fundAmount);
        }
        if (callCallback) {
            ISwapperFlashCallback(msg.sender).swapperFlashCallback(tokenToBeneficiary, amountToBeneficiary, data_);
        }
    }

    function payback() external payable {
        receivedPayback = true;
        paybackAmount = msg.value;
    }

    receive() external payable { }
}

