import { UniV3Swap } from "src/utils/vendor/0xSplits/UniV3Swap.sol";
import { QuoteParams } from "src/utils/vendor/0xSplits/LibQuotes.sol";
import { ISwapperImpl } from "src/utils/vendor/0xSplits/SwapperImpl.sol";
import { ISwapperFactory } from "src/utils/vendor/0xSplits/ISwapperFactory.sol";
import { ISwapperFlashCallback } from "src/utils/vendor/0xSplits/ISwapperFlashCallback.sol";
import { ISwapRouter } from "src/utils/vendor/uniswap/ISwapRouter.sol";

import { ERC20 } from "solady/tokens/ERC20.sol";
import { WETH } from "solady/tokens/WETH.sol";

/// -----------------------------------------------------------------------
/// Test doubles
/// -----------------------------------------------------------------------

/// @dev minimal mintable ERC20 (solady) for use as arbitrary swap tokens
contract MockERC20 is ERC20 {
    string private _name;
    string private _symbol;

    constructor(string memory name_, string memory symbol_) {
        _name = name_;
        _symbol = symbol_;
    }

    function name() public view override returns (string memory) {
        return _name;
    }

    function symbol() public view override returns (string memory) {
        return _symbol;
    }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

/// @dev stands in for `Swapper`. Records the args passed to `flash` and, when
/// configured to do so, calls back into the initiator exactly as the real
/// Swapper would (msg.sender of `flash` is the flash-initiator / callback target).
/// Also implements `payback()` so it can receive the ETH-beneficiary payback.
contract MockSwapper {
    bytes public lastFlashData;
    uint256 public lastQuoteParamsLength;

    address public callbackToken;
    uint256 public callbackAmount;
    bool public triggerCallback;

    uint256 public totalPayback;

    receive() external payable { }

    function configureCallback(address token_, uint256 amount_, bool trigger_) external {
        callbackToken = token_;
        callbackAmount = amount_;
        triggerCallback = trigger_;
    }

    function flash(QuoteParams[] calldata quoteParams_, bytes calldata data_) external {
        lastQuoteParamsLength = quoteParams_.length;
        lastFlashData = data_;

        if (triggerCallback) {
            ISwapperFlashCallback(msg.sender).swapperFlashCallback(callbackToken, callbackAmount, data_);
        }
    }

    function payback() external payable {
        totalPayback += msg.value;
    }
}

/// @dev stands in for uniswap's `SwapRouter`. Swap results are pre-configured
/// per-path by the test so behavior is fully deterministic. Pulls `amountIn`
/// of the configured `tokenIn` from the caller (requires prior approval, exactly
/// as the real router would via `safeApprove`), and pays out `amountOut` of the
/// configured `tokenOut` to `params.recipient`. Supports paying out real WETH
/// (by depositing ETH it was funded with) so ETH-out swap paths can be tested.
contract MockSwapRouter {
    struct SwapConfig {
        bool configured;
        address tokenIn;
        address tokenOut;
        uint256 amountOut;
    }

    WETH public immutable weth9;
    mapping(bytes32 => SwapConfig) public configs;

    constructor(WETH weth9_) {
        weth9 = weth9_;
    }

    receive() external payable { }

    function setSwap(bytes calldata path_, address tokenIn_, address tokenOut_, uint256 amountOut_) external {
        configs[keccak256(path_)] = SwapConfig({ configured: true, tokenIn: tokenIn_, tokenOut: tokenOut_, amountOut: amountOut_ });
    }

    function exactInput(ISwapRouter.ExactInputParams calldata params) external payable returns (uint256 amountOut) {
