        if (cfg.tokenOut == address(weth9)) {
            weth9.deposit{ value: amountOut }();
            require(weth9.transfer(params.recipient, amountOut), "weth xfr failed");
        } else {
            MockERC20(cfg.tokenOut).mint(params.recipient, amountOut);
        }
    }
