        tokenA = new MockERC20("Token A", "A");
        tokenB = new MockERC20("Token B", "B");

        vm.deal(address(router), 1000 ether);
    }

    /// -------------------------------------------------------------------
    /// helpers
    /// -------------------------------------------------------------------

    function _path(address tokenIn_, uint24 fee_, address tokenOut_) internal pure returns (bytes memory) {
        return abi.encodePacked(tokenIn_, fee_, tokenOut_);
    }

    function _eip(bytes memory path_, address recipient_, uint256 amountIn_) internal view returns (ISwapRouter.ExactInputParams memory) {
        return ISwapRouter.ExactInputParams({
            path: path_,
            recipient: recipient_,
            deadline: block.timestamp + 1000,
            amountIn: amountIn_,
            amountOutMinimum: 0
        });
    }

    function _emptyEips() internal pure returns (ISwapRouter.ExactInputParams[] memory eips) {
        eips = new ISwapRouter.ExactInputParams[](0);
    }

    /// -------------------------------------------------------------------
    /// constructor
    /// -------------------------------------------------------------------

    function test_Constructor_SetsImmutables() public {
        assertEq(address(uni.swapperFactory()), address(factory));
        assertEq(address(uni.swapRouter()), address(router));
        assertEq(address(uni.weth9()), address(weth9));
    }

    /// -------------------------------------------------------------------
    /// receive
    /// -------------------------------------------------------------------

    function test_Receive_AcceptsETH() public {
        uint256 amount = 3 ether;
        (bool ok,) = address(uni).call{ value: amount }("");
        assertTrue(ok);
        assertEq(address(uni).balance, amount);
    }

    /// -------------------------------------------------------------------
    /// initFlash
    /// -------------------------------------------------------------------

    function test_InitFlash_ForwardsQuoteParamsAndCallbackData() public {
        swapper.configureCallback(address(0), 0, false);

        QuoteParams[] memory quoteParams = new QuoteParams[](0);
        UniV3Swap.FlashCallbackData memory fcd =
            UniV3Swap.FlashCallbackData({ exactInputParams: _emptyEips(), excessRecipient: excessRecipient });
        UniV3Swap.InitFlashParams memory params =
            UniV3Swap.InitFlashParams({ quoteParams: quoteParams, flashCallbackData: fcd });

        uni.initFlash(ISwapperImpl(address(swapper)), params);

        assertEq(swapper.lastQuoteParamsLength(), 0);

        UniV3Swap.FlashCallbackData memory decoded =
            abi.decode(swapper.lastFlashData(), (UniV3Swap.FlashCallbackData));
        assertEq(decoded.excessRecipient, excessRecipient);
        assertEq(decoded.exactInputParams.length, 0);
    }

    function test_InitFlash_DoesNotForwardMsgValueToFlashCall() public {
        swapper.configureCallback(address(0), 0, false);

        UniV3Swap.FlashCallbackData memory fcd =
            UniV3Swap.FlashCallbackData({ exactInputParams: _emptyEips(), excessRecipient: excessRecipient });
        UniV3Swap.InitFlashParams memory params =
            UniV3Swap.InitFlashParams({ quoteParams: new QuoteParams[](0), flashCallbackData: fcd });

        uint256 value = 2 ether;
        uni.initFlash{ value: value }(ISwapperImpl(address(swapper)), params);

        // `initFlash` never forwards msg.value to `flash`, so it accumulates on UniV3Swap
        assertEq(address(uni).balance, value);
        assertEq(address(swapper).balance, 0);
    }

    function test_InitFlash_EndToEnd_ETHBeneficiary() public {
        // Simulate a trader who tops up with ETH to cover an oracle shortfall,
        // and Swapper calling back for an ETH beneficiary payout.
        uint256 topUp = 3 ether;
        uint256 amountToBeneficiary = 1 ether;
        swapper.configureCallback(address(0), amountToBeneficiary, true);

        UniV3Swap.FlashCallbackData memory fcd =
            UniV3Swap.FlashCallbackData({ exactInputParams: _emptyEips(), excessRecipient: excessRecipient });
        UniV3Swap.InitFlashParams memory params =
            UniV3Swap.InitFlashParams({ quoteParams: new QuoteParams[](0), flashCallbackData: fcd });

        uni.initFlash{ value: topUp }(ISwapperImpl(address(swapper)), params);

        assertEq(swapper.totalPayback(), amountToBeneficiary);
        assertEq(excessRecipient.balance, topUp - amountToBeneficiary);
        assertEq(address(uni).balance, 0);
        assertEq(weth9.balanceOf(address(uni)), 0);
    }

    /// -------------------------------------------------------------------
    /// swapperFlashCallback — ETH beneficiary
    /// -------------------------------------------------------------------

    function test_SwapperFlashCallback_ETH_NoSwaps_PaysBeneficiaryAndExcess() public {
        uint256 preFunded = 2 ether;
        uint256 amountToBeneficiary = 1.2 ether;
        vm.deal(address(uni), preFunded);

        UniV3Swap.FlashCallbackData memory fcd =
            UniV3Swap.FlashCallbackData({ exactInputParams: _emptyEips(), excessRecipient: excessRecipient });

        vm.prank(address(swapper));
        uni.swapperFlashCallback(address(0), amountToBeneficiary, abi.encode(fcd));

        assertEq(swapper.totalPayback(), amountToBeneficiary);
        assertEq(excessRecipient.balance, preFunded - amountToBeneficiary);
        assertEq(address(uni).balance, 0);
        assertEq(weth9.balanceOf(address(uni)), 0);
    }

    function test_SwapperFlashCallback_ETH_ExactAmount_NoExcessTransfer() public {
        uint256 preFunded = 1 ether;
        vm.deal(address(uni), preFunded);

        UniV3Swap.FlashCallbackData memory fcd =
            UniV3Swap.FlashCallbackData({ exactInputParams: _emptyEips(), excessRecipient: excessRecipient });

        vm.prank(address(swapper));
        uni.swapperFlashCallback(address(0), preFunded, abi.encode(fcd));

        assertEq(swapper.totalPayback(), preFunded);
        assertEq(excessRecipient.balance, 0);
    }

    function test_SwapperFlashCallback_ETH_RevertsInsufficientFunds() public {
        vm.deal(address(uni), 1 ether);

        UniV3Swap.FlashCallbackData memory fcd =
            UniV3Swap.FlashCallbackData({ exactInputParams: _emptyEips(), excessRecipient: excessRecipient });

        vm.prank(address(swapper));
        vm.expectRevert(UniV3Swap.InsufficientFunds.selector);
        uni.swapperFlashCallback(address(0), 2 ether, abi.encode(fcd));
    }

    function test_SwapperFlashCallback_ETH_ViaSwap() public {
        uint256 amountIn = 100e18;
        uint256 amountOut = 4 ether;
        uint256 amountToBeneficiary = 3 ether;

        tokenA.mint(address(uni), amountIn);

        bytes memory path = _path(address(tokenA), 3000, address(weth9));
        router.setSwap(path, address(tokenA), address(weth9), amountOut);

        ISwapRouter.ExactInputParams[] memory eips = new ISwapRouter.ExactInputParams[](1);
        eips[0] = _eip(path, address(uni), amountIn);

        UniV3Swap.FlashCallbackData memory fcd =
            UniV3Swap.FlashCallbackData({ exactInputParams: eips, excessRecipient: excessRecipient });

        vm.prank(address(swapper));
        uni.swapperFlashCallback(address(0), amountToBeneficiary, abi.encode(fcd));

        assertEq(tokenA.balanceOf(address(uni)), 0);
        assertEq(swapper.totalPayback(), amountToBeneficiary);
        assertEq(excessRecipient.balance, amountOut - amountToBeneficiary);
        assertEq(weth9.balanceOf(address(uni)), 0);
    }

    function test_SwapperFlashCallback_ETH_PreexistingBalanceCountsTowardTotalOut() public {
        // Trader-supplied ETH top-up should count toward the ETH-beneficiary total
        // without requiring any swap at all.
        uint256 preFunded = 5 ether;
        vm.deal(address(uni), preFunded);

        UniV3Swap.FlashCallbackData memory fcd =
            UniV3Swap.FlashCallbackData({ exactInputParams: _emptyEips(), excessRecipient: excessRecipient });

        vm.prank(address(swapper));
        uni.swapperFlashCallback(address(0), preFunded, abi.encode(fcd));

        assertEq(swapper.totalPayback(), preFunded);
    }

    /// -------------------------------------------------------------------
    /// swapperFlashCallback — ERC20 beneficiary
    /// -------------------------------------------------------------------

    function test_SwapperFlashCallback_ERC20_NoSwaps_ApprovesAndSendsExcess() public {
        uint256 preFunded = 500e18;
        uint256 amountToBeneficiary = 200e18;
        tokenB.mint(address(uni), preFunded);

        UniV3Swap.FlashCallbackData memory fcd =
            UniV3Swap.FlashCallbackData({ exactInputParams: _emptyEips(), excessRecipient: excessRecipient });

        vm.prank(address(swapper));
        uni.swapperFlashCallback(address(tokenB), amountToBeneficiary, abi.encode(fcd));

        assertEq(tokenB.allowance(address(uni), address(swapper)), amountToBeneficiary);
        assertEq(tokenB.balanceOf(excessRecipient), preFunded - amountToBeneficiary);
        assertEq(tokenB.balanceOf(address(uni)), amountToBeneficiary);
    }

    function test_SwapperFlashCallback_ERC20_RevertsInsufficientFunds() public {
        tokenB.mint(address(uni), 10e18);

        UniV3Swap.FlashCallbackData memory fcd =
            UniV3Swap.FlashCallbackData({ exactInputParams: _emptyEips(), excessRecipient: excessRecipient });

        vm.prank(address(swapper));
        vm.expectRevert(UniV3Swap.InsufficientFunds.selector);
        uni.swapperFlashCallback(address(tokenB), 20e18, abi.encode(fcd));
    }

    function test_SwapperFlashCallback_ERC20_ViaSingleSwap() public {
        uint256 amountIn = 50e18;
        uint256 amountOut = 80e18;
        uint256 amountToBeneficiary = 60e18;

        tokenA.mint(address(uni), amountIn);

        bytes memory path = _path(address(tokenA), 500, address(tokenB));
        router.setSwap(path, address(tokenA), address(tokenB), amountOut);

        ISwapRouter.ExactInputParams[] memory eips = new ISwapRouter.ExactInputParams[](1);
        eips[0] = _eip(path, address(uni), amountIn);

        UniV3Swap.FlashCallbackData memory fcd =
            UniV3Swap.FlashCallbackData({ exactInputParams: eips, excessRecipient: excessRecipient });

        vm.prank(address(swapper));
        uni.swapperFlashCallback(address(tokenB), amountToBeneficiary, abi.encode(fcd));

        assertEq(tokenA.balanceOf(address(uni)), 0);
        assertEq(tokenA.balanceOf(address(router)), amountIn);
        assertEq(tokenB.allowance(address(uni), address(swapper)), amountToBeneficiary);
        assertEq(tokenB.balanceOf(excessRecipient), amountOut - amountToBeneficiary);
    }

    function test_SwapperFlashCallback_ERC20_ViaMultipleSwaps_AggregatesTotalOut() public {
        uint256 amountIn1 = 10e18;
        uint256 amountOut1 = 15e18;
        uint256 amountIn2 = 20e18;
        uint256 amountOut2 = 25e18;
        uint256 amountToBeneficiary = 35e18;

        MockERC20 tokenC = new MockERC20("Token C", "C");
        tokenA.mint(address(uni), amountIn1);
        tokenC.mint(address(uni), amountIn2);

        bytes memory path1 = _path(address(tokenA), 500, address(tokenB));
        bytes memory path2 = _path(address(tokenC), 3000, address(tokenB));
        router.setSwap(path1, address(tokenA), address(tokenB), amountOut1);
        router.setSwap(path2, address(tokenC), address(tokenB), amountOut2);

