        assertEq(tokenB.allowance(address(uni), address(swapper)), preFunded);
    }

    function test_SwapperFlashCallback_ERC20_PreexistingETHIsWrappedButUnused() public {
        // ETH sitting on the contract always gets wrapped into WETH at the top of
        // the callback, even when the beneficiary token is an ERC20 — that WETH is
        // never swept back out in this branch, matching the contract's own warning
        // that it should never be left holding funds without further verification.
        uint256 strayEth = 1 ether;
        vm.deal(address(uni), strayEth);

        uint256 preFunded = 10e18;
        tokenB.mint(address(uni), preFunded);

        UniV3Swap.FlashCallbackData memory fcd =
            UniV3Swap.FlashCallbackData({ exactInputParams: _emptyEips(), excessRecipient: excessRecipient });

        vm.prank(address(swapper));
        uni.swapperFlashCallback(address(tokenB), preFunded, abi.encode(fcd));

        assertEq(weth9.balanceOf(address(uni)), strayEth);
        assertEq(address(uni).balance, 0);
        assertEq(tokenB.allowance(address(uni), address(swapper)), preFunded);
    }

    /// -------------------------------------------------------------------
    /// access control (documented lack thereof)
    /// -------------------------------------------------------------------

    /// @dev `swapperFlashCallback` has no caller restriction: whoever calls it
    /// becomes the address that receives `payback()`/approvals and the excess
    /// recipient can be set arbitrarily. This test documents that any stray
