        assertEq(address(uni).balance, 0);
        assertEq(tokenB.allowance(address(uni), address(swapper)), preFunded);
    }

    /// -------------------------------------------------------------------
    /// access control (documented lack thereof)
    /// -------------------------------------------------------------------

    /// @dev `swapperFlashCallback` has no caller restriction: whoever calls it
    /// becomes the address that receives `payback()`/approvals and the excess
    /// recipient can be set arbitrarily. This test documents that any stray
    /// balance left on the contract can be swept out by a direct, unsolicited
    /// call — underscoring the contract's own "DO NOT HOLD FUNDS" warning.
    function test_SwapperFlashCallback_CallableDirectlyByAnyone() public {
        uint256 strayEth = 1 ether;
        vm.deal(address(uni), strayEth);

        UniV3Swap.FlashCallbackData memory fcd =
            UniV3Swap.FlashCallbackData({ exactInputParams: _emptyEips(), excessRecipient: attacker });

        // `attacker` is a plain EOA-like address (no code) — a call to its
        // `payback()` "function" trivially succeeds under EVM semantics.
        vm.prank(attacker);
        uni.swapperFlashCallback(address(0), 0, abi.encode(fcd));

        assertEq(attacker.balance, strayEth);
        assertEq(address(uni).balance, 0);
    }
