import { AddressSet } from "src/utils/AddressSet.sol";
import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";

contract AddressSetTest is Test {
    AddressSet internal set;

    address internal owner = address(this);
    address internal alice = address(0xA11CE);
    address internal bob = address(0xB0B);
    address internal carol = address(0xCA201);
    address internal notOwner = address(0xBEEF);

    event AddressSetAltered(address indexed account, AddressSet.AddressSetOperation indexed operation);

    function setUp() public {
        set = new AddressSet();
    }

    // ============================================
    // CONSTRUCTOR / OWNERSHIP
    // ============================================

    function test_constructor_setsDeployerAsOwner() public view {
        assertEq(set.owner(), owner);
    }

    function test_constructor_initialStateEmpty() public view {
        assertEq(set.length(), 0);
        assertEq(set.values().length, 0);
    }

    // ============================================
    // add(address) - single
    // ============================================

    function test_addSingle_addsAddress() public {
        set.add(alice);
        assertTrue(set.contains(alice));
        assertEq(set.length(), 1);
    }

    function test_addSingle_emitsEvent() public {
        vm.expectEmit(true, true, false, true);
        emit AddressSetAltered(alice, AddressSet.AddressSetOperation.Add);
        set.add(alice);
    }

    function test_addSingle_revertsOnZeroAddress() public {
        vm.expectRevert(
            abi.encodeWithSelector(
                AddressSet.IllegalAddressSetOperation.selector, address(0), "Address zero not allowed."
            )
        );
        set.add(address(0));
    }

    function test_addSingle_revertsOnDuplicate() public {
        set.add(alice);
        vm.expectRevert(
            abi.encodeWithSelector(
                AddressSet.IllegalAddressSetOperation.selector, alice, "Address already in set."
            )
        );
        set.add(alice);
    }

    function test_addSingle_revertsIfNotOwner() public {
        vm.prank(notOwner);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, notOwner));
        set.add(alice);
    }

    function test_addSingle_multipleDistinctAddresses() public {
        set.add(alice);
        set.add(bob);
        set.add(carol);
        assertEq(set.length(), 3);
        assertTrue(set.contains(alice));
        assertTrue(set.contains(bob));
        assertTrue(set.contains(carol));
    }

    // ============================================
    // add(address[]) - batch
    // ============================================

    function test_addBatch_addsAllAddresses() public {
        address[] memory accounts = new address[](3);
        accounts[0] = alice;
        accounts[1] = bob;
        accounts[2] = carol;

        set.add(accounts);

        assertEq(set.length(), 3);
        assertTrue(set.contains(alice));
        assertTrue(set.contains(bob));
        assertTrue(set.contains(carol));
    }

    function test_addBatch_emitsEventPerAddress() public {
        address[] memory accounts = new address[](2);
        accounts[0] = alice;
        accounts[1] = bob;

        vm.expectEmit(true, true, false, true);
        emit AddressSetAltered(alice, AddressSet.AddressSetOperation.Add);
        vm.expectEmit(true, true, false, true);
        emit AddressSetAltered(bob, AddressSet.AddressSetOperation.Add);

        set.add(accounts);
    }

    function test_addBatch_revertsOnEmptyArray() public {
        address[] memory accounts = new address[](0);
        vm.expectRevert(AddressSet.EmptyArray.selector);
        set.add(accounts);
    }

    function test_addBatch_revertsOnZeroAddressInArray() public {
        address[] memory accounts = new address[](2);
        accounts[0] = alice;
        accounts[1] = address(0);

        vm.expectRevert(
            abi.encodeWithSelector(
                AddressSet.IllegalAddressSetOperation.selector, address(0), "Address zero not allowed."
            )
        );
        set.add(accounts);
    }

    function test_addBatch_revertsOnDuplicateWithinArray() public {
        address[] memory accounts = new address[](2);
        accounts[0] = alice;
        accounts[1] = alice;

        vm.expectRevert(
            abi.encodeWithSelector(
                AddressSet.IllegalAddressSetOperation.selector, alice, "Address already in set."
            )
