        address[] memory accounts = new address[](2);
        accounts[0] = alice;
        accounts[1] = address(0);

        vm.expectRevert(
            abi.encodeWithSelector(
                AddressSet.IllegalAddressSetOperation.selector, address(0), "Address zero not allowed."
            )
        );
        set.add(accounts);

        assertFalse(set.contains(alice));
        assertEq(set.length(), 0);
    }

    // ============================================
    // remove(address) - single
    // ============================================

    function test_removeSingle_removesAddress() public {
        set.add(alice);
        set.remove(alice);
        assertFalse(set.contains(alice));
        assertEq(set.length(), 0);
    }

    function test_removeSingle_emitsEvent() public {
        set.add(alice);
        vm.expectEmit(true, true, false, true);
        emit AddressSetAltered(alice, AddressSet.AddressSetOperation.Remove);
        set.remove(alice);
    }

    function test_removeSingle_revertsOnZeroAddress() public {
        vm.expectRevert(
            abi.encodeWithSelector(
                AddressSet.IllegalAddressSetOperation.selector, address(0), "Address zero not allowed."
            )
        );
        set.remove(address(0));
    }

    function test_removeSingle_revertsIfNotInSet() public {
        vm.expectRevert(
            abi.encodeWithSelector(
                AddressSet.IllegalAddressSetOperation.selector, alice, "Address not in set."
            )
        );
        set.remove(alice);
    }

    function test_removeSingle_revertsIfAlreadyRemoved() public {
        set.add(alice);
        set.remove(alice);
        vm.expectRevert(
            abi.encodeWithSelector(
                AddressSet.IllegalAddressSetOperation.selector, alice, "Address not in set."
            )
        );
        set.remove(alice);
    }

    function test_removeSingle_revertsIfNotOwner() public {
        set.add(alice);
        vm.prank(notOwner);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, notOwner));
        set.remove(alice);
    }

    // ============================================
    // remove(address[]) - batch
    // ============================================

    function test_removeBatch_removesAllAddresses() public {
        address[] memory accounts = new address[](3);
        accounts[0] = alice;
        accounts[1] = bob;
        accounts[2] = carol;
        set.add(accounts);

        set.remove(accounts);

        assertEq(set.length(), 0);
        assertFalse(set.contains(alice));
        assertFalse(set.contains(bob));
        assertFalse(set.contains(carol));
    }

    function test_removeBatch_emitsEventPerAddress() public {
        address[] memory accounts = new address[](2);
        accounts[0] = alice;
        accounts[1] = bob;
        set.add(accounts);

