// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.20;

/**
 * @dev Test suite for SparkStrategy.
 *
 * IMPORTANT ASSUMPTIONS
 * ----------------------
 * Only `SparkStrategy.sol` was provided for this task; its parent contracts
 * (`ERC4626Strategy`, the underlying `BaseStrategy`, and the "dragon" fork of
 * Yearn V3's `TokenizedStrategy`) live elsewhere in the repository and were
 * not shown. Those contracts follow the well known Yearn V3 tokenized-strategy
 * pattern: the strategy's constructor delegatecalls into an `initialize(...)`
 * function on `_tokenizedStrategyAddress`, and `onlyKeepers` / `TokenizedStrategy`
 * calls are routed through a `fallback()` delegatecall into that same address,
 * operating on the strategy's own storage.
 *
 * To exercise `SparkStrategy` end-to-end without the real implementation
 * contract, this suite deploys a purpose-built `MockDragonTokenizedStrategy`
 * at `_tokenizedStrategyAddress`. It:
 *   - implements `initialize(...)` with the parameter order implied by
 *     `SparkStrategy`'s constructor (asset, name, symbol, management, keeper,
 *     emergencyAdmin, donationAddress, enableBurning),
 *   - implements `dragonRouter()`, `management()`, `keeper()`,
 *     `requireManagement(address)` and `requireKeeperOrManagement(address)`
 *     (the calls `onlyKeepers`/`onlyManagement` modifiers are expected to make),
 *   - falls back to a permissive no-op for any other selector, so construction
 *     cannot revert even if the real `initialize` signature differs slightly,
 *   - exposes explicit `setManagement/setKeeper/setDragonRouter` setters that
 *     the test harness calls directly (through the strategy's fallback) after
 *     deployment, so role wiring for the tests below does not depend on
 *     guessing the exact `initialize` signature correctly.
 *
 * All storage in the mock lives at a namespaced slot (diamond-storage style)
 * to avoid colliding with `SparkStrategy`/`ERC4626Strategy`'s own storage
 * layout when reached via `delegatecall`.
 *
 * The suite focuses on the logic actually introduced by `SparkStrategy`:
 * `sweepAirdrop`.
 */

import { Test } from "forge-std/Test.sol";
import { SparkStrategy } from "src/strategies/yieldDonating/SparkStrategy.sol";

import { IERC20 } from "@openzeppelin/contracts/interfaces/IERC20.sol";
import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import { ERC4626 } from "@openzeppelin/contracts/token/ERC20/extensions/ERC4626.sol";

// ---------------------------------------------------------------------------
// Mocks
// ---------------------------------------------------------------------------

contract MockERC20 is ERC20 {
    uint8 private immutable _decimals;

    constructor(string memory name_, string memory symbol_, uint8 decimals_) ERC20(name_, symbol_) {
        _decimals = decimals_;
    }

    function decimals() public view override returns (uint8) {
        return _decimals;
    }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

contract MockERC4626Vault is ERC20, ERC4626 {
    constructor(
        IERC20 asset_,
        string memory name_,
        string memory symbol_
    ) ERC20(name_, symbol_) ERC4626(asset_) { }
}

library DragonMockStorage {
    // Namespaced slot so this mock's storage never collides with whatever
    // storage layout SparkStrategy / ERC4626Strategy actually use when this
    // contract's code runs via `delegatecall` from the strategy.
    bytes32 internal constant SLOT = keccak256("test.mock.dragon.tokenized.strategy.storage");

    struct Data {
        address asset;
        string name;
        string symbol;
        address management;
        address keeper;
        address emergencyAdmin;
        address dragonRouter;
        bool enableBurning;
        bool initialized;
    }

    function data() internal pure returns (Data storage d) {
        bytes32 slot = SLOT;
        assembly {
            d.slot := slot
        }
    }
}

/// @dev Minimal stand-in for the real ("dragon") TokenizedStrategy
/// implementation contract used by the yield-donating strategies base.
contract MockDragonTokenizedStrategy {
    function initialize(
        address _asset,
        string memory _name,
        string memory _symbol,
        address _management,
        address _keeper,
        address _emergencyAdmin,
        address _donationAddress,
        bool _enableBurning
    ) external {
        DragonMockStorage.Data storage d = DragonMockStorage.data();
        d.asset = _asset;
        d.name = _name;
        d.symbol = _symbol;
        d.management = _management;
        d.keeper = _keeper;
        d.emergencyAdmin = _emergencyAdmin;
        d.dragonRouter = _donationAddress;
        d.enableBurning = _enableBurning;
        d.initialized = true;
    }

    function setManagement(address _management) external {
        DragonMockStorage.data().management = _management;
    }

    function setKeeper(address _keeper) external {
        DragonMockStorage.data().keeper = _keeper;
    }

    function setDragonRouter(address _dragonRouter) external {
        DragonMockStorage.data().dragonRouter = _dragonRouter;
    }

    function dragonRouter() external view returns (address) {
        return DragonMockStorage.data().dragonRouter;
    }

    function management() external view returns (address) {
        return DragonMockStorage.data().management;
    }

    function keeper() external view returns (address) {
        return DragonMockStorage.data().keeper;
    }

    function requireManagement(address _sender) external view {
        require(_sender == DragonMockStorage.data().management, "!management");
    }

    function requireKeeperOrManagement(address _sender) external view {
        DragonMockStorage.Data storage d = DragonMockStorage.data();
        require(_sender == d.keeper || _sender == d.management, "!keeper");
    }

    function requireEmergencyAuthorized(address _sender) external view {
        DragonMockStorage.Data storage d = DragonMockStorage.data();
        require(_sender == d.emergencyAdmin || _sender == d.management, "!emergency");
    }

    // Permissive fallback: any selector this mock doesn't explicitly know
    // about (e.g. profit-unlock accounting, fee config, ERC20 plumbing for
    // the strategy's own shares, ...) succeeds as a no-op instead of
    // reverting, so strategy deployment/operation doesn't unexpectedly fail
    // due to interface details this suite could not observe.
    fallback() external {
        // no-op
    }
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

contract SparkStrategyTest is Test {
    SparkStrategy internal strategy;
    MockERC20 internal asset;
    MockERC4626Vault internal vault;
    MockDragonTokenizedStrategy internal tokenizedStrategyImpl;
    MockERC20 internal airdropToken;

    address internal management = makeAddr("management");
    address internal keeper = makeAddr("keeper");
    address internal emergencyAdmin = makeAddr("emergencyAdmin");
    address internal dragonRouter = makeAddr("dragonRouter");
    address internal stranger = makeAddr("stranger");

    event TokenSwept(address indexed token, uint256 amount, address indexed recipient);

    function setUp() public {
        asset = new MockERC20("Mock USDC", "mUSDC", 6);
        vault = new MockERC4626Vault(IERC20(address(asset)), "Mock Spark Vault", "spMUSDC");
        tokenizedStrategyImpl = new MockDragonTokenizedStrategy();

        strategy = new SparkStrategy(
            address(vault),
            address(asset),
            "Spark USDC Strategy",
            "osSparkUSDC",
            management,
            keeper,
            emergencyAdmin,
            dragonRouter,
            true,
            address(tokenizedStrategyImpl)
        );

        // Defensive re-wiring: guarantee role storage is set correctly
        // regardless of whether the constructor's own `initialize` call used
        // exactly the parameter order this mock assumes.
        (bool okM,) = address(strategy).call(abi.encodeWithSignature("setManagement(address)", management));
        (bool okK,) = address(strategy).call(abi.encodeWithSignature("setKeeper(address)", keeper));
        (bool okD,) = address(strategy).call(abi.encodeWithSignature("setDragonRouter(address)", dragonRouter));
        require(okM && okK && okD, "mock role wiring failed");

        airdropToken = new MockERC20("Random Airdrop", "DROP", 18);
    }

    // -- access control --------------------------------------------------

    function test_SweepAirdrop_RevertsForNonKeeperNonManagement() public {
        airdropToken.mint(address(strategy), 100e18);

        vm.prank(stranger);
        vm.expectRevert();
        strategy.sweepAirdrop(address(airdropToken));
    }

    function test_SweepAirdrop_CallableByKeeper() public {
        airdropToken.mint(address(strategy), 100e18);

        vm.prank(keeper);
        strategy.sweepAirdrop(address(airdropToken));

        assertEq(airdropToken.balanceOf(dragonRouter), 100e18);
    }

    function test_SweepAirdrop_CallableByManagement() public {
        airdropToken.mint(address(strategy), 100e18);

        vm.prank(management);
        strategy.sweepAirdrop(address(airdropToken));

        assertEq(airdropToken.balanceOf(dragonRouter), 100e18);
    }

    // -- protected-token guards -------------------------------------------

    function test_SweepAirdrop_RevertsWhenSweepingAsset() public {
        asset.mint(address(strategy), 1_000e6);

        vm.prank(keeper);
        vm.expectRevert(bytes("SparkStrategy: Cannot sweep main asset"));
        strategy.sweepAirdrop(address(asset));
    }

    function test_SweepAirdrop_RevertsWhenSweepingVaultShares() public {
        // Give the strategy a vault-share balance directly (no need to route
        // through deposit/report flows we don't have visibility into).
        deal(address(vault), address(strategy), 500e6);

