    // Namespaced slot so this mock's storage never collides with whatever
    // storage layout SparkStrategy / ERC4626Strategy actually use when this
    // contract's code runs via `delegatecall` from the strategy.
    bytes32 internal constant SLOT = keccak256("test.mock.dragon.tokenized.strategy.storage");

