    fallback() external payable {
        assembly {
            return(0, 0)
        }
    }
}

/*//////////////////////////////////////////////////////////////////////
                                TEST SUITE
//////////////////////////////////////////////////////////////////////*/

contract SparkStrategyTest is Test {
    /// @dev Re-declared locally so `vm.expectEmit` can match on topic0; the
    ///      hash is identical regardless of which contract "declares" it.
    event TokenSwept(address indexed token, uint256 amount, address indexed recipient);

