        // in the constructor. Individual tests may override these via
        // `_mockRoles` to exercise different branches of `onlyKeepers`.
        _mockRoles(keeper, management, dragonRouter);

        rewardToken = new MockERC20("Airdropped Governance Token", "AIRDROP");
    }

    /*//////////////////////////////////////////////////////////////////
                                  HELPERS
    //////////////////////////////////////////////////////////////////*/

    function _mockRoles(address _keeper, address _management, address _dragonRouter) internal {
        vm.mockCall(address(strategy), abi.encodeWithSignature("keeper()"), abi.encode(_keeper));
        vm.mockCall(address(strategy), abi.encodeWithSignature("management()"), abi.encode(_management));
        vm.mockCall(
            address(strategy), abi.encodeWithSignature("dragonRouter()"), abi.encode(_dragonRouter)
        );
