    //////////////////////////////////////////////////////////////////*/

    function test_sweepAirdrop_revertsWhenCallerIsNotKeeperOrManagement() public {
        rewardToken.mint(address(strategy), 100e18);

        vm.prank(stranger);
        vm.expectRevert();
        strategy.sweepAirdrop(address(rewardToken));
    }

    function test_sweepAirdrop_revertsWhenCallerIsEmergencyAdminOnly() public {
        // emergencyAdmin is distinct from keeper/management per setUp, and
        // per the strategy's NatSpec is NOT authorized to sweep.
        rewardToken.mint(address(strategy), 100e18);

        vm.prank(emergencyAdmin);
        vm.expectRevert();
        strategy.sweepAirdrop(address(rewardToken));
    }

    function test_sweepAirdrop_succeedsWhenCalledByKeeper() public {
        uint256 amount = 50e18;
        rewardToken.mint(address(strategy), amount);

        vm.expectEmit(true, true, false, true, address(strategy));
        emit TokenSwept(address(rewardToken), amount, dragonRouter);

        vm.prank(keeper);
        strategy.sweepAirdrop(address(rewardToken));

        assertEq(rewardToken.balanceOf(address(strategy)), 0, "strategy balance should be zero");
        assertEq(rewardToken.balanceOf(dragonRouter), amount, "dragon router should receive swept tokens");
    }

    function test_sweepAirdrop_succeedsWhenCalledByManagement() public {
        // Point `keeper()` at an unrelated address so this only passes if the
        // `|| msg.sender == management` branch is what authorizes the call.
        _mockRoles(makeAddr("someOtherKeeper"), management, dragonRouter);

        uint256 amount = 75e18;
        rewardToken.mint(address(strategy), amount);

        vm.expectEmit(true, true, false, true, address(strategy));
        emit TokenSwept(address(rewardToken), amount, dragonRouter);

        vm.prank(management);
        strategy.sweepAirdrop(address(rewardToken));

        assertEq(rewardToken.balanceOf(address(strategy)), 0);
        assertEq(rewardToken.balanceOf(dragonRouter), amount);
    }

    /*//////////////////////////////////////////////////////////////////
                          PROTECTED TOKEN GUARDS
    //////////////////////////////////////////////////////////////////*/

    function test_sweepAirdrop_revertsWhenSweepingMainAsset() public {
        asset.mint(address(strategy), 1_000e18);

        vm.prank(keeper);
        vm.expectRevert(bytes("SparkStrategy: Cannot sweep main asset"));
        strategy.sweepAirdrop(address(asset));
    }

    function test_sweepAirdrop_revertsWhenSweepingVaultShares() public {
        // Give the strategy some vault shares by minting asset then
        // depositing directly (bypassing strategy internals is fine here;
        // we only need `address(vault)` to be a token the strategy could
        // theoretically hold and that must be blocked from sweeping).
        asset.mint(address(this), 10e18);
        asset.approve(address(vault), 10e18);
        vault.deposit(10e18, address(strategy));

        vm.prank(keeper);
        vm.expectRevert(bytes("SparkStrategy: Cannot sweep vault shares"));
        strategy.sweepAirdrop(address(vault));
    }

    function test_sweepAirdrop_assetGuardTakesPrecedenceEvenWithZeroBalance() public {
        // Guard checks run before the balance check, so this must revert
        // with the asset-specific message even though the strategy holds no
        // asset balance at all.
        vm.prank(keeper);
        vm.expectRevert(bytes("SparkStrategy: Cannot sweep main asset"));
        strategy.sweepAirdrop(address(asset));
    }

    function test_sweepAirdrop_vaultGuardTakesPrecedenceEvenWithZeroBalance() public {
        vm.prank(keeper);
        vm.expectRevert(bytes("SparkStrategy: Cannot sweep vault shares"));
        strategy.sweepAirdrop(address(vault));
    }

    /*//////////////////////////////////////////////////////////////////
                              BALANCE CHECK
    //////////////////////////////////////////////////////////////////*/

    function test_sweepAirdrop_revertsWhenNoBalance() public {
        // rewardToken balance is zero by default in this fresh setUp.
        vm.prank(keeper);
        vm.expectRevert(bytes("SparkStrategy: No balance to sweep"));
        strategy.sweepAirdrop(address(rewardToken));
    }

    function test_sweepAirdrop_revertsOnSecondCallAfterFullSweep() public {
        rewardToken.mint(address(strategy), 10e18);

        vm.prank(keeper);
        strategy.sweepAirdrop(address(rewardToken));

        // Balance is now zero; a second sweep of the same token must revert.
        vm.prank(keeper);
        vm.expectRevert(bytes("SparkStrategy: No balance to sweep"));
        strategy.sweepAirdrop(address(rewardToken));
    }

    /*//////////////////////////////////////////////////////////////////
                                CORRECTNESS
    //////////////////////////////////////////////////////////////////*/

    function test_sweepAirdrop_sweepsFullBalanceNotPartial() public {
        uint256 amount = 12345e15;
        rewardToken.mint(address(strategy), amount);
        // Some unrelated balance sitting in an arbitrary account should not
        // be touched or influence the sweep amount.
        rewardToken.mint(stranger, 999e18);

        vm.prank(keeper);
        strategy.sweepAirdrop(address(rewardToken));

        assertEq(rewardToken.balanceOf(dragonRouter), amount);
        assertEq(rewardToken.balanceOf(address(strategy)), 0);
        assertEq(rewardToken.balanceOf(stranger), 999e18, "unrelated balances must be untouched");
    }

    function test_sweepAirdrop_doesNotAffectAssetOrVaultBalances() public {
        // Strategy holds both protected tokens and an airdrop token
        // simultaneously; sweeping the airdrop token must leave the others
        // untouched.
        asset.mint(address(strategy), 500e18);

        asset.mint(address(this), 20e18);
        asset.approve(address(vault), 20e18);
        vault.deposit(20e18, address(strategy));

        uint256 airdropAmount = 3e18;
        rewardToken.mint(address(strategy), airdropAmount);

        vm.prank(keeper);
        strategy.sweepAirdrop(address(rewardToken));

        assertEq(asset.balanceOf(address(strategy)), 500e18, "asset balance must be untouched");
        assertEq(vault.balanceOf(address(strategy)), 20e18, "vault share balance must be untouched");
        assertEq(rewardToken.balanceOf(dragonRouter), airdropAmount);
    }

    function test_sweepAirdrop_multipleDistinctTokensCanBeSweptIndependently() public {
        MockERC20 secondReward = new MockERC20("Second Airdrop", "AIR2");

        rewardToken.mint(address(strategy), 4e18);
        secondReward.mint(address(strategy), 7e18);

        vm.prank(keeper);
        strategy.sweepAirdrop(address(rewardToken));

        vm.prank(management);
        strategy.sweepAirdrop(address(secondReward));

        assertEq(rewardToken.balanceOf(dragonRouter), 4e18);
        assertEq(secondReward.balanceOf(dragonRouter), 7e18);
    }

    function test_sweepAirdrop_sendsToCurrentDragonRouterAtCallTime() public {
        address newDragon = makeAddr("newDragonRouter");
        _mockRoles(keeper, management, newDragon);

        uint256 amount = 8e18;
        rewardToken.mint(address(strategy), amount);

        vm.expectEmit(true, true, false, true, address(strategy));
        emit TokenSwept(address(rewardToken), amount, newDragon);

        vm.prank(keeper);
        strategy.sweepAirdrop(address(rewardToken));

        assertEq(rewardToken.balanceOf(newDragon), amount);
        assertEq(rewardToken.balanceOf(dragonRouter), 0, "old dragon router must not receive funds");
    }

    /*//////////////////////////////////////////////////////////////////
                                  FUZZING
    //////////////////////////////////////////////////////////////////*/

    function testFuzz_sweepAirdrop_arbitraryAmounts(uint96 amount) public {
        vm.assume(amount > 0);
        rewardToken.mint(address(strategy), amount);

        vm.prank(keeper);
        strategy.sweepAirdrop(address(rewardToken));

        assertEq(rewardToken.balanceOf(address(strategy)), 0);
        assertEq(rewardToken.balanceOf(dragonRouter), amount);
    }

    function testFuzz_sweepAirdrop_revertsForNonAuthorizedCallers(address caller) public {
        vm.assume(caller != keeper && caller != management);
        rewardToken.mint(address(strategy), 1e18);

        vm.prank(caller);
        vm.expectRevert();
        strategy.sweepAirdrop(address(rewardToken));
    }

    function testFuzz_sweepAirdrop_neverAllowsSweepingProtectedTokens(uint96 amount) public {
        vm.assume(amount > 0);
        asset.mint(address(strategy), amount);

        vm.prank(keeper);
        vm.expectRevert(bytes("SparkStrategy: Cannot sweep main asset"));
        strategy.sweepAirdrop(address(asset));

        vm.prank(management);
        vm.expectRevert(bytes("SparkStrategy: Cannot sweep vault shares"));
        strategy.sweepAirdrop(address(vault));
    }
}
