}

/// @dev Minimal ERC4626 vault standing in for the Spark Protocol vault that
///      SparkStrategy deposits into. Only `asset()` correctness matters for
///      these tests since deposit/withdraw accounting lives in
///      ERC4626Strategy, which is out of scope for this suite.
contract MockERC4626Vault is ERC20, ERC4626 {
    constructor(IERC20 asset_) ERC20("Mock Spark Vault Shares", "mvTKN") ERC4626(asset_) {}
}

/// @dev Stand-in for the singleton TokenizedStrategy implementation contract
///      that BaseStrategy delegatecalls into (the Yearn-V3-style tokenized
///      strategy pattern). Its only job here is to make the SparkStrategy
///      constructor's internal delegatecall (e.g. an `initialize(...)` call)
///      succeed without reverting, regardless of exact signature. All the
///      role/getter calls the strategy makes against itself at runtime
///      (`keeper()`, `management()`, `dragonRouter()`) are intercepted
///      directly via `vm.mockCall` in the tests below, so this contract does
///      not need to implement real storage-backed logic.
contract FakeTokenizedStrategy {
    receive() external payable {}

    fallback() external payable {
        assembly {
            return(0, 0)
        }
    }
}

/*//////////////////////////////////////////////////////////////////////
                                TEST SUITE
