    }

    /*//////////////////////////////////////////////////////////////////
                              BALANCE CHECK
    //////////////////////////////////////////////////////////////////*/

    function test_sweepAirdrop_revertsWhenNoBalance() public {
        // rewardToken balance is zero by default in this fresh setUp.
        vm.prank(keeper);
        vm.expectRevert(bytes("SparkStrategy: No balance to sweep"));
        strategy.sweepAirdrop(address(rewardToken));
    }

