        vm.expectRevert(bytes("SparkStrategy: No balance to sweep"));
        strategy.sweepAirdrop(address(rewardToken));
    }

    /*//////////////////////////////////////////////////////////////////
                                CORRECTNESS
    //////////////////////////////////////////////////////////////////*/

    function test_sweepAirdrop_sweepsFullBalanceNotPartial() public {
