        rewardToken.mint(stranger, 999e18);

        vm.prank(keeper);
        strategy.sweepAirdrop(address(rewardToken));

        assertEq(rewardToken.balanceOf(dragonRouter), amount);
        assertEq(rewardToken.balanceOf(address(strategy)), 0);
        assertEq(rewardToken.balanceOf(stranger), 999e18, "unrelated balances must be untouched");
    }

    function test_sweepAirdrop_doesNotAffectAssetOrVaultBalances() public {
