contract MockERC20 is ERC20 {
    uint8 private immutable _decimalsOverride;

    constructor(string memory name_, string memory symbol_, uint8 decimals_) ERC20(name_, symbol_) {
        _decimalsOverride = decimals_;
    }

    function decimals() public view override returns (uint8) {
        return _decimalsOverride;
    }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

/// @dev Minimal ERC4626 vault standing in for the Spark Protocol vault that
///      `SparkStrategy` deposits into. Only used here as the `targetVault`
///      address so that the "cannot sweep vault shares" guard can be tested.
contract MockERC4626Vault is ERC4626 {
    constructor(IERC20 _asset, string memory _name, string memory _symbol) ERC20(_name, _symbol) ERC4626(_asset) {}
}

/// @dev Minimal stand-in for the shared `TokenizedStrategy` implementation
///      contract that the base strategy delegates admin/role lookups to.
///      Exposes the getters `sweepAirdrop` (via `ERC4626Strategy`/`BaseStrategy`)
///      is expected to rely on: `dragonRouter()`, `management()`, `keeper()`.
///      A permissive fallback is included so that any additional calls made
///      by the (unshown) base-contract constructor during initialization do
///      not cause the deployment to revert.
contract MockTokenizedStrategy {
    address public management;
    address public keeper;
    address public emergencyAdmin;
    address public dragonRouter;
    address public asset;

    constructor(address _management, address _keeper, address _emergencyAdmin, address _dragonRouter, address _asset) {
        management = _management;
        keeper = _keeper;
        emergencyAdmin = _emergencyAdmin;
        dragonRouter = _dragonRouter;
        asset = _asset;
    }

    // solhint-disable-next-line no-empty-blocks
    fallback() external payable {}

    // solhint-disable-next-line no-empty-blocks
    receive() external payable {}
}

/*//////////////////////////////////////////////////////////////////////
                                TEST SUITE
//////////////////////////////////////////////////////////////////////*/

contract SparkStrategyTest is Test {
