    }

    function test_computeStrategyAddress_revertsOnInvalidAsset(address badAsset) public {
        vm.assume(badAsset != factory.USDS());

        vm.expectRevert(
            abi.encodeWithSelector(SkyCompounderStrategyFactory.InvalidAsset.selector, badAsset, factory.USDS())
        );
        _compute(
            factory.USDS_REWARD_ADDRESS(),
            badAsset,
            NAME,
            SYMBOL,
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
            tokenizedStrategyImpl,
            address(factory)
        );
    }

    function test_computeStrategyAddress_checksVaultBeforeAsset(address badVault, address badAsset) public {
        vm.assume(badVault != factory.USDS_REWARD_ADDRESS());
        // Even when both vault and asset are wrong, the vault check must fire first.
        vm.expectRevert(
            abi.encodeWithSelector(
                SkyCompounderStrategyFactory.InvalidVault.selector, badVault, factory.USDS_REWARD_ADDRESS()
            )
        );
        _compute(
            badVault,
            badAsset,
            NAME,
            SYMBOL,
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
            tokenizedStrategyImpl,
            address(factory)
        );
    }

    function test_computeStrategyAddress_succeedsWithValidVaultAndAsset() public view {
        address predicted = _compute(
            factory.USDS_REWARD_ADDRESS(),
            factory.USDS(),
            NAME,
            SYMBOL,
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
            tokenizedStrategyImpl,
            address(factory)
        );
        assertTrue(predicted != address(0), "predicted address should not be zero");
    }

    /*//////////////////////////////////////////////////////////
                COMPUTE STRATEGY ADDRESS - DETERMINISM
    //////////////////////////////////////////////////////////*/

    function test_computeStrategyAddress_isDeterministic() public view {
        address a1 = _computeDefault();
        address a2 = _computeDefault();
        assertEq(a1, a2, "identical inputs must predict identical addresses");
    }

    function test_computeStrategyAddress_variesWithName() public view {
        address a1 = _computeDefault();
        address a2 = _compute(
            factory.USDS_REWARD_ADDRESS(),
            factory.USDS(),
            "Different Name",
            SYMBOL,
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
            tokenizedStrategyImpl,
            address(factory)
        );
        assertTrue(a1 != a2, "different name must change predicted address");
    }

    function test_computeStrategyAddress_variesWithSymbol() public view {
        address a1 = _computeDefault();
        address a2 = _compute(
            factory.USDS_REWARD_ADDRESS(),
            factory.USDS(),
            NAME,
            "DIFF",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
            tokenizedStrategyImpl,
            address(factory)
        );
        assertTrue(a1 != a2, "different symbol must change predicted address");
    }

    function test_computeStrategyAddress_variesWithManagement(address altManagement) public view {
        vm.assume(altManagement != management);
        address a1 = _computeDefault();
        address a2 = _compute(
            factory.USDS_REWARD_ADDRESS(),
            factory.USDS(),
            NAME,
            SYMBOL,
            altManagement,
            keeper,
            emergencyAdmin,
            donationAddress,
