        vm.assume(altKeeper != keeper);
        address a1 = _computeDefault();
        address a2 = _compute(
            factory.USDS_REWARD_ADDRESS(),
            factory.USDS(),
            NAME,
            SYMBOL,
            management,
            altKeeper,
            emergencyAdmin,
            donationAddress,
            true,
            tokenizedStrategyImpl,
            address(factory)
        );
        assertTrue(a1 != a2, "different keeper must change predicted address");
    }

    function test_computeStrategyAddress_variesWithEmergencyAdmin(address altEmergencyAdmin) public view {
        vm.assume(altEmergencyAdmin != emergencyAdmin);
        address a1 = _computeDefault();
        address a2 = _compute(
            factory.USDS_REWARD_ADDRESS(),
            factory.USDS(),
            NAME,
            SYMBOL,
            management,
            keeper,
            altEmergencyAdmin,
            donationAddress,
            true,
            tokenizedStrategyImpl,
            address(factory)
        );
        assertTrue(a1 != a2, "different emergencyAdmin must change predicted address");
    }

    function test_computeStrategyAddress_variesWithDonationAddress(address altDonationAddress) public view {
        vm.assume(altDonationAddress != donationAddress);
        address a1 = _computeDefault();
        address a2 = _compute(
            factory.USDS_REWARD_ADDRESS(),
            factory.USDS(),
            NAME,
            SYMBOL,
            management,
            keeper,
            emergencyAdmin,
            altDonationAddress,
            true,
            tokenizedStrategyImpl,
            address(factory)
        );
        assertTrue(a1 != a2, "different donationAddress must change predicted address");
    }

    function test_computeStrategyAddress_variesWithEnableBurning() public view {
        address a1 = _computeDefault();
        address a2 = _compute(
            factory.USDS_REWARD_ADDRESS(),
            factory.USDS(),
            NAME,
            SYMBOL,
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            false,
            tokenizedStrategyImpl,
            address(factory)
        );
        assertTrue(a1 != a2, "different enableBurning flag must change predicted address");
    }

    function test_computeStrategyAddress_variesWithTokenizedStrategyAddress(address altImpl) public view {
        vm.assume(altImpl != tokenizedStrategyImpl);
        address a1 = _computeDefault();
        address a2 = _compute(
            factory.USDS_REWARD_ADDRESS(),
            factory.USDS(),
            NAME,
            SYMBOL,
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
            altImpl,
            address(factory)
        );
        assertTrue(a1 != a2, "different tokenizedStrategyAddress must change predicted address");
    }

    function test_computeStrategyAddress_variesWithDeployer(address altDeployer) public view {
        vm.assume(altDeployer != address(factory));
        address a1 = _computeDefault();
        address a2 = _compute(
            factory.USDS_REWARD_ADDRESS(),
            factory.USDS(),
            NAME,
            SYMBOL,
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
            tokenizedStrategyImpl,
            altDeployer
        );
        assertTrue(a1 != a2, "different deployer must change predicted address");
    }

    /*//////////////////////////////////////////////////////////
        FULL DEPLOYMENT (requires mainnet fork + real TS impl)
    //////////////////////////////////////////////////////////*/

    function test_createStrategy_deploysAtPredictedAddressAndEmitsEvent() public onlyForked {
        address predicted = _computeDefault();

        vm.expectEmit(true, true, true, true, address(factory));
        emit SkyCompounderStrategyFactory.StrategyDeploy(address(this), donationAddress, predicted, NAME);

        address deployed =
            factory.createStrategy(NAME, SYMBOL, management, keeper, emergencyAdmin, donationAddress, true, tokenizedStrategyImpl);

        assertEq(deployed, predicted, "deployed address must match prediction");
        assertGt(deployed.code.length, 0, "deployed strategy must contain code");
    }

    function test_createStrategy_revertsOnDuplicateParameters() public onlyForked {
        factory.createStrategy(NAME, SYMBOL, management, keeper, emergencyAdmin, donationAddress, true, tokenizedStrategyImpl);

        vm.expectRevert();
        factory.createStrategy(NAME, SYMBOL, management, keeper, emergencyAdmin, donationAddress, true, tokenizedStrategyImpl);
    }

    function test_createStrategy_duplicateRevertsRegardlessOfCaller(address otherCaller) public onlyForked {
