        factory.createStrategy(NAME, SYMBOL, management, keeper, emergencyAdmin, donationAddress, true, tokenizedStrategyImpl);

        vm.prank(otherCaller);
        vm.expectRevert();
        factory.createStrategy(NAME, SYMBOL, management, keeper, emergencyAdmin, donationAddress, true, tokenizedStrategyImpl);
    }

    function test_createStrategy_allowsDifferentParameters() public onlyForked {
        address first =
            factory.createStrategy(NAME, SYMBOL, management, keeper, emergencyAdmin, donationAddress, true, tokenizedStrategyImpl);
        address second = factory.createStrategy(
            "Sky Compounder USDS 2", SYMBOL, management, keeper, emergencyAdmin, donationAddress, true, tokenizedStrategyImpl
        );

        assertTrue(first != second, "different parameters must yield different strategy addresses");
        assertGt(first.code.length, 0);
        assertGt(second.code.length, 0);
    }

    /*//////////////////////////////////////////////////////////
                              HELPERS
    //////////////////////////////////////////////////////////*/

    function _computeDefault() internal view returns (address) {
        return _compute(
            factory.USDS_REWARD_ADDRESS(),
            factory.USDS(),
            NAME,
            SYMBOL,
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
            tokenizedStrategyImpl,
            address(factory)
        );
    }

    function _compute(
        address _vault,
        address _asset,
        string memory _name,
        string memory _symbol,
        address _management,
        address _keeper,
        address _emergencyAdmin,
        address _donationAddress,
        bool _enableBurning,
        address _tokenizedStrategyAddress,
        address _deployer
    ) internal view returns (address) {
        return factory.computeStrategyAddress(
            _vault,
            _asset,
            _name,
            _symbol,
            _management,
            _keeper,
            _emergencyAdmin,
            _donationAddress,
            _enableBurning,
            _tokenizedStrategyAddress,
            _deployer
        );
    }
}
