pragma solidity >=0.8.25;

import { Test } from "forge-std/Test.sol";
import { SkyCompounderStrategyFactory } from "src/factories/SkyCompounderStrategyFactory.sol";

/**
 * @title SkyCompounderStrategyFactoryTest
 * @notice Foundry test suite for SkyCompounderStrategyFactory.
 *
 * @dev Test-design notes:
 *
 * `computeStrategyAddress` never executes the strategy's constructor — it only
 * validates the vault/asset constants and hashes `type(SkyCompounderStrategy).creationCode`
 * for a CREATE2 address prediction. That means every test around it (input
 * validation + address determinism) is fully self-contained and needs no
 * mainnet state.
 *
 * `createStrategy`, on the other hand, actually runs `SkyCompounderStrategy`'s
 * constructor, which is expected to talk to the real `USDS_REWARD_ADDRESS`
 * contract on mainnet and to a real `TokenizedStrategy` implementation. Those
 * tests only make sense against a mainnet fork with a genuine TokenizedStrategy
 * implementation address, so they are gated behind the `onlyForked` modifier
 * and are skipped (not failed) when that environment isn't configured:
 *
 *   MAINNET_RPC_URL         - an RPC URL for an Ethereum mainnet fork
 *   TOKENIZED_STRATEGY_ADDRESS - address of a deployed TokenizedStrategy implementation
 *
 * Run with, e.g.:
 *   MAINNET_RPC_URL=$ETH_RPC_URL TOKENIZED_STRATEGY_ADDRESS=0x... forge test
 */
contract SkyCompounderStrategyFactoryTest is Test {
    SkyCompounderStrategyFactory internal factory;

    address internal management = makeAddr("management");
    address internal keeper = makeAddr("keeper");
    address internal emergencyAdmin = makeAddr("emergencyAdmin");
    address internal donationAddress = makeAddr("donationAddress");
    address internal tokenizedStrategyImpl;

    string internal constant NAME = "Sky Compounder USDS";
    string internal constant SYMBOL = "ycUSDS";

    bool internal forked;

    modifier onlyForked() {
        if (!forked || tokenizedStrategyImpl == address(0)) {
            vm.skip(true);
            return;
        }
        _;
    }

    function setUp() public {
        factory = new SkyCompounderStrategyFactory();

        string memory rpcUrl = vm.envOr("MAINNET_RPC_URL", string(""));
        if (bytes(rpcUrl).length > 0) {
            vm.createSelectFork(rpcUrl);
            forked = true;
        }

        tokenizedStrategyImpl = vm.envOr("TOKENIZED_STRATEGY_ADDRESS", address(0));
    }

    /*//////////////////////////////////////////////////////////
                            CONSTANTS
    //////////////////////////////////////////////////////////*/

    function test_constants_haveExpectedMainnetAddresses() public view {
        assertEq(
            factory.USDS_REWARD_ADDRESS(), 0x0650CAF159C5A49f711e8169D4336ECB9b950275, "USDS_REWARD_ADDRESS mismatch"
        );
