    }

    /*//////////////////////////////////////////////////////////
                COMPUTE STRATEGY ADDRESS - INPUT VALIDATION
    //////////////////////////////////////////////////////////*/

    function test_computeStrategyAddress_revertsOnInvalidVault(address badVault) public {
        vm.assume(badVault != factory.USDS_REWARD_ADDRESS());

        vm.expectRevert(
            abi.encodeWithSelector(
                SkyCompounderStrategyFactory.InvalidVault.selector, badVault, factory.USDS_REWARD_ADDRESS()
            )
        );
        _compute(badVault, factory.USDS(), NAME, SYMBOL, management, keeper, emergencyAdmin, donationAddress, true, tokenizedStrategyImpl, address(factory));
    }

    function test_computeStrategyAddress_revertsOnInvalidAsset(address badAsset) public {
        vm.assume(badAsset != factory.USDS());

        vm.expectRevert(
            abi.encodeWithSelector(SkyCompounderStrategyFactory.InvalidAsset.selector, badAsset, factory.USDS())
        );
