            factory.USDS_REWARD_ADDRESS(),
            badAsset,
            NAME,
            SYMBOL,
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
            tokenizedStrategyImpl,
            address(factory)
        );
