        vm.expectRevert(
            abi.encodeWithSelector(
                SkyCompounderStrategyFactory.InvalidVault.selector, badVault, factory.USDS_REWARD_ADDRESS()
            )
        );
        _compute(
            badVault,
            badAsset,
            NAME,
            SYMBOL,
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
            tokenizedStrategyImpl,
            address(factory)
        );
    }

    function test_computeStrategyAddress_succeedsWithValidVaultAndAsset() public view {
