            factory.USDS_REWARD_ADDRESS(),
            factory.USDS(),
            NAME,
            SYMBOL,
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
            tokenizedStrategyImpl,
            address(factory)
        );
        assertTrue(predicted != address(0), "predicted address should not be zero");
    }

    /*//////////////////////////////////////////////////////////
                COMPUTE STRATEGY ADDRESS - DETERMINISM
    //////////////////////////////////////////////////////////*/

    function test_computeStrategyAddress_isDeterministic() public view {
        address a1 = _computeDefault();
        address a2 = _computeDefault();
        assertEq(a1, a2, "identical inputs must predict identical addresses");
    }

    function test_computeStrategyAddress_variesWithName() public view {
        address a1 = _computeDefault();
        address a2 = _compute(
            factory.USDS_REWARD_ADDRESS(),
            factory.USDS(),
            "Different Name",
