            factory.USDS_REWARD_ADDRESS(),
            factory.USDS(),
            NAME,
            "DIFF",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
            tokenizedStrategyImpl,
            address(factory)
        );
        assertTrue(a1 != a2, "different symbol must change predicted address");
    }

    function test_computeStrategyAddress_variesWithManagement(address altManagement) public view {
        vm.assume(altManagement != management);
        address a1 = _computeDefault();
        address a2 = _compute(
            factory.USDS_REWARD_ADDRESS(),
            factory.USDS(),
            NAME,
            SYMBOL,
            altManagement,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
            tokenizedStrategyImpl,
            address(factory)
        );
        assertTrue(a1 != a2, "different management must change predicted address");
    }

    function test_computeStrategyAddress_variesWithKeeper(address altKeeper) public view {
        vm.assume(altKeeper != keeper);
        address a1 = _computeDefault();
        address a2 = _compute(
            factory.USDS_REWARD_ADDRESS(),
            factory.USDS(),
            NAME,
            SYMBOL,
            management,
            altKeeper,
            emergencyAdmin,
            donationAddress,
            true,
            tokenizedStrategyImpl,
            address(factory)
        );
        assertTrue(a1 != a2, "different keeper must change predicted address");
    }

    function test_computeStrategyAddress_variesWithEmergencyAdmin(address altEmergencyAdmin) public view {
        vm.assume(altEmergencyAdmin != emergencyAdmin);
        address a1 = _computeDefault();
        address a2 = _compute(
            factory.USDS_REWARD_ADDRESS(),
            factory.USDS(),
            NAME,
            SYMBOL,
            management,
            keeper,
            altEmergencyAdmin,
            donationAddress,
            true,
            tokenizedStrategyImpl,
            address(factory)
        );
        assertTrue(a1 != a2, "different emergencyAdmin must change predicted address");
    }

    function test_computeStrategyAddress_variesWithDonationAddress(address altDonationAddress) public view {
        vm.assume(altDonationAddress != donationAddress);
        address a1 = _computeDefault();
        address a2 = _compute(
            factory.USDS_REWARD_ADDRESS(),
            factory.USDS(),
            NAME,
            SYMBOL,
            management,
            keeper,
            emergencyAdmin,
            altDonationAddress,
            true,
            tokenizedStrategyImpl,
            address(factory)
        );
        assertTrue(a1 != a2, "different donationAddress must change predicted address");
    }

    function test_computeStrategyAddress_variesWithEnableBurning() public view {
        address a1 = _computeDefault();
        address a2 = _compute(
            factory.USDS_REWARD_ADDRESS(),
            factory.USDS(),
            NAME,
            SYMBOL,
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            false,
            tokenizedStrategyImpl,
            address(factory)
        );
        assertTrue(a1 != a2, "different enableBurning flag must change predicted address");
    }

    function test_computeStrategyAddress_variesWithTokenizedStrategyAddress(address altImpl) public view {
        vm.assume(altImpl != tokenizedStrategyImpl);
        address a1 = _computeDefault();
        address a2 = _compute(
            factory.USDS_REWARD_ADDRESS(),
            factory.USDS(),
            NAME,
            SYMBOL,
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
            altImpl,
            address(factory)
        );
        assertTrue(a1 != a2, "different tokenizedStrategyAddress must change predicted address");
    }

    function test_computeStrategyAddress_variesWithDeployer(address altDeployer) public view {
        vm.assume(altDeployer != address(factory));
        address a1 = _computeDefault();
        address a2 = _compute(
            factory.USDS_REWARD_ADDRESS(),
            factory.USDS(),
            NAME,
            SYMBOL,
            management,
            keeper,
