pragma solidity ^0.8.25;

import { Test } from "forge-std/Test.sol";
import { SkyCompounderStrategyFactory } from "src/factories/SkyCompounderStrategyFactory.sol";

/**
 * @title SkyCompounderStrategyFactoryTest
 * @notice Foundry test suite for SkyCompounderStrategyFactory.
 * @dev The factory hardcodes real mainnet addresses (the Sky/USDS staking rewards
 *      contract and the USDS token) as constants, and SkyCompounderStrategy's
 *      constructor is expected to interact with the staking rewards contract.
 *      Because of this, tests that actually deploy a strategy run against a mainnet
 *      fork. Tests that only exercise pure/view address computation and the
 *      vault/asset validation logic do not require a working strategy deployment
 *      and are kept independent of the fork's liveness so they remain robust.
 *
 *      The TokenizedStrategy implementation address used below
 *      (0xD377919FA87120584B21279a491F82D5265A139) is Yearn's canonical,
 *      generically-reusable mainnet TokenizedStrategy implementation, which is the
 *      conventional value passed to Yearn-V3-style strategy constructors.
 */
contract SkyCompounderStrategyFactoryTest is Test {
    SkyCompounderStrategyFactory internal factory;

    address internal constant TOKENIZED_STRATEGY_IMPL = 0xD377919FA87120584B21279a491F82D5265A139;

    address internal management;
    address internal keeper;
    address internal emergencyAdmin;
    address internal donationAddress;
    address internal deployer;

    bool internal forkAvailable;

    event StrategyDeploy(
        address indexed deployer, address indexed donationAddress, address indexed strategyAddress, string vaultTokenName
    );

    function setUp() public {
        management = makeAddr("management");
        keeper = makeAddr("keeper");
        emergencyAdmin = makeAddr("emergencyAdmin");
        donationAddress = makeAddr("donationAddress");
        deployer = makeAddr("deployer");

        // Attempt to fork mainnet so that createStrategy() can actually construct a
        // SkyCompounderStrategy against the real Sky/USDS staking rewards contract.
        // Falls back gracefully so that non-deployment tests still run in CI
        // environments without RPC access.
        try vm.createSelectFork(vm.envOr("MAINNET_RPC_URL", string("https://ethereum-rpc.publicnode.com"))) {
            forkAvailable = true;
        } catch {
            forkAvailable = false;
        }

        factory = new SkyCompounderStrategyFactory();
    }

    modifier onlyOnFork() {
        if (!forkAvailable) {
            return;
        }
        _;
    }

    /*//////////////////////////////////////////////////////////////
                                CONSTANTS
    //////////////////////////////////////////////////////////////*/

    function test_Constants() public view {
        assertEq(factory.USDS_REWARD_ADDRESS(), 0x0650CAF159C5A49f711e8169D4336ECB9b950275, "USDS_REWARD_ADDRESS mismatch");
        assertEq(factory.USDS(), 0xdC035D45d973E3EC169d2276DDab16f1e407384F, "USDS mismatch");
    }

    /*//////////////////////////////////////////////////////////////
                    computeStrategyAddress: VALIDATION
    //////////////////////////////////////////////////////////////*/

    function test_ComputeStrategyAddress_RevertsOnInvalidVault() public {
        address badVault = makeAddr("badVault");

        vm.expectRevert(
            abi.encodeWithSelector(SkyCompounderStrategyFactory.InvalidVault.selector, badVault, factory.USDS_REWARD_ADDRESS())
        );
        factory.computeStrategyAddress(
            badVault,
            factory.USDS(),
            "Sky Compounder",
            "skyUSDS",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
            TOKENIZED_STRATEGY_IMPL,
            deployer
        );
    }

    function test_ComputeStrategyAddress_RevertsOnInvalidAsset() public {
        address badAsset = makeAddr("badAsset");

        vm.expectRevert(
            abi.encodeWithSelector(SkyCompounderStrategyFactory.InvalidAsset.selector, badAsset, factory.USDS())
        );
        factory.computeStrategyAddress(
            factory.USDS_REWARD_ADDRESS(),
            badAsset,
            "Sky Compounder",
            "skyUSDS",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
            TOKENIZED_STRATEGY_IMPL,
            deployer
        );
    }

    function testFuzz_ComputeStrategyAddress_RevertsOnInvalidVault(address badVault) public {
        vm.assume(badVault != factory.USDS_REWARD_ADDRESS());

        vm.expectRevert(
            abi.encodeWithSelector(SkyCompounderStrategyFactory.InvalidVault.selector, badVault, factory.USDS_REWARD_ADDRESS())
        );
        factory.computeStrategyAddress(
            badVault,
            factory.USDS(),
            "Sky Compounder",
            "skyUSDS",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
            TOKENIZED_STRATEGY_IMPL,
            deployer
        );
    }

    /*//////////////////////////////////////////////////////////////
                computeStrategyAddress: DETERMINISM / SENSITIVITY
    //////////////////////////////////////////////////////////////*/

    function test_ComputeStrategyAddress_DeterministicForSameParams() public view {
        address a = _predict("Sky Compounder", "skyUSDS", management, keeper, emergencyAdmin, donationAddress, true, deployer);
        address b = _predict("Sky Compounder", "skyUSDS", management, keeper, emergencyAdmin, donationAddress, true, deployer);
        assertEq(a, b, "computeStrategyAddress should be pure/deterministic for identical inputs");
    }

    function test_ComputeStrategyAddress_DiffersWithDifferentDeployer() public {
        address deployerA = makeAddr("deployerA");
        address deployerB = makeAddr("deployerB");

        address a =
            _predict("Sky Compounder", "skyUSDS", management, keeper, emergencyAdmin, donationAddress, true, deployerA);
        address b =
            _predict("Sky Compounder", "skyUSDS", management, keeper, emergencyAdmin, donationAddress, true, deployerB);

        assertTrue(a != b, "different deployer should predict a different CREATE2 address");
    }

    function testFuzz_ComputeStrategyAddress_DiffersWhenNameChanges(string memory nameA, string memory nameB) public {
        vm.assume(keccak256(bytes(nameA)) != keccak256(bytes(nameB)));

        address a = _predict(nameA, "skyUSDS", management, keeper, emergencyAdmin, donationAddress, true, deployer);
        address b = _predict(nameB, "skyUSDS", management, keeper, emergencyAdmin, donationAddress, true, deployer);

        assertTrue(a != b, "different name should predict a different strategy address");
    }

    function testFuzz_ComputeStrategyAddress_DiffersWhenManagementChanges(address managementA, address managementB)
        public
    {
        vm.assume(managementA != managementB);

        address a = _predict("Sky Compounder", "skyUSDS", managementA, keeper, emergencyAdmin, donationAddress, true, deployer);
        address b = _predict("Sky Compounder", "skyUSDS", managementB, keeper, emergencyAdmin, donationAddress, true, deployer);

        assertTrue(a != b, "different management should predict a different strategy address");
    }

    function test_ComputeStrategyAddress_DiffersWhenEnableBurningChanges() public {
        address a = _predict("Sky Compounder", "skyUSDS", management, keeper, emergencyAdmin, donationAddress, true, deployer);
        address b =
            _predict("Sky Compounder", "skyUSDS", management, keeper, emergencyAdmin, donationAddress, false, deployer);

        assertTrue(a != b, "different enableBurning flag should predict a different strategy address");
    }

    function test_ComputeStrategyAddress_DiffersWhenDonationAddressChanges() public {
        address donationB = makeAddr("donationB");

        address a = _predict("Sky Compounder", "skyUSDS", management, keeper, emergencyAdmin, donationAddress, true, deployer);
        address b = _predict("Sky Compounder", "skyUSDS", management, keeper, emergencyAdmin, donationB, true, deployer);

        assertTrue(a != b, "different donation address should predict a different strategy address");
    }

    /*//////////////////////////////////////////////////////////////
                        createStrategy: DEPLOYMENT
    //////////////////////////////////////////////////////////////*/

    function test_CreateStrategy_DeploysToPredictedAddress() public onlyOnFork {
        address predicted = _predict(
            "Sky Compounder", "skyUSDS", management, keeper, emergencyAdmin, donationAddress, true, address(factory)
        );

        vm.prank(deployer);
        address deployed = factory.createStrategy(
            "Sky Compounder", "skyUSDS", management, keeper, emergencyAdmin, donationAddress, true, TOKENIZED_STRATEGY_IMPL
        );

        assertEq(deployed, predicted, "deployed address should match computeStrategyAddress prediction");
        assertGt(deployed.code.length, 0, "strategy should have deployed bytecode");
    }

    function test_CreateStrategy_EmitsStrategyDeployEvent() public onlyOnFork {
        address predicted = _predict(
            "Sky Compounder", "skyUSDS", management, keeper, emergencyAdmin, donationAddress, true, address(factory)
        );

        vm.expectEmit(true, true, true, true, address(factory));
        emit StrategyDeploy(deployer, donationAddress, predicted, "Sky Compounder");

        vm.prank(deployer);
        factory.createStrategy(
            "Sky Compounder", "skyUSDS", management, keeper, emergencyAdmin, donationAddress, true, TOKENIZED_STRATEGY_IMPL
        );
    }

    function test_CreateStrategy_RevertsOnDuplicateParams() public onlyOnFork {
        vm.prank(deployer);
        factory.createStrategy(
            "Sky Compounder", "skyUSDS", management, keeper, emergencyAdmin, donationAddress, true, TOKENIZED_STRATEGY_IMPL
        );

        // Same exact parameters -> same salt -> same target CREATE2 address, which
        // already has code deployed. The second deployment must fail.
        vm.expectRevert();
        vm.prank(deployer);
        factory.createStrategy(
            "Sky Compounder", "skyUSDS", management, keeper, emergencyAdmin, donationAddress, true, TOKENIZED_STRATEGY_IMPL
        );
    }

    function test_CreateStrategy_RevertsOnDuplicateParamsFromDifferentCaller() public onlyOnFork {
        // msg.sender is not part of the parameter hash, so the resulting salt (and
        // predicted address) is identical regardless of who calls createStrategy.
        address otherCaller = makeAddr("otherCaller");

        vm.prank(deployer);
        factory.createStrategy(
            "Sky Compounder", "skyUSDS", management, keeper, emergencyAdmin, donationAddress, true, TOKENIZED_STRATEGY_IMPL
        );

        vm.expectRevert();
        vm.prank(otherCaller);
        factory.createStrategy(
            "Sky Compounder", "skyUSDS", management, keeper, emergencyAdmin, donationAddress, true, TOKENIZED_STRATEGY_IMPL
        );
    }

    function test_CreateStrategy_DifferentParamsDeployDifferentAddresses() public onlyOnFork {
        vm.startPrank(deployer);
        address strategyA = factory.createStrategy(
            "Sky Compounder A", "skyUSDSA", management, keeper, emergencyAdmin, donationAddress, true, TOKENIZED_STRATEGY_IMPL
        );
        address strategyB = factory.createStrategy(
            "Sky Compounder B", "skyUSDSB", management, keeper, emergencyAdmin, donationAddress, true, TOKENIZED_STRATEGY_IMPL
        );
        vm.stopPrank();

        assertTrue(strategyA != strategyB, "distinct params should deploy distinct strategies");
        assertGt(strategyA.code.length, 0);
        assertGt(strategyB.code.length, 0);
    }

    function testFuzz_CreateStrategy_MatchesComputeStrategyAddress(bool enableBurning, address donation) public onlyOnFork {
        vm.assume(donation != address(0));

        address predicted = _predict(
            "Sky Compounder Fuzz", "skyUSDSF", management, keeper, emergencyAdmin, donation, enableBurning, address(factory)
        );

        vm.prank(deployer);
        address deployed = factory.createStrategy(
            "Sky Compounder Fuzz",
            "skyUSDSF",
            management,
            keeper,
            emergencyAdmin,
            donation,
            enableBurning,
            TOKENIZED_STRATEGY_IMPL
        );

        assertEq(deployed, predicted);
    }

    /*//////////////////////////////////////////////////////////////
                                 HELPERS
    //////////////////////////////////////////////////////////////*/

    function _predict(
        string memory _name,
        string memory _symbol,
        address _management,
        address _keeper,
        address _emergencyAdmin,
        address _donationAddress,
        bool _enableBurning,
        address _deployer
    ) internal view returns (address) {
        return factory.computeStrategyAddress(
            factory.USDS_REWARD_ADDRESS(),
            factory.USDS(),
            _name,
            _symbol,
            _management,
            _keeper,
            _emergencyAdmin,
            _donationAddress,
            _enableBurning,
            TOKENIZED_STRATEGY_IMPL,
            _deployer
        );
    }
}
