    string internal constant SYMBOL = "ycSKY";
    bool internal constant ENABLE_BURNING = true;

    bool internal forked;
    uint256 internal constant FORK_BLOCK = 21_000_000;

    function setUp() public {
        factory = new SkyCompounderStrategyFactory();

        management = makeAddr("management");
        keeper = makeAddr("keeper");
        emergencyAdmin = makeAddr("emergencyAdmin");
        donationAddress = makeAddr("donationAddress");

        // Attempt to fork mainnet so the real deployment path (which touches the
        // real USDS / USDS staking contracts) can be exercised. If no RPC endpoint
        // is configured in the environment, deployment-dependent tests are skipped
        // gracefully while all pure/view logic tests still run.
        string memory rpcUrl = vm.envOr("MAINNET_RPC_URL", string(""));
        if (bytes(rpcUrl).length == 0) {
            rpcUrl = vm.envOr("ETH_RPC_URL", string(""));
        }

        if (bytes(rpcUrl).length != 0) {
            vm.createSelectFork(rpcUrl, FORK_BLOCK);
            forked = true;
        }

