        assertEq(factory.USDS_REWARD_ADDRESS(), 0x0650CAF159C5A49f711e8169D4336ECB9b950275, "USDS_REWARD_ADDRESS mismatch");
        assertEq(factory.USDS(), 0xdC035D45d973E3EC169d2276DDab16f1e407384F, "USDS mismatch");
    }

