    function test_ComputeStrategyAddress_RevertsOnInvalidAsset() public {
        address badAsset = makeAddr("badAsset");

        vm.expectRevert(
            abi.encodeWithSelector(SkyCompounderStrategyFactory.InvalidAsset.selector, badAsset, factory.USDS())
        );
        factory.computeStrategyAddress(
            factory.USDS_REWARD_ADDRESS(),
            badAsset,
            NAME,
            SYMBOL,
            management,
            keeper,
