        );
        assertTrue(a != b, "different keeper should predict different addresses");
    }

    function test_ComputeStrategyAddress_DiffersByEmergencyAdmin() public view {
        address a = _computeDefault(address(this));
        address b = factory.computeStrategyAddress(
            factory.USDS_REWARD_ADDRESS(),
            factory.USDS(),
            NAME,
            SYMBOL,
            management,
            keeper,
            makeAddr("otherEmergencyAdmin"),
            donationAddress,
            ENABLE_BURNING,
            tokenizedStrategyAddress,
            address(this)
        );
        assertTrue(a != b, "different emergencyAdmin should predict different addresses");
    }

    function test_ComputeStrategyAddress_DiffersByDonationAddress() public view {
