contract MockSwapRouter {
    using SafeERC20 for ERC20;

    uint256 public amountOutToReturn;
    uint256 public amountInToReturn;
    bool public shouldRevert;

    string public lastFunction;
    bytes public lastPath;
    uint24 public lastFee;
    address public lastTokenIn;
    address public lastTokenOut;
    uint256 public lastAmountOutMinimum;
    uint256 public lastAmountInMaximum;

    function setAmountOut(uint256 _amount) external {
        amountOutToReturn = _amount;
    }

    function setAmountIn(uint256 _amount) external {
        amountInToReturn = _amount;
    }

    function setShouldRevert(bool _shouldRevert) external {
        shouldRevert = _shouldRevert;
    }

    function exactInputSingle(
        ISwapRouter.ExactInputSingleParams calldata params
    ) external returns (uint256 amountOut) {
        if (shouldRevert) revert("mock: forced revert");

        lastFunction = "exactInputSingle";
        lastFee = params.fee;
        lastTokenIn = params.tokenIn;
        lastTokenOut = params.tokenOut;
        lastAmountOutMinimum = params.amountOutMinimum;

        amountOut = amountOutToReturn;
        require(amountOut >= params.amountOutMinimum, "too little received");

        ERC20(params.tokenIn).safeTransferFrom(msg.sender, address(this), params.amountIn);
        ERC20(params.tokenOut).safeTransfer(params.recipient, amountOut);
    }

    function exactInput(ISwapRouter.ExactInputParams calldata params) external returns (uint256 amountOut) {
        if (shouldRevert) revert("mock: forced revert");

        lastFunction = "exactInput";
        lastPath = params.path;
        lastAmountOutMinimum = params.amountOutMinimum;

        address tokenIn = _toAddress(params.path, 0);
        address tokenOut = _toAddress(params.path, params.path.length - 20);
        lastTokenIn = tokenIn;
        lastTokenOut = tokenOut;

        amountOut = amountOutToReturn;
        require(amountOut >= params.amountOutMinimum, "too little received");

        ERC20(tokenIn).safeTransferFrom(msg.sender, address(this), params.amountIn);
        ERC20(tokenOut).safeTransfer(params.recipient, amountOut);
    }

    function exactOutputSingle(
        ISwapRouter.ExactOutputSingleParams calldata params
    ) external returns (uint256 amountIn) {
        if (shouldRevert) revert("mock: forced revert");

        lastFunction = "exactOutputSingle";
        lastFee = params.fee;
        lastTokenIn = params.tokenIn;
        lastTokenOut = params.tokenOut;
        lastAmountInMaximum = params.amountInMaximum;

        amountIn = amountInToReturn;
        require(amountIn <= params.amountInMaximum, "too much requested");

        ERC20(params.tokenIn).safeTransferFrom(msg.sender, address(this), amountIn);
        ERC20(params.tokenOut).safeTransfer(params.recipient, params.amountOut);
    }

    function exactOutput(ISwapRouter.ExactOutputParams calldata params) external returns (uint256 amountIn) {
        if (shouldRevert) revert("mock: forced revert");

        lastFunction = "exactOutput";
        lastPath = params.path;
        lastAmountInMaximum = params.amountInMaximum;

        // exact-output paths are encoded tokenOut -> ... -> tokenIn
        address tokenOut = _toAddress(params.path, 0);
        address tokenIn = _toAddress(params.path, params.path.length - 20);
        lastTokenIn = tokenIn;
        lastTokenOut = tokenOut;

        amountIn = amountInToReturn;
        require(amountIn <= params.amountInMaximum, "too much requested");

        ERC20(tokenIn).safeTransferFrom(msg.sender, address(this), amountIn);
        ERC20(tokenOut).safeTransfer(params.recipient, params.amountOut);
    }

    function _toAddress(bytes memory _bytes, uint256 _start) internal pure returns (address tempAddress) {
        assembly {
            tempAddress := div(mload(add(add(_bytes, 0x20), _start)), 0x1000000000000000000000000)
        }
    }
}

