// Bare harness used only to inspect default storage values.
contract UniswapV3SwapperDefaultsHarness is UniswapV3Swapper {}

/*//////////////////////////////////////////////////////////////
                            TEST SUITE
//////////////////////////////////////////////////////////////*/

contract UniswapV3SwapperTest is Test {
    UniswapV3SwapperHarness internal swapper;
    MockSwapRouter internal router;
    MockERC20 internal base;
    MockERC20 internal tokenA;
    MockERC20 internal tokenB;

    uint24 internal constant FEE_A_BASE = 500;
    uint24 internal constant FEE_BASE_B = 3000;

    function setUp() public {
        router = new MockSwapRouter();
        base = new MockERC20("Base Token", "BASE");
        tokenA = new MockERC20("Token A", "TKA");
        tokenB = new MockERC20("Token B", "TKB");

        swapper = new UniswapV3SwapperHarness(address(router), address(base));

        swapper.setUniFees(address(tokenA), address(base), FEE_A_BASE);
        swapper.setUniFees(address(base), address(tokenB), FEE_BASE_B);

        // Fund the swapper with tokens it might sell.
        base.mint(address(swapper), 1_000 ether);
        tokenA.mint(address(swapper), 1_000 ether);
        tokenB.mint(address(swapper), 1_000 ether);

        // Fund the mock router so it can pay out swap results.
        base.mint(address(router), 1_000 ether);
        tokenA.mint(address(router), 1_000 ether);
        tokenB.mint(address(router), 1_000 ether);
    }

    /*//////////////////////////////////////////////////////////
                            DEFAULT STATE
    //////////////////////////////////////////////////////////*/

    function test_DefaultBaseAndRouterAddresses() public {
        UniswapV3SwapperDefaultsHarness defaults = new UniswapV3SwapperDefaultsHarness();
        assertEq(defaults.base(), 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2);
        assertEq(defaults.router(), 0xE592427A0AEce92De3Edee1F18E0157C05861564);
        assertEq(defaults.minAmountToSell(), 0);
    }

    /*//////////////////////////////////////////////////////////
                            _setUniFees
    //////////////////////////////////////////////////////////*/

    function test_SetUniFees_SetsBothDirections() public {
        swapper.setUniFees(address(tokenA), address(tokenB), 777);
        assertEq(swapper.uniFees(address(tokenA), address(tokenB)), 777);
        assertEq(swapper.uniFees(address(tokenB), address(tokenA)), 777);
    }

    /*//////////////////////////////////////////////////////////
                            _checkAllowance
    //////////////////////////////////////////////////////////*/

    function test_CheckAllowance_SetsApprovalWhenInsufficient() public {
        assertEq(tokenA.allowance(address(swapper), address(router)), 0);
        swapper.checkAllowance(address(router), address(tokenA), 500 ether);
        assertEq(tokenA.allowance(address(swapper), address(router)), 500 ether);
    }

    function test_CheckAllowance_NoopWhenAlreadySufficient() public {
        swapper.checkAllowance(address(router), address(tokenA), 1_000 ether);
        assertEq(tokenA.allowance(address(swapper), address(router)), 1_000 ether);

        // Requesting a smaller allowance should not touch the existing approval.
        swapper.checkAllowance(address(router), address(tokenA), 10 ether);
        assertEq(tokenA.allowance(address(swapper), address(router)), 1_000 ether);
    }

    /*//////////////////////////////////////////////////////////
                            _swapFrom
    //////////////////////////////////////////////////////////*/

    function test_SwapFrom_ZeroAmountIn_ReturnsZeroAndNoOp() public {
        uint256 balBefore = base.balanceOf(address(swapper));

        uint256 out = swapper.swapFrom(address(base), address(tokenB), 0, 0);

        assertEq(out, 0);
        assertEq(base.balanceOf(address(swapper)), balBefore);
        assertEq(base.allowance(address(swapper), address(router)), 0);
        assertEq(router.lastFunction(), "");
    }

    function test_SwapFrom_BelowMinAmountToSell_ReturnsZero() public {
        swapper.setMinAmountToSell(100 ether);

        uint256 out = swapper.swapFrom(address(base), address(tokenB), 99 ether, 0);

        assertEq(out, 0);
        assertEq(router.lastFunction(), "");
    }

    function test_SwapFrom_AtMinAmountToSell_ExecutesSwap() public {
        swapper.setMinAmountToSell(100 ether);
        router.setAmountOut(50 ether);

        uint256 out = swapper.swapFrom(address(base), address(tokenB), 100 ether, 1);

        assertEq(out, 50 ether);
        assertEq(router.lastFunction(), "exactInputSingle");
    }

    function test_SwapFrom_FromIsBase_UsesExactInputSingle() public {
        router.setAmountOut(200 ether);
        uint256 balBaseBefore = base.balanceOf(address(swapper));
        uint256 balBBefore = tokenB.balanceOf(address(swapper));

        uint256 out = swapper.swapFrom(address(base), address(tokenB), 100 ether, 1);

        assertEq(out, 200 ether);
        assertEq(router.lastFunction(), "exactInputSingle");
        assertEq(router.lastFee(), FEE_BASE_B);
        assertEq(router.lastTokenIn(), address(base));
        assertEq(router.lastTokenOut(), address(tokenB));
        assertEq(base.balanceOf(address(swapper)), balBaseBefore - 100 ether);
        assertEq(tokenB.balanceOf(address(swapper)), balBBefore + 200 ether);
        // allowance fully consumed by the exact-input transferFrom
        assertEq(base.allowance(address(swapper), address(router)), 0);
    }

    function test_SwapFrom_ToIsBase_UsesExactInputSingle() public {
        router.setAmountOut(75 ether);

        uint256 out = swapper.swapFrom(address(tokenA), address(base), 100 ether, 1);

        assertEq(out, 75 ether);
        assertEq(router.lastFunction(), "exactInputSingle");
        assertEq(router.lastFee(), FEE_A_BASE);
        assertEq(router.lastTokenIn(), address(tokenA));
        assertEq(router.lastTokenOut(), address(base));
    }

    function test_SwapFrom_NeitherIsBase_UsesMultihopExactInput() public {
        router.setAmountOut(60 ether);
        uint256 balABefore = tokenA.balanceOf(address(swapper));
        uint256 balBBefore = tokenB.balanceOf(address(swapper));

        uint256 out = swapper.swapFrom(address(tokenA), address(tokenB), 100 ether, 1);

        assertEq(out, 60 ether);
        assertEq(router.lastFunction(), "exactInput");

        bytes memory expectedPath = abi.encodePacked(
            address(tokenA),
            FEE_A_BASE,
            address(base),
            FEE_BASE_B,
            address(tokenB)
        );
        assertEq(router.lastPath(), expectedPath);
        assertEq(router.lastTokenIn(), address(tokenA));
        assertEq(router.lastTokenOut(), address(tokenB));
        assertEq(tokenA.balanceOf(address(swapper)), balABefore - 100 ether);
        assertEq(tokenB.balanceOf(address(swapper)), balBBefore + 60 ether);
    }

    function test_SwapFrom_RevertsWhenAmountOutBelowMinimum() public {
        router.setAmountOut(1 ether);

        vm.expectRevert("too little received");
        swapper.swapFrom(address(base), address(tokenB), 100 ether, 2 ether);
    }

    function test_SwapFrom_RevertsWhenRouterReverts() public {
        router.setShouldRevert(true);

        vm.expectRevert("mock: forced revert");
        swapper.swapFrom(address(base), address(tokenB), 100 ether, 1);
    }

    /*//////////////////////////////////////////////////////////
                            _swapTo
    //////////////////////////////////////////////////////////*/

    function test_SwapTo_ZeroMaxAmountFrom_ReturnsZero() public {
        uint256 out = swapper.swapTo(address(base), address(tokenB), 10 ether, 0);

        assertEq(out, 0);
        assertEq(router.lastFunction(), "");
    }

    function test_SwapTo_BelowMinAmountToSell_ReturnsZero() public {
        swapper.setMinAmountToSell(100 ether);

        uint256 out = swapper.swapTo(address(base), address(tokenB), 10 ether, 99 ether);

        assertEq(out, 0);
        assertEq(router.lastFunction(), "");
    }

    function test_SwapTo_FromIsBase_UsesExactOutputSingle_AndResetsAllowance() public {
        router.setAmountIn(40 ether);
        uint256 balBaseBefore = base.balanceOf(address(swapper));
        uint256 balBBefore = tokenB.balanceOf(address(swapper));

        uint256 amtIn = swapper.swapTo(address(base), address(tokenB), 20 ether, 100 ether);

        assertEq(amtIn, 40 ether);
        assertEq(router.lastFunction(), "exactOutputSingle");
        assertEq(router.lastFee(), FEE_BASE_B);
        assertEq(base.balanceOf(address(swapper)), balBaseBefore - 40 ether);
        assertEq(tokenB.balanceOf(address(swapper)), balBBefore + 20 ether);
        // allowance is explicitly reset to 0 after a successful _swapTo
        assertEq(base.allowance(address(swapper), address(router)), 0);
    }

    function test_SwapTo_ToIsBase_UsesExactOutputSingle() public {
        router.setAmountIn(30 ether);

        uint256 amtIn = swapper.swapTo(address(tokenA), address(base), 15 ether, 100 ether);

        assertEq(amtIn, 30 ether);
        assertEq(router.lastFunction(), "exactOutputSingle");
        assertEq(router.lastFee(), FEE_A_BASE);
        assertEq(tokenA.allowance(address(swapper), address(router)), 0);
    }

    function test_SwapTo_NeitherIsBase_UsesMultihopExactOutput() public {
        router.setAmountIn(55 ether);

        uint256 amtIn = swapper.swapTo(address(tokenA), address(tokenB), 30 ether, 200 ether);

        assertEq(amtIn, 55 ether);
        assertEq(router.lastFunction(), "exactOutput");

        bytes memory expectedPath = abi.encodePacked(
            address(tokenB),
            FEE_BASE_B,
            address(base),
            FEE_A_BASE,
            address(tokenA)
        );
        assertEq(router.lastPath(), expectedPath);
        assertEq(router.lastTokenIn(), address(tokenA));
        assertEq(router.lastTokenOut(), address(tokenB));
        assertEq(tokenA.allowance(address(swapper), address(router)), 0);
    }

    function test_SwapTo_RevertsWhenAmountInExceedsMaximum() public {
        router.setAmountIn(100 ether);

        vm.expectRevert("too much requested");
        swapper.swapTo(address(base), address(tokenB), 20 ether, 50 ether);
    }

    function test_SwapTo_RevertsWhenRouterReverts() public {
        router.setShouldRevert(true);

        vm.expectRevert("mock: forced revert");
        swapper.swapTo(address(base), address(tokenB), 10 ether, 100 ether);
    }

    /*//////////////////////////////////////////////////////////
                                FUZZ
    //////////////////////////////////////////////////////////*/

    function testFuzz_SwapFrom_MinAmountToSellBoundary(uint256 amountIn, uint256 minAmount) public {
        amountIn = bound(amountIn, 0, 1_000 ether);
        minAmount = bound(minAmount, 0, 1_000 ether);

        swapper.setMinAmountToSell(minAmount);
        router.setAmountOut(1 ether);

        if (amountIn > base.balanceOf(address(swapper))) {
            base.mint(address(swapper), amountIn);
        }

        uint256 out = swapper.swapFrom(address(base), address(tokenB), amountIn, 0);

        if (amountIn == 0 || amountIn < minAmount) {
            assertEq(out, 0);
        } else {
            assertEq(out, 1 ether);
        }
    }
}

