    mapping(address => mapping(address => uint256)) public rate;

    // records of the most recent call, for assertions
    address public lastTokenIn;
    address public lastTokenOut;
    uint24 public lastFee;
    address public lastRecipient;
    uint256 public lastDeadline;
    bytes public lastPath;

    function setRate(address tokenIn, address tokenOut, uint256 r) external {
        rate[tokenIn][tokenOut] = r;
    }

    function exactInputSingle(ISwapRouter.ExactInputSingleParams calldata params) external returns (uint256 amountOut) {
        require(block.timestamp <= params.deadline, "expired");
        lastTokenIn = params.tokenIn;
        lastTokenOut = params.tokenOut;
        lastFee = params.fee;
        lastRecipient = params.recipient;
        lastDeadline = params.deadline;

        IERC20(params.tokenIn).transferFrom(msg.sender, address(this), params.amountIn);
        uint256 r = rate[params.tokenIn][params.tokenOut];
        require(r != 0, "no rate set");
        amountOut = (params.amountIn * r) / 1e18;
        require(amountOut >= params.amountOutMinimum, "too little received");
        IERC20(params.tokenOut).transfer(params.recipient, amountOut);
    }

    function exactInput(ISwapRouter.ExactInputParams calldata params) external returns (uint256 amountOut) {
        require(block.timestamp <= params.deadline, "expired");
        address tokenIn = _firstAddress(params.path);
        address tokenOut = _lastAddress(params.path);
        lastTokenIn = tokenIn;
        lastTokenOut = tokenOut;
        lastRecipient = params.recipient;
        lastDeadline = params.deadline;
        lastPath = params.path;

        IERC20(tokenIn).transferFrom(msg.sender, address(this), params.amountIn);
        uint256 r = rate[tokenIn][tokenOut];
        require(r != 0, "no rate set");
        amountOut = (params.amountIn * r) / 1e18;
        require(amountOut >= params.amountOutMinimum, "too little received");
        IERC20(tokenOut).transfer(params.recipient, amountOut);
    }

    function exactOutputSingle(ISwapRouter.ExactOutputSingleParams calldata params) external returns (uint256 amountIn) {
        require(block.timestamp <= params.deadline, "expired");
        lastTokenIn = params.tokenIn;
        lastTokenOut = params.tokenOut;
        lastFee = params.fee;
        lastRecipient = params.recipient;
        lastDeadline = params.deadline;

        uint256 r = rate[params.tokenIn][params.tokenOut];
        require(r != 0, "no rate set");
        amountIn = (params.amountOut * 1e18) / r;
        require(amountIn <= params.amountInMaximum, "too much requested");
        IERC20(params.tokenIn).transferFrom(msg.sender, address(this), amountIn);
        IERC20(params.tokenOut).transfer(params.recipient, params.amountOut);
    }

    function exactOutput(ISwapRouter.ExactOutputParams calldata params) external returns (uint256 amountIn) {
        require(block.timestamp <= params.deadline, "expired");
        // exact-output multihop paths are encoded tokenOut -> ... -> tokenIn
        address tokenOut = _firstAddress(params.path);
        address tokenIn = _lastAddress(params.path);
        lastTokenIn = tokenIn;
        lastTokenOut = tokenOut;
        lastRecipient = params.recipient;
