contract UniswapV3SwapperTest is Test {
    UniswapV3SwapperHarness internal harness;
    MockSwapRouter internal router;

    MockERC20 internal base;
    MockERC20 internal tokenA;
    MockERC20 internal tokenB;

    uint24 internal constant FEE_LOW = 500;
    uint24 internal constant FEE_MED = 3000;

    function setUp() public {
        harness = new UniswapV3SwapperHarness();
        router = new MockSwapRouter();

        base = new MockERC20("Base", "BASE");
        tokenA = new MockERC20("TokenA", "TKA");
        tokenB = new MockERC20("TokenB", "TKB");

        harness.setRouter(address(router));
        harness.setBase(address(base));

        harness.setUniFees(address(base), address(tokenA), FEE_LOW);
        harness.setUniFees(address(base), address(tokenB), FEE_MED);

        // 1:1 exchange rates by default
        router.setRate(address(base), address(tokenA), 1e18);
        router.setRate(address(tokenA), address(base), 1e18);
        router.setRate(address(base), address(tokenB), 1e18);
        router.setRate(address(tokenB), address(base), 1e18);
        router.setRate(address(tokenA), address(tokenB), 1e18);
        router.setRate(address(tokenB), address(tokenA), 1e18);
    }

    // ---------------------------------------------------------------------
    // default state
    // ---------------------------------------------------------------------

    function test_defaultState() public {
        UniswapV3SwapperHarness fresh = new UniswapV3SwapperHarness();
        assertEq(fresh.base(), 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2);
        assertEq(fresh.router(), 0xE592427A0AEce92De3Edee1F18E0157C05861564);
        assertEq(fresh.minAmountToSell(), 0);
    }

    // ---------------------------------------------------------------------
    // _setUniFees
    // ---------------------------------------------------------------------

    function test_setUniFees_setsBidirectionally() public {
        harness.setUniFees(address(tokenA), address(tokenB), 10_000);
        assertEq(harness.uniFees(address(tokenA), address(tokenB)), 10_000);
        assertEq(harness.uniFees(address(tokenB), address(tokenA)), 10_000);
    }

    function test_uniFees_defaultsToZero() public {
        assertEq(harness.uniFees(address(tokenA), address(tokenB)), 0);
    }

    // ---------------------------------------------------------------------
    // _checkAllowance
    // ---------------------------------------------------------------------

    function test_checkAllowance_approvesWhenInsufficient() public {
        assertEq(tokenA.allowance(address(harness), address(router)), 0);
        harness.checkAllowance(address(router), address(tokenA), 1000);
        assertEq(tokenA.allowance(address(harness), address(router)), 1000);
    }

    function test_checkAllowance_noopWhenAlreadySufficient() public {
        harness.checkAllowance(address(router), address(tokenA), 1000);
        assertEq(tokenA.allowance(address(harness), address(router)), 1000);

        // requesting a smaller allowance should not touch the existing approval
        harness.checkAllowance(address(router), address(tokenA), 500);
        assertEq(tokenA.allowance(address(harness), address(router)), 1000);
    }

    function test_checkAllowance_bumpsWhenInsufficient() public {
        harness.checkAllowance(address(router), address(tokenA), 1000);
        harness.checkAllowance(address(router), address(tokenA), 5000);
        assertEq(tokenA.allowance(address(harness), address(router)), 5000);
    }

    // ---------------------------------------------------------------------
    // _swapFrom
    // ---------------------------------------------------------------------

    function test_swapFrom_zeroAmountReturnsZeroAndDoesNothing() public {
        uint256 out = harness.swapFrom(address(base), address(tokenA), 0, 0);
        assertEq(out, 0);
        assertEq(tokenA.balanceOf(address(harness)), 0);
    }

    function test_swapFrom_belowMinAmountToSellReturnsZero() public {
        harness.setMinAmountToSell(1000);
        base.mint(address(harness), 500);

        uint256 out = harness.swapFrom(address(base), address(tokenA), 500, 0);
        assertEq(out, 0);
        assertEq(base.balanceOf(address(harness)), 500); // untouched
    }

    function test_swapFrom_atMinAmountToSellProceeds() public {
        harness.setMinAmountToSell(1000);
        base.mint(address(harness), 1000);
        tokenA.mint(address(router), 1000);

        uint256 out = harness.swapFrom(address(base), address(tokenA), 1000, 0);
        assertEq(out, 1000);
    }

    function test_swapFrom_directSwap_fromIsBase() public {
        base.mint(address(harness), 1_000e18);
        tokenA.mint(address(router), 1_000e18);

        uint256 out = harness.swapFrom(address(base), address(tokenA), 1_000e18, 1);

        assertEq(out, 1_000e18);
        assertEq(tokenA.balanceOf(address(harness)), 1_000e18);
        assertEq(base.balanceOf(address(harness)), 0);

        assertEq(router.lastTokenIn(), address(base));
        assertEq(router.lastTokenOut(), address(tokenA));
        assertEq(router.lastFee(), FEE_LOW);
        assertEq(router.lastRecipient(), address(harness));
        assertEq(router.lastDeadline(), block.timestamp);
    }

    function test_swapFrom_directSwap_toIsBase() public {
        tokenA.mint(address(harness), 500e18);
        base.mint(address(router), 500e18);

        uint256 out = harness.swapFrom(address(tokenA), address(base), 500e18, 1);

        assertEq(out, 500e18);
        assertEq(base.balanceOf(address(harness)), 500e18);
        assertEq(router.lastTokenIn(), address(tokenA));
        assertEq(router.lastTokenOut(), address(base));
    }

    function test_swapFrom_multihopWhenNeitherIsBase() public {
        tokenA.mint(address(harness), 200e18);
        tokenB.mint(address(router), 200e18);

        uint256 out = harness.swapFrom(address(tokenA), address(tokenB), 200e18, 1);

        assertEq(out, 200e18);
        assertEq(tokenB.balanceOf(address(harness)), 200e18);
        assertEq(router.lastTokenIn(), address(tokenA));
        assertEq(router.lastTokenOut(), address(tokenB));

        bytes memory expectedPath =
            abi.encodePacked(address(tokenA), FEE_LOW, address(base), FEE_MED, address(tokenB));
        assertEq(router.lastPath(), expectedPath);
    }

    function test_swapFrom_setsRouterApproval() public {
        base.mint(address(harness), 100e18);
        tokenA.mint(address(router), 100e18);

        harness.swapFrom(address(base), address(tokenA), 100e18, 1);

        assertEq(base.allowance(address(harness), address(router)), 100e18);
    }

    function test_swapFrom_revertsWhenOutputBelowMinimum() public {
        base.mint(address(harness), 100e18);
        tokenA.mint(address(router), 100e18);
        router.setRate(address(base), address(tokenA), 0.5e18); // 100 base -> 50 tokenA

        vm.expectRevert(bytes("too little received"));
        harness.swapFrom(address(base), address(tokenA), 100e18, 60e18);
    }

    function testFuzz_swapFrom_directSwap(uint256 amountIn) public {
        amountIn = bound(amountIn, 1, 1_000_000e18);
        base.mint(address(harness), amountIn);
        tokenA.mint(address(router), amountIn);

        uint256 out = harness.swapFrom(address(base), address(tokenA), amountIn, 0);
        assertEq(out, amountIn);
    }

    // ---------------------------------------------------------------------
    // _swapTo
    // ---------------------------------------------------------------------

    function test_swapTo_zeroMaxAmountReturnsZero() public {
        uint256 in_ = harness.swapTo(address(base), address(tokenA), 100, 0);
        assertEq(in_, 0);
    }

    function test_swapTo_belowMinAmountToSellReturnsZero() public {
        harness.setMinAmountToSell(1000);
        base.mint(address(harness), 500);

        uint256 in_ = harness.swapTo(address(base), address(tokenA), 100, 500);
        assertEq(in_, 0);
        assertEq(base.balanceOf(address(harness)), 500); // untouched
    }

    function test_swapTo_directSwap_fromIsBase() public {
        base.mint(address(harness), 1_000e18);
        tokenA.mint(address(router), 1_000e18);

        uint256 in_ = harness.swapTo(address(base), address(tokenA), 300e18, 1_000e18);

        assertEq(in_, 300e18);
        assertEq(tokenA.balanceOf(address(harness)), 300e18);
        assertEq(base.balanceOf(address(harness)), 700e18);

        assertEq(router.lastTokenIn(), address(base));
        assertEq(router.lastTokenOut(), address(tokenA));
        assertEq(router.lastFee(), FEE_LOW);
        assertEq(router.lastRecipient(), address(harness));
    }

    function test_swapTo_directSwap_toIsBase() public {
        tokenA.mint(address(harness), 1_000e18);
        base.mint(address(router), 1_000e18);

        uint256 in_ = harness.swapTo(address(tokenA), address(base), 400e18, 1_000e18);

        assertEq(in_, 400e18);
        assertEq(base.balanceOf(address(harness)), 400e18);
    }

    function test_swapTo_multihopWhenNeitherIsBase() public {
        tokenA.mint(address(harness), 1_000e18);
