contract UniswapV3SwapperTest is Test {
    UniswapV3SwapperHarness internal harness;
    MockSwapRouter internal mockRouter;

    MockERC20 internal baseToken;
    MockERC20 internal tokenA;
    MockERC20 internal tokenB;
    MockERC20 internal tokenC;

    uint24 internal constant FEE_LOW = 500;
    uint24 internal constant FEE_MED = 3000;

    function setUp() public {
        harness = new UniswapV3SwapperHarness();
        mockRouter = new MockSwapRouter();

        baseToken = new MockERC20("Base", "BASE");
        tokenA = new MockERC20("TokenA", "A");
        tokenB = new MockERC20("TokenB", "B");
        tokenC = new MockERC20("TokenC", "C");

        harness.setBase(address(baseToken));
        harness.setRouter(address(mockRouter));

        // give the router a warchest to pay out with
        baseToken.mint(address(mockRouter), 1_000_000 ether);
        tokenA.mint(address(mockRouter), 1_000_000 ether);
        tokenB.mint(address(mockRouter), 1_000_000 ether);
        tokenC.mint(address(mockRouter), 1_000_000 ether);
    }

    /*//////////////////////////////////////////////////////////
                        DEFAULT STATE / SETUP
    //////////////////////////////////////////////////////////*/

    function test_defaultAddresses() public {
        UniswapV3SwapperHarness fresh = new UniswapV3SwapperHarness();
        assertEq(fresh.base(), 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2);
        assertEq(fresh.router(), 0xE592427A0AEce92De3Edee1F18E0157C05861564);
        assertEq(fresh.minAmountToSell(), 0);
    }

    function test_setUniFees_setsBothDirections() public {
        assertEq(harness.uniFees(address(tokenA), address(tokenB)), 0);
        assertEq(harness.uniFees(address(tokenB), address(tokenA)), 0);

        harness.setUniFeesExternal(address(tokenA), address(tokenB), FEE_LOW);

        assertEq(harness.uniFees(address(tokenA), address(tokenB)), FEE_LOW);
        assertEq(harness.uniFees(address(tokenB), address(tokenA)), FEE_LOW);
    }

    function test_setUniFees_overwritesPreviousValue() public {
        harness.setUniFeesExternal(address(tokenA), address(tokenB), FEE_LOW);
