        assertEq(in_, 6 ether);
        assertEq(mockRouter.lastFn(), "exactOutputSingle");
        assertEq(mockRouter.lastTokenIn(), address(baseToken));
        assertEq(mockRouter.lastTokenOut(), address(tokenA));
