        assertEq(mockRouter.lastAmountInMaximum(), 10 ether);

        assertEq(baseToken.balanceOf(address(harness)), 4 ether);
        assertEq(tokenA.balanceOf(address(harness)), 5 ether);
    }

    function test_swapTo_directPath_toIsBase() public {
        harness.setUniFeesExternal(address(tokenA), address(baseToken), FEE_LOW);
        tokenA.mint(address(harness), 10 ether);
        mockRouter.setMockAmountIn(4 ether);

        uint256 in_ = harness.swapTo(address(tokenA), address(baseToken), 3 ether, 10 ether);

        assertEq(in_, 4 ether);
        assertEq(mockRouter.lastFn(), "exactOutputSingle");
        assertEq(mockRouter.lastTokenIn(), address(tokenA));
        assertEq(mockRouter.lastTokenOut(), address(baseToken));

        assertEq(tokenA.balanceOf(address(harness)), 6 ether);
        assertEq(baseToken.balanceOf(address(harness)), 3 ether);
    }

    function test_swapTo_multiHop_neitherIsBase_usesExactOutputWithEncodedPath() public {
        harness.setUniFeesExternal(address(tokenA), address(baseToken), FEE_LOW);
        harness.setUniFeesExternal(address(baseToken), address(tokenC), FEE_MED);

        tokenA.mint(address(harness), 10 ether);
