        vm.expectRevert("Too much requested");
        harness.swapTo(address(tokenA), address(baseToken), 1 ether, 5 ether);
    }

    function testFuzz_swapTo_thresholdBoundary(uint256 maxAmountFrom, uint256 minAmountToSell) public {
        maxAmountFrom = bound(maxAmountFrom, 0, 1_000_000 ether);
        minAmountToSell = bound(minAmountToSell, 0, 1_000_000 ether);

        harness.setMinAmountToSell(minAmountToSell);
