// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.19;

import { Test } from "forge-std/Test.sol";
import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import { UniswapV3Swapper } from "src/strategies/periphery/UniswapV3Swapper.sol";

/*//////////////////////////////////////////////////////////////
                            MOCK ERC20
//////////////////////////////////////////////////////////////*/

contract MockERC20 is ERC20 {
    constructor(string memory name_, string memory symbol_) ERC20(name_, symbol_) { }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

/*//////////////////////////////////////////////////////////////
                        MOCK SWAP ROUTER
//////////////////////////////////////////////////////////////*/

/// @dev Mirrors ISwapRouter's function selectors (identical field types/order),
///      so it can be called by UniswapV3Swapper through the ISwapRouter interface.
contract MockSwapRouter {
    struct ExactInputSingleParams {
        address tokenIn;
        address tokenOut;
        uint24 fee;
        address recipient;
        uint256 deadline;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 sqrtPriceLimitX96;
    }

    struct ExactInputParams {
        bytes path;
        address recipient;
        uint256 deadline;
        uint256 amountIn;
        uint256 amountOutMinimum;
    }

    struct ExactOutputSingleParams {
        address tokenIn;
        address tokenOut;
        uint24 fee;
        address recipient;
        uint256 deadline;
        uint256 amountOut;
        uint256 amountInMaximum;
        uint160 sqrtPriceLimitX96;
    }

    struct ExactOutputParams {
        bytes path;
        address recipient;
        uint256 deadline;
        uint256 amountOut;
        uint256 amountInMaximum;
    }

    // configurable mock amounts
    uint256 public mockAmountOut;
    uint256 public mockAmountIn;

    // for path-based calls, since the mock does not decode `path`
    address public pathTokenIn;
    address public pathTokenOut;

    // call recording
    uint256 public callCount;
    string public lastFn;
    address public lastTokenIn;
    address public lastTokenOut;
    uint24 public lastFee;
    address public lastRecipient;
    uint256 public lastDeadline;
    uint256 public lastAmountIn;
    uint256 public lastAmountOutMinimum;
    uint256 public lastAmountOut;
    uint256 public lastAmountInMaximum;
    bytes public lastPath;

    function setMockAmountOut(uint256 _v) external {
        mockAmountOut = _v;
    }

    function setMockAmountIn(uint256 _v) external {
        mockAmountIn = _v;
    }

    function setPathTokens(address _tokenIn, address _tokenOut) external {
        pathTokenIn = _tokenIn;
        pathTokenOut = _tokenOut;
    }

    function exactInputSingle(ExactInputSingleParams calldata p) external returns (uint256 amountOut) {
        callCount++;
        lastFn = "exactInputSingle";
        lastTokenIn = p.tokenIn;
        lastTokenOut = p.tokenOut;
        lastFee = p.fee;
        lastRecipient = p.recipient;
        lastDeadline = p.deadline;
        lastAmountIn = p.amountIn;
        lastAmountOutMinimum = p.amountOutMinimum;

        amountOut = mockAmountOut;
        require(amountOut >= p.amountOutMinimum, "Too little received");

        IERC20(p.tokenIn).transferFrom(msg.sender, address(this), p.amountIn);
        IERC20(p.tokenOut).transfer(p.recipient, amountOut);
    }

    function exactInput(ExactInputParams calldata p) external returns (uint256 amountOut) {
        callCount++;
        lastFn = "exactInput";
        lastPath = p.path;
        lastRecipient = p.recipient;
        lastDeadline = p.deadline;
        lastAmountIn = p.amountIn;
        lastAmountOutMinimum = p.amountOutMinimum;

        amountOut = mockAmountOut;
        require(amountOut >= p.amountOutMinimum, "Too little received");

        IERC20(pathTokenIn).transferFrom(msg.sender, address(this), p.amountIn);
        IERC20(pathTokenOut).transfer(p.recipient, amountOut);
    }

    function exactOutputSingle(ExactOutputSingleParams calldata p) external returns (uint256 amountIn) {
        callCount++;
        lastFn = "exactOutputSingle";
        lastTokenIn = p.tokenIn;
        lastTokenOut = p.tokenOut;
        lastFee = p.fee;
        lastRecipient = p.recipient;
        lastDeadline = p.deadline;
        lastAmountOut = p.amountOut;
        lastAmountInMaximum = p.amountInMaximum;

        amountIn = mockAmountIn;
        require(amountIn <= p.amountInMaximum, "Too much requested");

        IERC20(p.tokenIn).transferFrom(msg.sender, address(this), amountIn);
        IERC20(p.tokenOut).transfer(p.recipient, p.amountOut);
    }

    function exactOutput(ExactOutputParams calldata p) external returns (uint256 amountIn) {
        callCount++;
        lastFn = "exactOutput";
        lastPath = p.path;
        lastRecipient = p.recipient;
        lastDeadline = p.deadline;
        lastAmountOut = p.amountOut;
        lastAmountInMaximum = p.amountInMaximum;

        amountIn = mockAmountIn;
        require(amountIn <= p.amountInMaximum, "Too much requested");

        IERC20(pathTokenIn).transferFrom(msg.sender, address(this), amountIn);
        IERC20(pathTokenOut).transfer(p.recipient, p.amountOut);
    }
}

/*//////////////////////////////////////////////////////////////
                             HARNESS
//////////////////////////////////////////////////////////////*/

contract UniswapV3SwapperHarness is UniswapV3Swapper {
    function setMinAmountToSell(uint256 _min) external {
        minAmountToSell = _min;
    }

    function setBase(address _base) external {
        base = _base;
    }

    function setRouter(address _router) external {
        router = _router;
    }

    function setUniFeesExternal(address _token0, address _token1, uint24 _fee) external {
        _setUniFees(_token0, _token1, _fee);
    }

    function swapFrom(
        address _from,
        address _to,
        uint256 _amountIn,
        uint256 _minAmountOut
    ) external returns (uint256) {
        return _swapFrom(_from, _to, _amountIn, _minAmountOut);
    }

    function swapTo(address _from, address _to, uint256 _amountTo, uint256 _maxAmountFrom) external returns (uint256) {
        return _swapTo(_from, _to, _amountTo, _maxAmountFrom);
    }

    function checkAllowance(address _contract, address _token, uint256 _amount) external {
        _checkAllowance(_contract, _token, _amount);
    }
}

/*//////////////////////////////////////////////////////////////
                              TESTS
//////////////////////////////////////////////////////////////*/

contract UniswapV3SwapperTest is Test {
    UniswapV3SwapperHarness internal harness;
    MockSwapRouter internal mockRouter;

    MockERC20 internal baseToken;
