    /*//////////////////////////////////////////////////////////
                          _checkAllowance
    //////////////////////////////////////////////////////////*/

    function test_checkAllowance_approvesWhenInsufficient() public {
        assertEq(tokenA.allowance(address(harness), address(mockRouter)), 0);

