        _mint(to, amount);
    }
}

/// @dev Mimics the two Uniswap V3 SwapRouter functions used by the adapter.
///      Struct field types/order match the real ISwapRouter structs exactly,
///      so the generated function selectors are identical - the adapter can
///      call this mock through the ISwapRouter interface without modification.
contract MockSwapRouter {
    using SafeERC20 for IERC20;

    struct ExactInputSingleParams {
        address tokenIn;
        address tokenOut;
        uint24 fee;
        address recipient;
        uint256 deadline;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 sqrtPriceLimitX96;
    }

    struct ExactInputParams {
        bytes path;
        address recipient;
        uint256 deadline;
        uint256 amountIn;
        uint256 amountOutMinimum;
    }

    // Exchange rate: amountOut = amountPulled * rateNum / rateDen
    uint256 public rateNum = 1;
    uint256 public rateDen = 1;

    // Fraction (out of 10_000) of amountIn actually pulled - lets tests simulate partial fills
    uint256 public pullBps = 10_000;

    bool public shouldRevert;
    string public revertMessage = "MockSwapRouter: forced revert";

    // call recording
    bool public exactInputSingleCalled;
    bool public exactInputCalled;
    address public lastTokenIn;
    address public lastTokenOut;
    uint24 public lastFee;
    address public lastRecipient;
    uint256 public lastDeadline;
    uint256 public lastAmountIn;
    uint256 public lastMinAmountOut;
    bytes public lastPath;

    function setRate(uint256 num, uint256 den) external {
        rateNum = num;
        rateDen = den;
    }

    function setPullBps(uint256 bps) external {
        pullBps = bps;
    }

    function setShouldRevert(bool v) external {
        shouldRevert = v;
    }

    function exactInputSingle(ExactInputSingleParams calldata params) external returns (uint256 amountOut) {
        if (shouldRevert) revert(revertMessage);

        exactInputSingleCalled = true;
        lastTokenIn = params.tokenIn;
        lastTokenOut = params.tokenOut;
        lastFee = params.fee;
        lastRecipient = params.recipient;
        lastDeadline = params.deadline;
        lastAmountIn = params.amountIn;
        lastMinAmountOut = params.amountOutMinimum;

        uint256 amountPulled = (params.amountIn * pullBps) / 10_000;
        if (amountPulled != 0) {
            IERC20(params.tokenIn).safeTransferFrom(msg.sender, address(this), amountPulled);
        }

        amountOut = (amountPulled * rateNum) / rateDen;
        require(amountOut >= params.amountOutMinimum, "Too little received");

        if (amountOut != 0) {
            MockERC20(params.tokenOut).mint(params.recipient, amountOut);
        }
    }

    function exactInput(ExactInputParams calldata params) external returns (uint256 amountOut) {
        if (shouldRevert) revert(revertMessage);

        exactInputCalled = true;
        lastPath = params.path;
        lastRecipient = params.recipient;
        lastDeadline = params.deadline;
        lastAmountIn = params.amountIn;
        lastMinAmountOut = params.amountOutMinimum;

        (address tokenIn, address tokenOut) = _decodePathEnds(params.path);
        lastTokenIn = tokenIn;
        lastTokenOut = tokenOut;

        uint256 amountPulled = (params.amountIn * pullBps) / 10_000;
        if (amountPulled != 0) {
            IERC20(tokenIn).safeTransferFrom(msg.sender, address(this), amountPulled);
        }

        amountOut = (amountPulled * rateNum) / rateDen;
        require(amountOut >= params.amountOutMinimum, "Too little received");

        if (amountOut != 0) {
            MockERC20(tokenOut).mint(params.recipient, amountOut);
        }
    }

    /// @dev Path layout: tokenIn(20) | fee(3) | base(20) | feeOut(3) | tokenOut(20) = 66 bytes
    function _decodePathEnds(bytes memory path) internal pure returns (address tokenIn, address tokenOut) {
        require(path.length == 66, "unexpected path length");
        assembly {
            tokenIn := shr(96, mload(add(path, 32)))
            tokenOut := and(mload(add(path, 66)), 0xffffffffffffffffffffffffffffffffffffffff)
        }
    }
}

// ============================================
// TESTS
// ============================================

contract UniswapV3SwapperAdapterTest is Test {
    uint24 internal constant FEE = 3000;
    uint24 internal constant FEE_OUT = 500;

    MockSwapRouter internal router;
    MockERC20 internal tokenA;
    MockERC20 internal tokenB;
    MockERC20 internal base;

    UniswapV3SwapperAdapter internal singleHopAdapter; // base == address(0)
    UniswapV3SwapperAdapter internal multiHopAdapter; // base != address(0)

    address internal user = makeAddr("user");
    address internal receiver = makeAddr("receiver");

    function setUp() public {
        router = new MockSwapRouter();
        tokenA = new MockERC20("Token A", "TKA");
        tokenB = new MockERC20("Token B", "TKB");
        base = new MockERC20("Base/WETH", "WETH");

        singleHopAdapter = new UniswapV3SwapperAdapter(address(router), FEE, address(0), 0);
        multiHopAdapter = new UniswapV3SwapperAdapter(address(router), FEE, address(base), FEE_OUT);
    }

    function _mintAndApprove(MockERC20 token, address owner, address spender, uint256 amount) internal {
        token.mint(owner, amount);
        vm.prank(owner);
        token.approve(spender, amount);
    }

    // ============================================
    // CONSTRUCTOR
    // ============================================

    function test_constructor_setsImmutables_singleHop() public view {
        assertEq(singleHopAdapter.router(), address(router));
        assertEq(singleHopAdapter.fee(), FEE);
        assertEq(singleHopAdapter.base(), address(0));
        assertEq(singleHopAdapter.feeOut(), 0);
    }

    function test_constructor_setsImmutables_multiHop() public view {
        assertEq(multiHopAdapter.router(), address(router));
        assertEq(multiHopAdapter.fee(), FEE);
        assertEq(multiHopAdapter.base(), address(base));
        assertEq(multiHopAdapter.feeOut(), FEE_OUT);
    }

    function test_constructor_revertsOnZeroRouter() public {
        vm.expectRevert(UniswapV3SwapperAdapter.InvalidRouter.selector);
        new UniswapV3SwapperAdapter(address(0), FEE, address(0), 0);
    }

    function test_constructor_allowsZeroBase() public {
        UniswapV3SwapperAdapter adapter = new UniswapV3SwapperAdapter(address(router), FEE, address(0), 0);
        assertEq(adapter.base(), address(0));
    }

    // ============================================
    // INPUT VALIDATION
    // ============================================

    function test_swap_revertsOnZeroTokenIn() public {
        vm.expectRevert(UniswapV3SwapperAdapter.InvalidToken.selector);
        vm.prank(user);
        singleHopAdapter.swap(address(0), address(tokenB), 1 ether, 0, receiver);
    }

    function test_swap_revertsOnZeroTokenOut() public {
        vm.expectRevert(UniswapV3SwapperAdapter.InvalidToken.selector);
        vm.prank(user);
        singleHopAdapter.swap(address(tokenA), address(0), 1 ether, 0, receiver);
    }

    // ============================================
    // SINGLE-HOP MODE (base == address(0))
    // ============================================

    function test_swap_singleHop_fullFill_success() public {
        uint256 amountIn = 100 ether;
        _mintAndApprove(tokenA, user, address(singleHopAdapter), amountIn);

        vm.prank(user);
        uint256 amountOut = singleHopAdapter.swap(address(tokenA), address(tokenB), amountIn, 0, receiver);

        assertEq(amountOut, amountIn, "1:1 rate should yield equal amountOut");
        assertEq(tokenB.balanceOf(receiver), amountIn, "receiver should get tokenOut");
        assertEq(tokenA.balanceOf(user), 0, "user's tokenIn should be fully spent");
        assertEq(tokenA.balanceOf(address(singleHopAdapter)), 0, "adapter should hold no leftover tokenIn");
        assertEq(tokenA.allowance(address(singleHopAdapter), address(router)), 0, "router allowance must be reset");

        assertTrue(router.exactInputSingleCalled());
        assertEq(router.lastTokenIn(), address(tokenA));
        assertEq(router.lastTokenOut(), address(tokenB));
        assertEq(router.lastFee(), FEE);
        assertEq(router.lastRecipient(), receiver);
        assertEq(router.lastAmountIn(), amountIn);
    }

    function test_swap_singleHop_usesBlockTimestampAsDeadline() public {
        vm.warp(1_700_000_000);
        uint256 amountIn = 1 ether;
        _mintAndApprove(tokenA, user, address(singleHopAdapter), amountIn);

        vm.prank(user);
        singleHopAdapter.swap(address(tokenA), address(tokenB), amountIn, 0, receiver);

        assertEq(router.lastDeadline(), block.timestamp);
    }

    function test_swap_singleHop_partialFill_refundsLeftoverToCaller() public {
        uint256 amountIn = 100 ether;
        router.setPullBps(6000); // router only consumes 60%
        _mintAndApprove(tokenA, user, address(singleHopAdapter), amountIn);

        vm.prank(user);
        uint256 amountOut = singleHopAdapter.swap(address(tokenA), address(tokenB), amountIn, 0, receiver);

        uint256 expectedPulled = (amountIn * 6000) / 10_000;
        assertEq(amountOut, expectedPulled);
        assertEq(tokenB.balanceOf(receiver), expectedPulled);
        assertEq(tokenA.balanceOf(user), amountIn - expectedPulled, "leftover must be refunded to caller");
        assertEq(tokenA.balanceOf(address(singleHopAdapter)), 0, "adapter must not retain tokens");
        assertEq(tokenA.allowance(address(singleHopAdapter), address(router)), 0);
    }

    function test_swap_singleHop_receiverDistinctFromCaller() public {
        uint256 amountIn = 10 ether;
        _mintAndApprove(tokenA, user, address(singleHopAdapter), amountIn);

        vm.prank(user);
        singleHopAdapter.swap(address(tokenA), address(tokenB), amountIn, 0, receiver);

        assertEq(tokenB.balanceOf(user), 0, "caller must not receive tokenOut");
        assertEq(tokenB.balanceOf(receiver), amountIn);
    }

    function test_swap_singleHop_revertsWithoutApproval() public {
        uint256 amountIn = 1 ether;
        tokenA.mint(user, amountIn); // no approve

        vm.expectRevert();
        vm.prank(user);
        singleHopAdapter.swap(address(tokenA), address(tokenB), amountIn, 0, receiver);
    }

    function test_swap_singleHop_revertsWithInsufficientBalance() public {
        uint256 amountIn = 1 ether;
        vm.prank(user);
        tokenA.approve(address(singleHopAdapter), amountIn); // approved but never minted

        vm.expectRevert();
        vm.prank(user);
        singleHopAdapter.swap(address(tokenA), address(tokenB), amountIn, 0, receiver);
    }

    function test_swap_singleHop_revertsWhenRouterReverts_stateFullyRolledBack() public {
        uint256 amountIn = 5 ether;
        router.setShouldRevert(true);
        _mintAndApprove(tokenA, user, address(singleHopAdapter), amountIn);

        vm.expectRevert(bytes("MockSwapRouter: forced revert"));
        vm.prank(user);
        singleHopAdapter.swap(address(tokenA), address(tokenB), amountIn, 0, receiver);

        // Nothing should have moved since the whole call reverted atomically
        assertEq(tokenA.balanceOf(user), amountIn);
        assertEq(tokenA.balanceOf(address(singleHopAdapter)), 0);
        assertEq(tokenA.allowance(address(singleHopAdapter), address(router)), 0);
    }

    function test_swap_singleHop_revertsWhenMinAmountOutNotMet() public {
        uint256 amountIn = 10 ether;
        router.setPullBps(5000); // only 50% consumed -> amountOut will be less than amountIn
        _mintAndApprove(tokenA, user, address(singleHopAdapter), amountIn);

        vm.expectRevert(bytes("Too little received"));
        vm.prank(user);
        singleHopAdapter.swap(address(tokenA), address(tokenB), amountIn, amountIn, receiver);
    }

    function test_swap_singleHop_zeroAmountIn_doesNotRevert() public {
        _mintAndApprove(tokenA, user, address(singleHopAdapter), 0);

        vm.prank(user);
        uint256 amountOut = singleHopAdapter.swap(address(tokenA), address(tokenB), 0, 0, receiver);

        assertEq(amountOut, 0);
    }

    function test_swap_singleHop_multipleCallsAreIndependent() public {
        uint256 amountIn = 1 ether;
        _mintAndApprove(tokenA, user, address(singleHopAdapter), amountIn * 2);

        vm.startPrank(user);
        tokenA.approve(address(singleHopAdapter), amountIn * 2);
        uint256 out1 = singleHopAdapter.swap(address(tokenA), address(tokenB), amountIn, 0, receiver);
        uint256 out2 = singleHopAdapter.swap(address(tokenA), address(tokenB), amountIn, 0, receiver);
        vm.stopPrank();

        assertEq(out1, amountIn);
        assertEq(out2, amountIn);
        assertEq(tokenB.balanceOf(receiver), amountIn * 2);
        assertEq(tokenA.allowance(address(singleHopAdapter), address(router)), 0);
    }

    // ============================================
    // MULTI-HOP MODE (base != address(0))
    // ============================================

    function test_swap_multiHop_tokenInIsBase_usesFeeOutAndSingleHop() public {
        uint256 amountIn = 4 ether;
        _mintAndApprove(base, user, address(multiHopAdapter), amountIn);

        vm.prank(user);
        multiHopAdapter.swap(address(base), address(tokenB), amountIn, 0, receiver);

        assertTrue(router.exactInputSingleCalled());
        assertFalse(router.exactInputCalled());
        assertEq(router.lastFee(), FEE_OUT, "tokenIn == base should use feeOut for the single hop");
        assertEq(router.lastTokenIn(), address(base));
        assertEq(router.lastTokenOut(), address(tokenB));
    }

    function test_swap_multiHop_tokenOutIsBase_usesFeeAndSingleHop() public {
        uint256 amountIn = 4 ether;
        _mintAndApprove(tokenA, user, address(multiHopAdapter), amountIn);

        vm.prank(user);
        multiHopAdapter.swap(address(tokenA), address(base), amountIn, 0, receiver);

        assertTrue(router.exactInputSingleCalled());
        assertFalse(router.exactInputCalled());
        assertEq(router.lastFee(), FEE, "tokenOut == base should use fee for the single hop");
        assertEq(router.lastTokenIn(), address(tokenA));
        assertEq(router.lastTokenOut(), address(base));
    }

    function test_swap_multiHop_neitherIsBase_usesExactInputWithCorrectPath() public {
        uint256 amountIn = 4 ether;
        _mintAndApprove(tokenA, user, address(multiHopAdapter), amountIn);

        vm.prank(user);
        uint256 amountOut = multiHopAdapter.swap(address(tokenA), address(tokenB), amountIn, 0, receiver);

        assertTrue(router.exactInputCalled());
        assertFalse(router.exactInputSingleCalled());
        assertEq(amountOut, amountIn);

        bytes memory expectedPath = abi.encodePacked(address(tokenA), FEE, address(base), FEE_OUT, address(tokenB));
        assertEq(keccak256(router.lastPath()), keccak256(expectedPath));
        assertEq(router.lastRecipient(), receiver);
        assertEq(router.lastAmountIn(), amountIn);

        assertEq(tokenA.balanceOf(address(multiHopAdapter)), 0);
        assertEq(tokenA.allowance(address(multiHopAdapter), address(router)), 0);
    }

    function test_swap_multiHop_neitherIsBase_partialFillRefundsLeftover() public {
        uint256 amountIn = 8 ether;
        router.setPullBps(2500); // 25% consumed
        _mintAndApprove(tokenA, user, address(multiHopAdapter), amountIn);

        vm.prank(user);
        uint256 amountOut = multiHopAdapter.swap(address(tokenA), address(tokenB), amountIn, 0, receiver);

        uint256 expectedPulled = (amountIn * 2500) / 10_000;
        assertEq(amountOut, expectedPulled);
        assertEq(tokenB.balanceOf(receiver), expectedPulled);
        assertEq(tokenA.balanceOf(user), amountIn - expectedPulled);
        assertEq(tokenA.balanceOf(address(multiHopAdapter)), 0);
    }

    function test_swap_multiHop_revertsWhenRouterReverts() public {
        uint256 amountIn = 2 ether;
        router.setShouldRevert(true);
        _mintAndApprove(tokenA, user, address(multiHopAdapter), amountIn);

        vm.expectRevert(bytes("MockSwapRouter: forced revert"));
        vm.prank(user);
        multiHopAdapter.swap(address(tokenA), address(tokenB), amountIn, 0, receiver);
    }

    // ============================================
    // FUZZ
    // ============================================

    function testFuzz_swap_singleHop_invariants(uint256 amountIn, uint256 pullBps) public {
        amountIn = bound(amountIn, 0, 1_000_000 ether);
        pullBps = bound(pullBps, 0, 10_000);
        router.setPullBps(pullBps);

        _mintAndApprove(tokenA, user, address(singleHopAdapter), amountIn);

        vm.prank(user);
        uint256 amountOut = singleHopAdapter.swap(address(tokenA), address(tokenB), amountIn, 0, receiver);

        uint256 expectedPulled = (amountIn * pullBps) / 10_000;
        assertEq(amountOut, expectedPulled);
        assertEq(tokenB.balanceOf(receiver), expectedPulled);
        assertEq(tokenA.balanceOf(user), amountIn - expectedPulled);
        assertEq(tokenA.balanceOf(address(singleHopAdapter)), 0, "adapter must never retain tokenIn");
        assertEq(tokenA.allowance(address(singleHopAdapter), address(router)), 0, "router allowance must always be reset");
    }

    function testFuzz_swap_multiHop_neitherIsBase_invariants(uint256 amountIn, uint256 pullBps) public {
        amountIn = bound(amountIn, 0, 1_000_000 ether);
        pullBps = bound(pullBps, 0, 10_000);
        router.setPullBps(pullBps);

        _mintAndApprove(tokenA, user, address(multiHopAdapter), amountIn);

        vm.prank(user);
        uint256 amountOut = multiHopAdapter.swap(address(tokenA), address(tokenB), amountIn, 0, receiver);

        uint256 expectedPulled = (amountIn * pullBps) / 10_000;
        assertEq(amountOut, expectedPulled);
        assertEq(tokenB.balanceOf(receiver), expectedPulled);
        assertEq(tokenA.balanceOf(user), amountIn - expectedPulled);
        assertEq(tokenA.balanceOf(address(multiHopAdapter)), 0);
        assertEq(tokenA.allowance(address(multiHopAdapter), address(router)), 0);
    }
}

