/// @notice Minimal mock of the Uniswap V3 SwapRouter.
/// @dev Intentionally does NOT declare `is ISwapRouter` so it only needs to implement the two
///      functions the adapter actually calls, regardless of what else the real interface exposes.
///      Selector matching against `ISwapRouter(router).exactInputSingle/exactInput` still works.
contract MockSwapRouter {
    bool public shouldRevert;
    string public revertMessage = "MockRouter: forced revert";
    uint256 public outAmount;
    // Fraction (in bps) of `amountIn` the router actually pulls from the caller.
    // 10_000 = pulls everything (no leftover). Anything less simulates a partial fill.
    uint256 public pullBps = 10_000;

    // --- exactInputSingle call recording ---
    bool public singleCalled;
    address public lastTokenIn;
    address public lastTokenOut;
    uint24 public lastFee;
    address public lastRecipient;
    uint256 public lastDeadline;
    uint256 public lastAmountIn;
    uint256 public lastAmountOutMinimum;
    uint160 public lastSqrtPriceLimitX96;
    uint256 public lastAllowanceAtCall;

    // --- exactInput (multi-hop) call recording ---
    bool public multiCalled;
    bytes public lastPath;
    address public lastPathRecipient;
    uint256 public lastPathDeadline;
    uint256 public lastPathAmountIn;
    uint256 public lastPathAmountOutMinimum;
    uint256 public lastPathAllowanceAtCall;

    function setShouldRevert(bool v) external {
        shouldRevert = v;
    }

    function setOutAmount(uint256 v) external {
        outAmount = v;
    }

    function setPullBps(uint256 v) external {
        pullBps = v;
    }

    function exactInputSingle(ISwapRouter.ExactInputSingleParams calldata params)
        external
        payable
        returns (uint256 amountOut)
    {
        singleCalled = true;
        lastTokenIn = params.tokenIn;
        lastTokenOut = params.tokenOut;
        lastFee = params.fee;
        lastRecipient = params.recipient;
        lastDeadline = params.deadline;
        lastAmountIn = params.amountIn;
        lastAmountOutMinimum = params.amountOutMinimum;
        lastSqrtPriceLimitX96 = params.sqrtPriceLimitX96;
        lastAllowanceAtCall = IERC20(params.tokenIn).allowance(msg.sender, address(this));

        if (shouldRevert) revert(revertMessage);

        uint256 pullAmount = (params.amountIn * pullBps) / 10_000;
        if (pullAmount != 0) {
            IERC20(params.tokenIn).transferFrom(msg.sender, address(this), pullAmount);
        }

        amountOut = outAmount;
        require(amountOut >= params.amountOutMinimum, "Too little received");
        MockERC20(params.tokenOut).mint(params.recipient, amountOut);
    }

    function exactInput(ISwapRouter.ExactInputParams calldata params) external payable returns (uint256 amountOut) {
        multiCalled = true;
        lastPath = params.path;
        lastPathRecipient = params.recipient;
        lastPathDeadline = params.deadline;
        lastPathAmountIn = params.amountIn;
        lastPathAmountOutMinimum = params.amountOutMinimum;

        address tokenIn = _toAddress(params.path, 0);
        address tokenOut = _toAddress(params.path, params.path.length - 20);

        lastPathAllowanceAtCall = IERC20(tokenIn).allowance(msg.sender, address(this));

        if (shouldRevert) revert(revertMessage);

        uint256 pullAmount = (params.amountIn * pullBps) / 10_000;
