import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import { ISwapRouter } from "@tokenized-strategy-periphery/interfaces/Uniswap/V3/ISwapRouter.sol";
import { UniswapV3SwapperAdapter } from "src/swappers/UniswapV3SwapperAdapter.sol";

/// @notice Minimal mintable ERC20 used as tokenIn/tokenOut/base in tests
contract MockERC20 is ERC20 {
    constructor(string memory name_, string memory symbol_) ERC20(name_, symbol_) { }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

/// @notice Minimal Uniswap V3 SwapRouter mock.
/// @dev Implements only the two functions the adapter calls, using the exact
///      struct types from the real ISwapRouter interface so calldata encoding
///      (and therefore function selectors) match what the adapter sends.
contract MockSwapRouter {
    uint256 public amountOutToReturn;

    uint256 public amountInOverride;
    bool public useAmountInOverride;

    uint256 public exactInputSingleCallCount;
    uint256 public exactInputCallCount;

    address public lastTokenIn;
    address public lastTokenOut;
    uint24 public lastFee;
    address public lastRecipient;
    uint256 public lastDeadline;
    uint256 public lastAmountIn;
    uint256 public lastAmountOutMinimum;
    uint160 public lastSqrtPriceLimitX96;

    bytes public lastPath;

    function setAmountOut(uint256 _amountOut) external {
        amountOutToReturn = _amountOut;
    }

    /// @dev When set, the router only pulls `_amountIn` tokens instead of the
    ///      full requested amount, simulating a partial fill.
    function setAmountInOverride(uint256 _amountIn) external {
        amountInOverride = _amountIn;
        useAmountInOverride = true;
    }

    function exactInputSingle(ISwapRouter.ExactInputSingleParams calldata params)
        external
        payable
        returns (uint256 amountOut)
    {
        exactInputSingleCallCount++;
        lastTokenIn = params.tokenIn;
        lastTokenOut = params.tokenOut;
        lastFee = params.fee;
        lastRecipient = params.recipient;
        lastDeadline = params.deadline;
        lastAmountIn = params.amountIn;
        lastAmountOutMinimum = params.amountOutMinimum;
        lastSqrtPriceLimitX96 = params.sqrtPriceLimitX96;

        uint256 pull = useAmountInOverride ? amountInOverride : params.amountIn;
        if (pull > 0) {
            IERC20(params.tokenIn).transferFrom(msg.sender, address(this), pull);
        }

        amountOut = amountOutToReturn;
        if (amountOut > 0) {
            MockERC20(params.tokenOut).mint(params.recipient, amountOut);
        }
    }

    function exactInput(ISwapRouter.ExactInputParams calldata params)
        external
        payable
        returns (uint256 amountOut)
    {
        exactInputCallCount++;
        lastPath = params.path;
        lastRecipient = params.recipient;
        lastDeadline = params.deadline;
        lastAmountIn = params.amountIn;
        lastAmountOutMinimum = params.amountOutMinimum;

        address tokenIn_ = _firstAddress(params.path);
        address tokenOut_ = _lastAddress(params.path);

        uint256 pull = useAmountInOverride ? amountInOverride : params.amountIn;
        if (pull > 0) {
            IERC20(tokenIn_).transferFrom(msg.sender, address(this), pull);
        }

        amountOut = amountOutToReturn;
        if (amountOut > 0) {
            MockERC20(tokenOut_).mint(params.recipient, amountOut);
        }
    }

    function _firstAddress(bytes memory data) internal pure returns (address addr) {
        require(data.length >= 20, "path too short");
        assembly {
            addr := shr(96, mload(add(data, 0x20)))
        }
    }

    function _lastAddress(bytes memory data) internal pure returns (address addr) {
        require(data.length >= 20, "path too short");
        uint256 offset = data.length - 20;
        assembly {
            addr := shr(96, mload(add(add(data, 0x20), offset)))
        }
    }
}

contract UniswapV3SwapperAdapterTest is Test {
    uint24 internal constant FEE = 3000;
    uint24 internal constant FEE_OUT = 500;

    MockERC20 internal tokenIn;
    MockERC20 internal tokenOut;
    MockERC20 internal baseToken;

    MockSwapRouter internal router;

    UniswapV3SwapperAdapter internal singleHopAdapter; // base == address(0)
    UniswapV3SwapperAdapter internal multiHopAdapter; // base == baseToken

    address internal alice = makeAddr("alice");
    address internal receiver = makeAddr("receiver");

    function setUp() public {
        tokenIn = new MockERC20("TokenIn", "TIN");
        tokenOut = new MockERC20("TokenOut", "TOUT");
        baseToken = new MockERC20("Base", "BASE");

        router = new MockSwapRouter();

        singleHopAdapter = new UniswapV3SwapperAdapter(address(router), FEE, address(0), 0);
        multiHopAdapter = new UniswapV3SwapperAdapter(address(router), FEE, address(baseToken), FEE_OUT);
    }

    // ============================================
    // Helpers
    // ============================================

    function _fund(MockERC20 token, address to, uint256 amount) internal {
        token.mint(to, amount);
    }

    function _approve(MockERC20 token, address owner, address spender, uint256 amount) internal {
        vm.prank(owner);
        token.approve(spender, amount);
    }

    // ============================================
    // Constructor
    // ============================================

    function test_constructor_RevertsIfRouterIsZero() public {
        vm.expectRevert(UniswapV3SwapperAdapter.InvalidRouter.selector);
        new UniswapV3SwapperAdapter(address(0), FEE, address(0), 0);
    }

    function test_constructor_SetsImmutables_SingleHop() public view {
        assertEq(singleHopAdapter.router(), address(router));
        assertEq(singleHopAdapter.fee(), FEE);
        assertEq(singleHopAdapter.base(), address(0));
        assertEq(singleHopAdapter.feeOut(), 0);
    }

    function test_constructor_SetsImmutables_MultiHop() public view {
        assertEq(multiHopAdapter.router(), address(router));
        assertEq(multiHopAdapter.fee(), FEE);
        assertEq(multiHopAdapter.base(), address(baseToken));
        assertEq(multiHopAdapter.feeOut(), FEE_OUT);
    }

    // ============================================
    // Input validation
    // ============================================

    function test_swap_RevertsIfTokenInIsZero() public {
        vm.expectRevert(UniswapV3SwapperAdapter.InvalidToken.selector);
        singleHopAdapter.swap(address(0), address(tokenOut), 1 ether, 0, receiver);
    }

    function test_swap_RevertsIfTokenOutIsZero() public {
        vm.expectRevert(UniswapV3SwapperAdapter.InvalidToken.selector);
        singleHopAdapter.swap(address(tokenIn), address(0), 1 ether, 0, receiver);
    }

    function test_swap_RevertsIfCallerHasNotApprovedAdapter() public {
        uint256 amountIn = 10 ether;
        _fund(tokenIn, alice, amountIn);
        // no approval given

        vm.prank(alice);
        vm.expectRevert();
        singleHopAdapter.swap(address(tokenIn), address(tokenOut), amountIn, 0, receiver);
    }

    function test_swap_RevertsIfCallerHasInsufficientBalance() public {
        uint256 amountIn = 10 ether;
        _approve(tokenIn, alice, address(singleHopAdapter), amountIn);
        // alice never received tokens

        vm.prank(alice);
        vm.expectRevert();
        singleHopAdapter.swap(address(tokenIn), address(tokenOut), amountIn, 0, receiver);
    }

    // ============================================
    // Single-hop: base == address(0)
    // ============================================

    function test_swap_SingleHop_BaseZero_UsesExactInputSingleWithFee() public {
        uint256 amountIn = 100 ether;
        uint256 amountOut = 95 ether;

        router.setAmountOut(amountOut);
        _fund(tokenIn, alice, amountIn);
        _approve(tokenIn, alice, address(singleHopAdapter), amountIn);

        vm.prank(alice);
        uint256 out = singleHopAdapter.swap(address(tokenIn), address(tokenOut), amountIn, 90 ether, receiver);

        assertEq(out, amountOut, "returned amountOut mismatch");
        assertEq(tokenOut.balanceOf(receiver), amountOut, "receiver did not get tokenOut");
        assertEq(tokenIn.balanceOf(alice), 0, "alice tokenIn not fully pulled");
        assertEq(tokenIn.balanceOf(address(singleHopAdapter)), 0, "adapter should hold no leftover");

        assertEq(router.exactInputSingleCallCount(), 1);
        assertEq(router.exactInputCallCount(), 0);
        assertEq(router.lastTokenIn(), address(tokenIn));
        assertEq(router.lastTokenOut(), address(tokenOut));
        assertEq(router.lastFee(), FEE);
        assertEq(router.lastRecipient(), receiver);
        assertEq(router.lastAmountIn(), amountIn);
        assertEq(router.lastAmountOutMinimum(), 90 ether);
        assertEq(router.lastDeadline(), block.timestamp);

        assertEq(tokenIn.allowance(address(singleHopAdapter), address(router)), 0, "allowance not reset");
    }

    // ============================================
    // Single-hop fallback: base != 0, tokenIn == base
    // ============================================

    function test_swap_SingleHop_WhenTokenInIsBase_UsesFeeOut() public {
        uint256 amountIn = 50 ether;
        uint256 amountOut = 48 ether;

        router.setAmountOut(amountOut);
        _fund(baseToken, alice, amountIn);
        _approve(baseToken, alice, address(multiHopAdapter), amountIn);

        vm.prank(alice);
        uint256 out = multiHopAdapter.swap(address(baseToken), address(tokenOut), amountIn, 0, receiver);

        assertEq(out, amountOut);
        assertEq(router.exactInputSingleCallCount(), 1);
        assertEq(router.exactInputCallCount(), 0);
        assertEq(router.lastFee(), FEE_OUT, "should use feeOut when tokenIn is base");
        assertEq(router.lastTokenIn(), address(baseToken));
        assertEq(router.lastTokenOut(), address(tokenOut));
        assertEq(tokenOut.balanceOf(receiver), amountOut);
    }

    // ============================================
    // Single-hop fallback: base != 0, tokenOut == base
    // ============================================

    function test_swap_SingleHop_WhenTokenOutIsBase_UsesFee() public {
        uint256 amountIn = 50 ether;
        uint256 amountOut = 48 ether;

        router.setAmountOut(amountOut);
        _fund(tokenIn, alice, amountIn);
        _approve(tokenIn, alice, address(multiHopAdapter), amountIn);

        vm.prank(alice);
        uint256 out = multiHopAdapter.swap(address(tokenIn), address(baseToken), amountIn, 0, receiver);

        assertEq(out, amountOut);
        assertEq(router.exactInputSingleCallCount(), 1);
        assertEq(router.exactInputCallCount(), 0);
        assertEq(router.lastFee(), FEE, "should use fee when tokenOut is base");
        assertEq(router.lastTokenIn(), address(tokenIn));
        assertEq(router.lastTokenOut(), address(baseToken));
        assertEq(baseToken.balanceOf(receiver), amountOut);
    }

    // ============================================
    // Multi-hop: base != 0, neither token is base
    // ============================================

    function test_swap_MultiHop_UsesExactInputWithEncodedPath() public {
        uint256 amountIn = 200 ether;
        uint256 amountOut = 190 ether;

        router.setAmountOut(amountOut);
        _fund(tokenIn, alice, amountIn);
        _approve(tokenIn, alice, address(multiHopAdapter), amountIn);

        vm.prank(alice);
        uint256 out = multiHopAdapter.swap(address(tokenIn), address(tokenOut), amountIn, 180 ether, receiver);

        assertEq(out, amountOut);
        assertEq(router.exactInputCallCount(), 1);
        assertEq(router.exactInputSingleCallCount(), 0);

        bytes memory expectedPath = abi.encodePacked(address(tokenIn), FEE, address(baseToken), FEE_OUT, address(tokenOut));
        assertEq(router.lastPath(), expectedPath, "path encoding mismatch");
        assertEq(router.lastRecipient(), receiver);
        assertEq(router.lastAmountIn(), amountIn);
        assertEq(router.lastAmountOutMinimum(), 180 ether);
        assertEq(router.lastDeadline(), block.timestamp);

        assertEq(tokenOut.balanceOf(receiver), amountOut);
        assertEq(tokenIn.allowance(address(multiHopAdapter), address(router)), 0);
    }

    // ============================================
    // Leftover / partial-fill refund behavior
    // ============================================

    function test_swap_RefundsLeftoverToCaller_OnPartialFill_SingleHop() public {
        uint256 amountIn = 100 ether;
        uint256 pulled = 60 ether;
        uint256 amountOut = 55 ether;

        router.setAmountOut(amountOut);
        router.setAmountInOverride(pulled);

        _fund(tokenIn, alice, amountIn);
        _approve(tokenIn, alice, address(singleHopAdapter), amountIn);

        vm.prank(alice);
        uint256 out = singleHopAdapter.swap(address(tokenIn), address(tokenOut), amountIn, 0, receiver);

        assertEq(out, amountOut);
        // leftover (amountIn - pulled) refunded back to msg.sender (alice), not receiver
        assertEq(tokenIn.balanceOf(alice), amountIn - pulled, "leftover not refunded to caller");
        assertEq(tokenIn.balanceOf(address(singleHopAdapter)), 0, "adapter should not retain leftover");
        assertEq(tokenIn.balanceOf(receiver), 0, "receiver should not get tokenIn");
        assertEq(tokenOut.balanceOf(receiver), amountOut, "receiver should get tokenOut");

        // allowance fully reset regardless of partial consumption
        assertEq(tokenIn.allowance(address(singleHopAdapter), address(router)), 0);
    }

    function test_swap_RefundsLeftoverToCaller_OnPartialFill_MultiHop() public {
        uint256 amountIn = 100 ether;
        uint256 pulled = 70 ether;
        uint256 amountOut = 65 ether;

        router.setAmountOut(amountOut);
        router.setAmountInOverride(pulled);

        _fund(tokenIn, alice, amountIn);
        _approve(tokenIn, alice, address(multiHopAdapter), amountIn);

        vm.prank(alice);
        uint256 out = multiHopAdapter.swap(address(tokenIn), address(tokenOut), amountIn, 0, receiver);

        assertEq(out, amountOut);
        assertEq(tokenIn.balanceOf(alice), amountIn - pulled);
        assertEq(tokenIn.balanceOf(address(multiHopAdapter)), 0);
        assertEq(tokenOut.balanceOf(receiver), amountOut);
        assertEq(tokenIn.allowance(address(multiHopAdapter), address(router)), 0);
    }

    function test_swap_NoLeftoverRefund_OnFullFill() public {
        uint256 amountIn = 100 ether;
        uint256 amountOut = 95 ether;

        router.setAmountOut(amountOut);
        // no override -> router pulls full amountIn

        _fund(tokenIn, alice, amountIn);
        _approve(tokenIn, alice, address(singleHopAdapter), amountIn);

        uint256 aliceBalanceBefore = tokenIn.balanceOf(alice);

        vm.prank(alice);
        singleHopAdapter.swap(address(tokenIn), address(tokenOut), amountIn, 0, receiver);

        assertEq(tokenIn.balanceOf(alice), aliceBalanceBefore - amountIn);
        assertEq(tokenIn.balanceOf(address(singleHopAdapter)), 0);
    }

    // ============================================
    // Receiver vs caller distinction
    // ============================================

    function test_swap_SendsOutputToReceiver_NotCaller() public {
        uint256 amountIn = 10 ether;
        uint256 amountOut = 9 ether;

        router.setAmountOut(amountOut);
        _fund(tokenIn, alice, amountIn);
        _approve(tokenIn, alice, address(singleHopAdapter), amountIn);

        assertTrue(receiver != alice);

        vm.prank(alice);
        singleHopAdapter.swap(address(tokenIn), address(tokenOut), amountIn, 0, receiver);

        assertEq(tokenOut.balanceOf(alice), 0);
        assertEq(tokenOut.balanceOf(receiver), amountOut);
    }

    // ============================================
    // Fuzz
    // ============================================

    function testFuzz_swap_SingleHop_FullFill(uint96 amountInRaw, uint96 amountOutRaw) public {
        uint256 amountIn = uint256(amountInRaw) + 1; // avoid zero
        uint256 amountOut = uint256(amountOutRaw);

        router.setAmountOut(amountOut);
        _fund(tokenIn, alice, amountIn);
        _approve(tokenIn, alice, address(singleHopAdapter), amountIn);

        vm.prank(alice);
        uint256 out = singleHopAdapter.swap(address(tokenIn), address(tokenOut), amountIn, 0, receiver);

        assertEq(out, amountOut);
        assertEq(tokenIn.balanceOf(alice), 0);
        assertEq(tokenIn.balanceOf(address(singleHopAdapter)), 0);
        assertEq(tokenOut.balanceOf(receiver), amountOut);
        assertEq(tokenIn.allowance(address(singleHopAdapter), address(router)), 0);
    }
}

