// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.25;

import { Test } from "forge-std/Test.sol";
import { MorphoCompounderStrategyFactory } from "src/factories/MorphoCompounderStrategyFactory.sol";
import { USDC_MAINNET } from "src/constants.sol";

/// @dev Minimal stand-in for the real Yearn V3 `TokenizedStrategy` implementation.
/// `MorphoCompounderStrategy`'s constructor performs a `delegatecall` into the
/// address supplied as `_tokenizedStrategyAddress` to run its initialization
/// logic. A contract with only an empty fallback is enough to satisfy that
/// call (any call into a contract that has code but no matching function
/// simply falls through to `fallback()` and returns successfully), which lets
/// us exercise the *factory's* deployment/address-prediction logic without
/// needing to wire up the full tokenized-strategy periphery.
contract MockTokenizedStrategy {
    fallback() external payable { }
    receive() external payable { }
}

contract MorphoCompounderStrategyFactoryTest is Test {
    // Mirrors the event declared on MorphoCompounderStrategyFactory so it can
    // be used with vm.expectEmit / emit from this test file.
    event StrategyDeploy(
        address indexed deployer, address indexed donationAddress, address indexed strategyAddress, string vaultTokenName
    );

    MorphoCompounderStrategyFactory internal factory;
    MockTokenizedStrategy internal tokenizedStrategyImpl;

    address internal management = makeAddr("management");
    address internal keeper = makeAddr("keeper");
    address internal emergencyAdmin = makeAddr("emergencyAdmin");
    address internal donationAddress = makeAddr("donationAddress");

    address internal constant YS_USDC = 0x074134A2784F4F66b6ceD6f68849382990Ff3215;

    function setUp() public {
        // The factory hardcodes real mainnet addresses (YS_USDC, USDC), and
        // MorphoCompounderStrategy's constructor interacts with them (e.g.
        // approvals / sanity checks against the real vault & token), so
        // deployment tests need a mainnet fork. Pure view-logic tests below
        // (computeStrategyAddress reverts / determinism) do not actually
        // depend on the fork, but we run everything against it for
        // consistency and to allow an env override in CI.
        string memory rpcUrl = vm.envOr("MAINNET_RPC_URL", string("https://ethereum.publicnode.com"));
        vm.createSelectFork(rpcUrl);

        factory = new MorphoCompounderStrategyFactory();
        tokenizedStrategyImpl = new MockTokenizedStrategy();
    }

    // ---------------------------------------------------------------------
    // Constants
    // ---------------------------------------------------------------------

    function test_Constants() public view {
        assertEq(factory.YS_USDC(), YS_USDC, "YS_USDC mismatch");
        assertEq(factory.USDC(), USDC_MAINNET, "USDC mismatch");
    }

    // ---------------------------------------------------------------------
    // computeStrategyAddress: input validation. These are pure
    // hashing/prediction paths with no deployment side effects, so they do
    // not depend on MorphoCompounderStrategy's constructor actually
    // succeeding against the mock tokenized-strategy implementation.
    // ---------------------------------------------------------------------

    function test_ComputeStrategyAddress_RevertsOnInvalidVault(address badVault) public {
        vm.assume(badVault != YS_USDC);

        vm.expectRevert(abi.encodeWithSignature("InvalidVault(address,address)", badVault, YS_USDC));
        factory.computeStrategyAddress(
            badVault,
            USDC_MAINNET,
            "Morpho Compounder",
            "mcUSDC",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            false,
            address(tokenizedStrategyImpl),
            address(factory)
        );
    }

    function test_ComputeStrategyAddress_RevertsOnInvalidAsset(address badAsset) public {
        vm.assume(badAsset != USDC_MAINNET);

        vm.expectRevert(abi.encodeWithSignature("InvalidAsset(address,address)", badAsset, USDC_MAINNET));
        factory.computeStrategyAddress(
            YS_USDC,
            badAsset,
            "Morpho Compounder",
            "mcUSDC",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            false,
            address(tokenizedStrategyImpl),
            address(factory)
        );
    }

    function test_ComputeStrategyAddress_VaultCheckedBeforeAsset(address badVault, address badAsset) public {
        vm.assume(badVault != YS_USDC);
        // Even when the asset is *also* wrong, the vault check must fire first.
        vm.expectRevert(abi.encodeWithSignature("InvalidVault(address,address)", badVault, YS_USDC));
        factory.computeStrategyAddress(
            badVault,
            badAsset,
            "Morpho Compounder",
            "mcUSDC",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            false,
            address(tokenizedStrategyImpl),
            address(factory)
        );
    }

    function test_ComputeStrategyAddress_ValidParamsDoNotRevert() public view {
        // Should simply return a prediction, not revert, for well-formed params.
        _predict("Morpho Compounder", address(factory));
    }

    function test_ComputeStrategyAddress_IsDeterministic() public view {
        address predicted1 = _predict("Morpho Compounder", address(factory));
        address predicted2 = _predict("Morpho Compounder", address(factory));
        assertEq(predicted1, predicted2, "prediction should be deterministic for identical params");
    }

    function test_ComputeStrategyAddress_DiffersByName() public view {
        address predictedA = _predict("Strategy A", address(factory));
        address predictedB = _predict("Strategy B", address(factory));
