import { USDC_MAINNET } from "src/constants.sol";

/**
 * @dev Minimal stand-in for the Yearn-V3-style TokenizedStrategy implementation that
 *      `MorphoCompounderStrategy`'s constructor delegatecalls into during initialization.
 *      Its fallback accepts any selector/calldata and returns an empty success payload,
 *      which is sufficient for constructors that gate on `success` alone. This lets us
 *      exercise real end-to-end deployment on a mainnet fork without depending on the
 *      exact initializer signature of the (unseen) TokenizedStrategy implementation.
 */
contract MockTokenizedStrategy {
    fallback() external payable {
        assembly {
            return(0, 0)
        }
    }

    receive() external payable { }
}

contract MorphoCompounderStrategyFactoryTest is Test {
    MorphoCompounderStrategyFactory internal factory;
    MockTokenizedStrategy internal tokenizedStrategyImpl;

    address internal management = makeAddr("management");
