        tokenizedStrategyImpl = new MockTokenizedStrategy();

        vm.label(address(factory), "factory");
        vm.label(address(tokenizedStrategyImpl), "tokenizedStrategyImpl");
        vm.label(EXPECTED_YS_USDC, "YS_USDC");
        vm.label(USDC_MAINNET, "USDC");
