    function test_constants_usdc() public view {
        assertEq(factory.USDC(), USDC_MAINNET, "USDC mismatch");
    }

    // ---------------------------------------------------------------------
    // computeStrategyAddress: input validation
    // ---------------------------------------------------------------------

    function test_computeStrategyAddress_revertsOnInvalidVault() public {
        address wrongVault = makeAddr("wrongVault");

