    function test_createStrategy_wiresUpUnderlyingAsset() public {
        address deployed = _createDefault();

        // Best-effort check: the deployed strategy should ultimately report wstETH as
        // its underlying asset via the tokenized-strategy delegatecall pattern. Wrapped
        // in try/catch so the suite stays robust if the exposed ABI differs.
        try IStrategyView(deployed).asset() returns (address assetAddr) {
