        } catch {
            console2.log("asset() not exposed on deployed strategy; skipping soft check");
        }
    }

    /// forge-config: default.fuzz.runs = 8
    function testFuzz_computeStrategyAddress_matchesActualDeployment(string memory name, string memory symbol) public {
        vm.assume(bytes(name).length > 0 && bytes(name).length < 48);
        vm.assume(bytes(symbol).length > 0 && bytes(symbol).length < 16);

        address predicted = factory.computeStrategyAddress(
            WSTETH, WSTETH, name, symbol, management, keeper, emergencyAdmin, donationAddress, true, TOKENIZED_STRATEGY, address(factory)
        );

        address deployed = factory.createStrategy(name, symbol, management, keeper, emergencyAdmin, donationAddress, true, TOKENIZED_STRATEGY);

