}

/// @dev Concrete harness exercising the abstract BaseStrategyFactory internals.
contract BaseStrategyFactoryHarness is BaseStrategyFactory {
    event StrategyDeploy(address indexed strategy, address indexed deployer, string name);

    struct Params {
        address vault;
        address asset;
        string name;
        string symbol;
        address management;
        address keeper;
        address emergencyAdmin;
        address donationAddress;
        bool enableBurning;
        address tokenizedStrategyAddress;
    }

    function _getBytecode(Params memory p) internal pure returns (bytes memory) {
        return abi.encodePacked(
            type(MockStrategy).creationCode,
            abi.encode(
                p.vault,
                p.asset,
                p.name,
                p.symbol,
                p.management,
                p.keeper,
                p.emergencyAdmin,
                p.donationAddress,
                p.enableBurning,
                p.tokenizedStrategyAddress
            )
        );
    }

    function _hashParams(Params memory p) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                p.vault,
                p.asset,
                p.name,
                p.symbol,
                p.management,
                p.keeper,
                p.emergencyAdmin,
                p.donationAddress,
                p.enableBurning,
                p.tokenizedStrategyAddress
            )
        );
    }

    function computeStrategyAddress(
        address _vault,
        address _asset,
        string memory _name,
        string memory _symbol,
        address _management,
        address _keeper,
        address _emergencyAdmin,
        address _donationAddress,
